INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1449', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-04T14:41:32.317Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may attempt to access the Cloud Instance Metadata API to collect credentials and other sensitive data.\n\nMost cloud service providers support a Cloud Instance Metadata API which is a service provided to running virtual instances that allows applications to access information about the running virtual instance. Available information generally includes name, security group, and additional metadata including sensitive data such as credentials and UserData scripts that may contain additional secrets. The Instance Metadata API is provided as a convenience to assist in managing applications and is accessible by anyone who can access the instance.(Citation: AWS Instance Metadata API)\n\nIf adversaries have a presence on the running virtual instance, they may query the Instance Metadata API directly to identify credentials that grant access to additional resources. Additionally, attackers may exploit a Server-Side Request Forgery (SSRF) vulnerability in a public facing web proxy that allows the attacker to gain access to the sensitive information via a request to the Instance Metadata API.(Citation: RedLock Instance Metadata API 2018)\n\nThe de facto standard across cloud service providers is to host the Instance Metadata API at http[:]//169.254.169.254 .\n", "external_references": [{"external_id": "T1522", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1522"}, {"description": "AWS. (n.d.). Instance Metadata and User Data. Retrieved July 18, 2019.", "source_name": "AWS Instance Metadata API", "url": "https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-instance-metadata.html"}, {"description": "Higashi, Michael. (2018, May 15). Instance Metadata API: A Modern Day Trojan Horse. Retrieved July 16, 2019.", "source_name": "RedLock Instance Metadata API 2018", "url": "https://redlock.io/blog/instance-metadata-api-a-modern-day-trojan-horse"}], "id": "attack-pattern--1c2fd73a-e634-44ed-b1b5-9e7cf7404e9f", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "credential-access"}], "modified": "2025-10-24T17:48:28.695Z", "name": "Cloud Instance Metadata API", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Praetorian"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1449', 0, 276, '09-mitre-attack', 'retrieved', '6CE95E08E916DD3D80BD846ABA9FE9187823A624C427368CF363372A000A6565', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
