INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1480', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-08-28T14:14:18.512Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may communicate using publish/subscribe (pub/sub) application layer protocols to avoid detection/network filtering by blending in with existing traffic. Commands to the remote system, and often the results of those commands, will be embedded within the protocol traffic between the client and server. \n\nProtocols such as MQTT , XMPP , AMQP , and STOMP use a publish/subscribe design, with message distribution managed by a centralized broker.(Citation: wailing crab sub/pub)(Citation: Mandiant APT1 Appendix) Publishers categorize their messages by topics, while subscribers receive messages according to their subscribed topics.(Citation: wailing crab sub/pub) An adversary may abuse publish/subscribe protocols to communicate with systems under their control from behind a message broker while also mimicking normal, expected traffic.", "external_references": [{"external_id": "T1071.005", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1071/005"}, {"description": "Hammond, Charlotte. Villadsen, Ole. Metrick, Kat.. (2023, November 21). Stealthy WailingCrab Malware misuses MQTT Messaging Protocol. Retrieved August 28, 2024.", "source_name": "wailing crab sub/pub", "url": "https://securityintelligence.com/x-force/wailingcrab-malware-misues-mqtt-messaging-protocol/"}, {"description": "Mandiant. (n.d.). Appendix C (Digital) - The Malware Arsenal. Retrieved July 18, 2016.", "source_name": "Mandiant APT1 Appendix", "url": "https://www.mandiant.com/sites/default/files/2021-09/mandiant-apt1-report.pdf"}], "id": "attack-pattern--241f9ea8-f6ae-4f38-92f5-cef5b7e539dd", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "command-and-control"}], "modified": "2025-04-15T19:58:14.152Z", "name": "Publish/Subscribe Protocols", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Domenico Mazzaferro Palmeri", "Sofia Sanchez Margolles"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS", "Linux", "Windows", "Network Devices"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1480', 0, 218, '09-mitre-attack', 'retrieved', 'FCFE4A9824056D190671962DF043D53E4CA261A56B205A8563E46E451C6D5047', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
