VALUES ('doc-09-mitre-attack-p0-1499', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-21T21:15:06.561Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may attempt to find domain-level groups and permission settings. The knowledge of domain-level permission groups can help adversaries determine which groups exist and which users belong to a particular group. Adversaries may use this information to determine which users have elevated permissions, such as domain administrators.\n\nCommands such as net group /domain of the [Net](https://attack.mitre.org/software/S0039) utility, dscacheutil -q group on macOS, and ldapsearch on Linux can list domain-level groups.", "external_references": [{"external_id": "T1069.002", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1069/002"}], "id": "attack-pattern--2aed01ad-3df3-4410-a8cb-11ea4ded587c", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "discovery"}], "modified": "2026-05-12T15:12:00.623Z", "name": "Domain Groups", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Harshal Tupsamudre, Qualys", "Miriam Wiesner, @miriamxyra, Microsoft Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1499', 0, 126, '09-mitre-attack', 'retrieved', '6E4A6819A85CC5A9116A5F2448ECBA5B80F1E59AAF13326289949FCA347638E8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
