INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1503', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-28T17:11:54.034Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may clear system logs to hide evidence of an intrusion. macOS and Linux both keep track of system or user-initiated actions via system logs. The majority of native system logging is stored under the /var/log/ directory. Subfolders in this directory categorize logs by their related functions, such as:(Citation: Linux Logs)\n\n* /var/log/messages: : General and system-related messages\n* /var/log/secure or /var/log/auth.log : Authentication logs\n* /var/log/utmp or /var/log/wtmp : Login records\n* /var/log/kern.log : Kernel logs\n* /var/log/cron.log : Crond logs\n* /var/log/maillog : Mail server logs\n* /var/log/httpd/ : Web server access and error logs\n", "external_references": [{"external_id": "T1070.002", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1070/002"}, {"description": "Marcel. (2018, April 19). 12 Critical Linux Log Files You Must be Monitoring. Retrieved March 29, 2020.", "source_name": "Linux Logs", "url": "https://www.eurovps.com/blog/important-linux-log-files-you-must-be-monitoring/"}], "id": "attack-pattern--2bce5b30-7014-4a5d-ade7-12913fe6ac36", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}], "modified": "2026-04-14T22:54:50.786Z", "name": "Clear Linux or Mac System Logs", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1503', 0, 164, '09-mitre-attack', 'retrieved', '9336ED7BDD7F6BFB6A0CF7981B6716D9E4AAEA824CB6A523994B3006226AB6D7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
