VALUES ('doc-09-mitre-attack-p0-1511', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:31:07.958Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may disable security tools to avoid possible detection of their tools and activities. This can take the form of killing security software or event logging processes, deleting Registry keys so that tools do not start at run time, or other methods to interfere with security scanning or event reporting.", "external_references": [{"external_id": "T1089", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1089"}, {"external_id": "CAPEC-578", "source_name": "capec", "url": "https://capec.mitre.org/data/definitions/578.html"}], "id": "attack-pattern--2e0dd10b-676d-4964-acd0-8a404c92b044", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}], "modified": "2026-04-14T22:53:15.926Z", "name": "Disabling Security Tools", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1511', 0, 105, '09-mitre-attack', 'retrieved', 'B9991A6A39C86783FFCFB62597CB33B45E6AC87CAA52B009702698783BDFF6CA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
