VALUES ('doc-09-mitre-attack-p0-1514', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The Windows Registry stores configuration information that can be used by the system or other programs. Adversaries may query the Registry looking for credentials and passwords that have been stored for use by other programs or services. Sometimes these credentials are used for automatic logons.\n\nExample commands to find Registry keys related to password information: (Citation: Pentestlab Stored Credentials)\n\n* Local Machine Hive: reg query HKLM /f password /t REG_SZ /s \n* Current User Hive: reg query HKCU /f password /t REG_SZ /s ", "external_references": [{"external_id": "T1214", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1214"}, {"description": "netbiosX. (2017, April 19). Stored Credentials. Retrieved April 6, 2018.", "source_name": "Pentestlab Stored Credentials", "url": "https://pentestlab.blog/2017/04/19/stored-credentials/"}], "id": "attack-pattern--2edd9d6a-5674-4326-a600-ba56de467286", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "credential-access"}], "modified": "2025-10-24T17:48:35.620Z", "name": "Credentials in Registry", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Sudhanshu Chauhan, @Sudhanshu_C"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1514', 0, 150, '09-mitre-attack', 'retrieved', '9B886527EA2ACC60F715F9EE08ABA2503B0351EEBC3DE45AD5ECEEEAFC4A3640', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
