INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1534', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T12:58:40.678Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may search the Registry on compromised systems for insecurely stored credentials. The Windows Registry stores configuration information that can be used by the system or other programs. Adversaries may query the Registry looking for credentials and passwords that have been stored for use by other programs or services. Sometimes these credentials are used for automatic logons.\n\nExample commands to find Registry keys related to password information: (Citation: Pentestlab Stored Credentials)\n\n* Local Machine Hive: reg query HKLM /f password /t REG_SZ /s \n* Current User Hive: reg query HKCU /f password /t REG_SZ /s ", "external_references": [{"external_id": "T1552.002", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1552/002"}, {"description": "netbiosX. (2017, April 19). Stored Credentials. Retrieved April 6, 2018.", "source_name": "Pentestlab Stored Credentials", "url": "https://pentestlab.blog/2017/04/19/stored-credentials/"}], "id": "attack-pattern--341e222a-a6e3-4f6f-b69c-831d792b1580", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "credential-access"}], "modified": "2026-05-12T15:12:00.624Z", "name": "Credentials in Registry", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Sudhanshu Chauhan, @Sudhanshu_C"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1534', 0, 162, '09-mitre-attack', 'retrieved', 'ADADE69EC0FBBCBE1A8AC005C301F7C55D5BBB6771215120D4C1BE231AE5CB5A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
