VALUES ('doc-09-mitre-attack-p0-1536', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:31:28.471Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may attempt to gather information about attached peripheral devices and components connected to a computer system.(Citation: Peripheral Discovery Linux)(Citation: Peripheral Discovery macOS) Peripheral devices could include auxiliary resources that support a variety of functionalities such as keyboards, printers, cameras, smart card readers, or removable storage. The information may be used to enhance their awareness of the system and network environment or may be used for further actions.", "external_references": [{"external_id": "T1120", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1120"}, {"description": "Shahriar Shovon. (2018, March). List USB Devices Linux. Retrieved March 11, 2022.", "source_name": "Peripheral Discovery Linux", "url": "https://linuxhint.com/list-usb-devices-linux/"}, {"description": "SS64. (n.d.). system_profiler. Retrieved March 11, 2022.", "source_name": "Peripheral Discovery macOS", "url": "https://ss64.com/osx/system_profiler.html"}], "id": "attack-pattern--348f1eef-964b-4eb6-bb53-69b3dcb0c643", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "discovery"}], "modified": "2026-05-12T15:12:00.624Z", "name": "Peripheral Device Discovery", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-1536', 0, 150, '09-mitre-attack', 'retrieved', '01BB3C0E04AB0EFA6C2740FE7AC547404A2E607311B0945DEBEE3090B2B3F569', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1537', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-27T19:49:40.815Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An adversary may attempt to evade process tree-based analysis by modifying executed malware''s parent process ID (PPID). If endpoint protection software leverages the “parent-child\" relationship for detection, breaking this relationship could result in the adversary’s behavior not being associated with previous process tree activity. On Unix-based systems breaking this process tree is common practice for administrators to execute software using scripts and programs.(Citation: 3OHA double-fork 2022) \n\nOn Linux systems, adversaries may execute a series of [Native API](https://attack.mitre.org/techniques/T1106) calls to alter malware''s process tree. For example, adversaries can execute their payload without any arguments, call the `fork()` API call twice, then have the parent process exit. This creates a grandchild process with no parent process that is immediately adopted by the `init` system process (PID 1), which successfully disconnects the execution of the adversary''s payload from its previous process tree.\n\nAnother example is using the “daemon” syscall to detach from the current parent process and run in the background.(Citation: Sandfly BPFDoor 2022)(Citation: Microsoft XorDdos Linux Stealth 2022) ", "external_references": [{"external_id": "T1036.009", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1036/009"}, {"description": "Juan Tapiador. (2022, April 11). UNIX daemonization and the double fork. Retrieved September 29, 2023.", "source_name": "3OHA double-fork 2022", "url": "https://0xjet.github.io/3OHA/2022/04/11/post.html"}, {"description": "Microsoft Threat Intelligence. (2022, May 19). Rise in XorDdos: A deeper look at the stealthy DDoS malware targeting Linux devices. Retrieved September 27, 2023.", "source_name": "Microsoft XorDdos Linux Stealth 2022", "url": "https://www.microsoft.com/en-us/security/blog/2022/05/19/rise-in-xorddos-a-deeper-look-at-the-stealthy-ddos-malware-targeting-linux-devices/"}, {"description": "The Sandfly Security Team. (2022, May 11). BPFDoor - An Evasive Linux Backdoor Technical Analysis. Retrieved September 29, 2023.", "source_name": "Sandfly BPFDoor 2022", "url": "https://sandflysecurity.com/blog/bpfdoor-an-evasive-linux-backdoor-technical-analysis/"}], "id": "attack-pattern--34a80bc4-80f2-46e6-94ff-f3265a4b657c", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}], "modified": "2026-05-12T15:12:00.625Z", "name": "Break Process Trees", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Tim (Wadhwa-)Brown"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1537', 0, 298, '09-mitre-attack', 'retrieved', '8A3E95B77231B0AC2E024A1D9475BE6749BD836676F731CEB3240733BE5BF21B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
