VALUES ('doc-09-mitre-attack-p0-1542', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-14T22:54:02.368Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An adversary may disable or modify cloud logging capabilities and integrations to limit what data is collected on their activities and avoid detection. Cloud environments allow for collection and analysis of audit and application logs that provide insight into what activities a user does within the environment. If an adversary has sufficient permissions, they can disable or modify logging to avoid detection of their activities. \n\nFor example, in AWS an adversary may disable CloudWatch/CloudTrail integrations prior to conducting further malicious activity. They may alternatively tamper with logging functionality, for example, by removing any associated SNS topics, disabling multi-region logging, or disabling settings that validate and/or encrypt log files.(Citation: AWS Cloud Trail)(Citation: Pacu Detection Disruption Module) In Office 365, an adversary may disable logging on mail collection activities for specific users by using the Set-MailboxAuditBypassAssociation cmdlet, by disabling M365 Advanced Auditing for the user, or by downgrading the user’s license from an Enterprise E5 to an Enterprise E3 license.(Citation: Dark Reading)", "external_references": [{"external_id": "T1685.002", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1685/002"}, {"description": "AWS. (n.d.). update-trail. Retrieved April 15, 2026.", "source_name": "AWS Cloud Trail", "url": "https://docs.aws.amazon.com/cli/latest/reference/cloudtrail/update-trail.html"}, {"description": "Kelly Sheridan. (2021, August 5). Retrieved April 15, 2026.", "source_name": "Dark Reading", "url": "https://www.darkreading.com/threat-intelligence/incident-responders-explore-microsoft-365-attacks-in-the-wild"}, {"description": "Rhino Security Labs. (2021, April 29). Pacu Detection Disruption Module. Retrieved August 4, 2023.", "source_name": "Pacu Detection Disruption Module", "url": "https://github.com/RhinoSecurityLabs/pacu/blob/master/pacu/modules/detection__disruption/main.py"}], "id": "attack-pattern--34ff60a3-a3f8-42e4-bed0-af9a2cb563d7", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "defense-impairment"}], "modified": "2026-05-12T15:12:00.625Z", "name": "Disable or Modify Cloud Log", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Alex Soler, AttackIQ", "Arun Seelagan, CISA", "Ibrahim Ali Khan", "Janantha Marasinghe", "Joe Gumke, U.S. Bank", "Matt Snyder, VMware", "Prasad Somasamudram, McAfee", "Sekhar Sarukkai, McAfee", "Syed Ummar Farooqh, McAfee"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["IaaS", "SaaS", "Identity Provider", "Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-1542', 0, 294, '09-mitre-attack', 'retrieved', 'D92549C65CC577B88D8F2A95F07F6270F7AA3C2876376C6589CA03A38F5491BA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
