INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1605', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may bypass process and/or signature-based defenses by proxying execution of malicious content with signed, or otherwise trusted, binaries. Binaries used in this technique are often Microsoft-signed files, indicating that they have been either downloaded from Microsoft or are already native in the operating system.(Citation: LOLBAS Project) Binaries signed with trusted digital certificates can typically execute on Windows systems protected by digital signature validation. Several Microsoft signed binaries that are default on Windows installations can be used to proxy execution of other files or commands.\n\nSimilarly, on Linux systems adversaries may abuse trusted binaries such as split to proxy execution of malicious commands.(Citation: split man page)(Citation: GTFO split)", "external_references": [{"external_id": "T1218", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1218"}, {"description": "GTFOBins. (2020, November 13). split. Retrieved April 18, 2022.", "source_name": "GTFO split", "url": "https://gtfobins.github.io/gtfobins/split/"}, {"description": "Oddvar Moe et al. (2022, February). Living Off The Land Binaries, Scripts and Libraries. Retrieved March 7, 2022.", "source_name": "LOLBAS Project", "url": "https://github.com/LOLBAS-Project/LOLBAS#criteria"}, {"description": "Torbjorn Granlund, Richard M. Stallman. (2020, March null). split(1) — Linux manual page. Retrieved March 25, 2022.", "source_name": "split man page", "url": "https://man7.org/linux/man-pages/man1/split.1.html"}], "id": "attack-pattern--457c7820-d331-465a-915e-42f85500ccc4", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}], "modified": "2026-05-12T15:12:00.629Z", "name": "System Binary Proxy Execution", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Hans Christoffer Gaardløs", "Nishan Maharjan, @loki248", "Praetorian", "Wes Hurd"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "4.0"}', 'kb-doc-09-mitre-attack-p0-1605', 0, 230, '09-mitre-attack', 'retrieved', '5C82E5DA0557A72B92DFB570EF63F8CA1D01CBD1E2576E1BF736290DF5AD6E9B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
