INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1614', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-08-24T17:23:34.470Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may evade defensive mechanisms by executing commands that hide from process interrupt signals. Many operating systems use signals to deliver messages to control process behavior. Command interpreters often include specific commands/flags that ignore errors and other hangups, such as when the user of the active session logs off.(Citation: Linux Signal Man) These interrupt signals may also be used by defensive tools and/or analysts to pause or terminate specified running processes. \n\nAdversaries may invoke processes using `nohup`, [PowerShell](https://attack.mitre.org/techniques/T1059/001) `-ErrorAction SilentlyContinue`, or similar commands that may be immune to hangups.(Citation: nohup Linux Man)(Citation: Microsoft PowerShell SilentlyContinue) This may enable malicious commands and malware to continue execution through system events that would otherwise terminate its execution, such as users logging off or the termination of its C2 network connection.\n\nHiding from process interrupt signals may allow malware to continue execution, but unlike [Trap](https://attack.mitre.org/techniques/T1546/005) this does not establish [Persistence](https://attack.mitre.org/tactics/TA0003) since the process will not be re-invoked once actually terminated.", "external_references": [{"external_id": "T1564.011", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1564/011"}, {"description": "Linux man-pages. (2023, April 3). signal(7). Retrieved August 30, 2023.", "source_name": "Linux Signal Man", "url": "https://man7.org/linux/man-pages/man7/signal.7.html"}, {"description": "Meyering, J. (n.d.). nohup(1). Retrieved August 30, 2023.", "source_name": "nohup Linux Man", "url": "https://linux.die.net/man/1/nohup"}, {"description": "Microsoft. (2023, March 2). $DebugPreference. Retrieved August 30, 2023.", "source_name": "Microsoft PowerShell SilentlyContinue", "url": "https://learn.microsoft.com/powershell/module/microsoft.powershell.core/about/about_preference_variables?view=powershell-7.3#debugpreference"}], "id": "attack-pattern--4a2975db-414e-4c0c-bd92-775987514b4b", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}], "modified": "2026-05-12T15:12:00.630Z", "name": "Ignore Process Interrupts", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Viren Chaudhari, Qualys"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS", "Windows"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1614', 0, 256, '09-mitre-attack', 'retrieved', '6759A569EB8B7884FDBA735E76F44D0546BD60A8A82B701359F49C11538EDA42', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
