VALUES ('doc-09-mitre-attack-p0-1671', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-08T17:51:41.390Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may modify visual content available internally or externally to an enterprise network, thus affecting the integrity of the original content. Reasons for [Defacement](https://attack.mitre.org/techniques/T1491) include delivering messaging, intimidation, or claiming (possibly false) credit for an intrusion. Disturbing or offensive images may be used as a part of [Defacement](https://attack.mitre.org/techniques/T1491) in order to cause user discomfort, or to pressure compliance with accompanying messages. \n", "external_references": [{"external_id": "T1491", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1491"}], "id": "attack-pattern--5909f20f-3c39-4795-be06-ef1ea40d350b", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "impact"}], "modified": "2025-10-24T17:48:49.761Z", "name": "Defacement", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_impact_type": ["Integrity"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows", "IaaS", "Linux", "macOS", "ESXi"], "x_mitre_version": "1.4"}', 'kb-doc-09-mitre-attack-p0-1671', 0, 111, '09-mitre-attack', 'retrieved', '88CF4710D1B82CA19E4B42CD1CF097AA3E9DE14DA452318698DCD325066B6BCA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1672', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-04T14:35:04.617Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may create cloud instances in unused geographic service regions in order to evade detection. Access is usually obtained through compromising accounts used to manage cloud infrastructure.\n\nCloud service providers often provide infrastructure throughout the world in order to improve performance, provide redundancy, and allow customers to meet compliance requirements. Oftentimes, a customer will only use a subset of the available regions and may not actively monitor other regions. If an adversary creates resources in an unused region, they may be able to operate undetected.\n\nA variation on this behavior takes advantage of differences in functionality across cloud regions. An adversary could utilize regions which do not support advanced detection services in order to avoid detection of their activity.\n\nAn example of adversary use of unused AWS regions is to mine cryptocurrency through [Resource Hijacking](https://attack.mitre.org/techniques/T1496), which can cost organizations substantial amounts of money over time depending on the processing power used.(Citation: CloudSploit - Unused AWS Regions)", "external_references": [{"external_id": "T1535", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1535"}, {"description": "CloudSploit. (2019, June 8). The Danger of Unused AWS Regions. Retrieved October 8, 2019.", "source_name": "CloudSploit - Unused AWS Regions", "url": "https://medium.com/cloudsploit/the-danger-of-unused-aws-regions-af0bf1b878fc"}], "id": "attack-pattern--59bd0dec-f8b2-4b9a-9141-37a1e6899761", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}], "modified": "2026-05-12T15:12:00.635Z", "name": "Unused/Unsupported Cloud Regions", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Netskope"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["IaaS"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1672', 0, 225, '09-mitre-attack', 'retrieved', 'F1FE986AC0B9D2403C794FD2FB2B6050BBB6783DEF0C5240B48B908DF7C5BA04', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
