INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1691', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T14:17:43.906Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may establish persistence by executing malicious content triggered by an interrupt signal. The trap command allows programs and shells to specify commands that will be executed upon receiving interrupt signals. A common situation is a script allowing for graceful termination and handling of common keyboard interrupts like ctrl+c and ctrl+d .\n\nAdversaries can use this to register code to be executed when the shell encounters specific interrupts as a persistence mechanism. Trap commands are of the following format trap ''command list'' signals where \"command list\" will be executed when \"signals\" are received.(Citation: Trap Manual)(Citation: Cyberciti Trap Statements)", "external_references": [{"external_id": "T1546.005", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1546/005"}, {"description": "ss64. (n.d.). trap. Retrieved May 21, 2019.", "source_name": "Trap Manual", "url": "https://ss64.com/bash/trap.html"}, {"description": "Cyberciti. (2016, March 29). Trap statement. Retrieved May 21, 2019.", "source_name": "Cyberciti Trap Statements", "url": "https://bash.cyberciti.biz/guide/Trap_statement"}], "id": "attack-pattern--63220765-d418-44de-8fae-694b3912317d", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "privilege-escalation"}, {"kill_chain_name": "mitre-attack", "phase_name": "persistence"}], "modified": "2025-10-24T17:48:51.725Z", "name": "Trap", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["macOS", "Linux"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1691', 0, 175, '09-mitre-attack', 'retrieved', '058307B91DE2602979C7F758F305799FF9962CB40D70715916CF5438B478A912', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1692', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-13T20:09:59.569Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may execute their own malicious payloads by hijacking environment variables the dynamic linker uses to load shared libraries. During the execution preparation phase of a program, the dynamic linker loads specified absolute paths of shared libraries from various environment variables and files, such as LD_PRELOAD on Linux or DYLD_INSERT_LIBRARIES on macOS.(Citation: TheEvilBit DYLD_INSERT_LIBRARIES)(Citation: Timac DYLD_INSERT_LIBRARIES)(Citation: Gabilondo DYLD_INSERT_LIBRARIES Catalina Bypass) Libraries specified in environment variables are loaded first, taking precedence over system libraries with the same function name.(Citation: Man LD.SO)(Citation: TLDP Shared Libraries)(Citation: Apple Doco Archive Dynamic Libraries) Each platform''s linker uses an extensive list of environment variables at different points in execution. These variables are often used by developers to debug binaries without needing to recompile, deconflict mapped symbols, and implement custom functions in the original library.(Citation: Baeldung LD_PRELOAD)\n\nHijacking dynamic linker variables may grant access to the victim process''s memory, system/network resources, and possibly elevated privileges. On Linux, adversaries may set LD_PRELOAD to point to malicious libraries that match the name of legitimate libraries which are requested by a victim program, causing the operating system to load the adversary''s malicious code upon execution of the victim program. For example, adversaries have used `LD_PRELOAD` to inject a malicious library into every descendant process of the `sshd` daemon, resulting in execution under a legitimate process. When the executing sub-process calls the `execve` function, for example, the malicious library’s `execve` function is executed rather than the system function `execve` contained in the system library on disk. This allows adversaries to [Hide Artifacts](https://attack.mitre.org/techniques/T1564) from detection, as hooking system functions such as `execve` and `readdir` enables malware to scrub its own artifacts from the results of commands such as `ls`, `ldd`, `iptables`, and `dmesg`.(Citation: ESET Ebury Oct 2017)(Citation: Intezer Symbiote 2022)(Citation: Elastic Security Labs Pumakit 2024)\n\nHijacking dynamic linker variables may grant access to the victim process''s memory, system/network resources, and possibly elevated privileges.", "external_references": [{"external_id": "T1574.006", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1574/006"}, {"description": "Apple Inc.. (2012, July 23). Overview of Dynamic Libraries. Retrieved March 24, 2021.", "source_name": "Apple Doco Archive Dynamic Libraries", "url": "https://developer.apple.com/library/archive/documentation/DeveloperTools/Conceptual/DynamicLibraries/100-Articles/OverviewOfDynamicLibraries.html"}, {"description": "baeldung. (2020, August 9). What Is the LD_PRELOAD Trick?. Retrieved March 24, 2021.", "source_name": "Baeldung LD_PRELOAD", "url": "https://www.baeldung.com/linux/ld_preload-trick-what-is"}, {"description": "Fitzl, C. (2019, July 9). DYLD_INSERT_LIBRARIES DYLIB injection in macOS / OSX. Retrieved March 26, 2020.", "source_name": "TheEvilBit DYLD_INSERT_LIBRARIES", "url": "https://theevilbit.github.io/posts/dyld_insert_libraries_dylib_injection_in_macos_osx_deep_dive/"}, {"description": "Joakim Kennedy and The BlackBerry Threat Research & Intelligence Team. (2022, June 9). Symbiote Deep-Dive: Analysis of a New, Nearly-Impossible-to-Detect Linux Threat. Retrieved March 24, 2025.", "source_name": "Intezer Symbiote 2022", "url": "https://intezer.com/blog/research/new-linux-threat-symbiote/"}, {"description": "Jon Gabilondo. (2019, September 22). How to Inject Code into Mach-O Apps. Part II.. Retrieved March 24, 2021.", "source_name": "Gabilondo DYLD_INSERT_LIBRARIES Catalina Bypass", "url": "https://jon-gabilondo-angulo-7635.medium.com/how-to-inject-code-into-mach-o-apps-part-ii-ddb13ebc8191"}, {"description": "Kerrisk, M. (2020, June 13). Linux Programmer''s Manual. Retrieved June 15, 2020.", "source_name": "Man LD.SO", "url": "https://www.man7.org/linux/man-pages/man8/ld.so.8.html"}, {"description": "Remco Sprooten and Ruben Groenewoud. (2024, December 11). Declawing PUMAKIT. Retrieved March 24, 2025.", "source_name": "Elastic Security Labs Pumakit 2024", "url": "https://www.elastic.co/security-labs/declawing-pumakit"}, {"description": "The Linux Documentation Project. (n.d.). Shared Libraries. Retrieved January 31, 2020.", "source_name": "TLDP Shared Libraries", "url": "https://www.tldp.org/HOWTO/Program-Library-HOWTO/shared-libraries.html"}, {"description": "Timac. (2012, December 18). Simple code injection using DYLD_INSERT_LIBRARIES. Retrieved March 26, 2020.", "source_name": "Timac DYLD_INSERT_LIBRARIES", "url": "https://blog.timac.org/2012/1218-simple-code-injection-using-dyld_insert_libraries/"}, {"description": "Vachon, F. (2017, October 30). Windigo Still not Windigone: An Ebury Update . Retrieved February 10, 2021.", "source_name": "ESET Ebury Oct 2017", "url": "https://www.welivesecurity.com/2017/10/30/windigo-ebury-update-2/"}], "id": "attack-pattern--633a100c-b2c9-41bf-9be5-905c1b16c825", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}, {"kill_chain_name": "mitre-attack", "phase_name": "execution"}], "modified": "2026-05-12T15:12:00.636Z", "name": "Dynamic Linker Hijacking", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS"], "x_mitre_remote_support": false, "x_mitre_version": "3.0"}', 'kb-doc-09-mitre-attack-p0-1692', 0, 588, '09-mitre-attack', 'retrieved', 'E5F72694BA8CCCCCE93CB2BA3EAE755510255CD643372EAB30C9DA347806FA97', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
