VALUES ('doc-09-mitre-attack-p0-1697', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-28T17:05:14.707Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may clear Windows Event Logs to hide the activity of an intrusion. Windows Event Logs are a record of a computer''s alerts and notifications. There are three system-defined sources of events: System, Application, and Security, with five event types: Error, Warning, Information, Success Audit, and Failure Audit.\n\n\nWith administrator privileges, the event logs can be cleared with the following utility commands:\n\n* wevtutil cl system \n* wevtutil cl application \n* wevtutil cl security \n\nThese logs may also be cleared through other mechanisms, such as the event viewer GUI or [PowerShell](https://attack.mitre.org/techniques/T1059/001). For example, adversaries may use the PowerShell command Remove-EventLog -LogName Security to delete the Security EventLog and after reboot, disable future logging. Note: events may still be generated and logged in the .evtx file between the time the command is run and the reboot.(Citation: disable_win_evt_logging)\n\nAdversaries may also attempt to clear logs by directly deleting the stored log files within `C:\\Windows\\System32\\winevt\\logs\\`.", "external_references": [{"external_id": "T1070.001", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1070/001"}, {"description": "Heiligenstein, L. (n.d.). REP-25: Disable Windows Event Logging. Retrieved April 7, 2022.", "source_name": "disable_win_evt_logging", "url": "https://ptylu.github.io/content/report/report.html?report=25"}, {"description": "Microsoft. (n.d.). Clear-EventLog. Retrieved July 2, 2018.", "source_name": "Microsoft Clear-EventLog", "url": "https://docs.microsoft.com/powershell/module/microsoft.powershell.management/clear-eventlog"}, {"description": "Microsoft. (n.d.). EventLog.Clear Method (). Retrieved July 2, 2018.", "source_name": "Microsoft EventLog.Clear", "url": "https://msdn.microsoft.com/library/system.diagnostics.eventlog.clear.aspx"}, {"description": "Plett, C. et al.. (2017, October 16). wevtutil. Retrieved July 2, 2018.", "source_name": "Microsoft wevtutil Oct 2017", "url": "https://docs.microsoft.com/windows-server/administration/windows-commands/wevtutil"}], "id": "attack-pattern--6495ae23-3ab4-43c5-a94f-5638a2c31fd2", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}], "modified": "2026-04-14T22:54:48.496Z", "name": "Clear Windows Event Logs", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Lucas Heiligenstein"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.5"}', 'kb-doc-09-mitre-attack-p0-1697', 0, 265, '09-mitre-attack', 'retrieved', 'D211FA88F1488F194DC20E8788180C711F322CF98BC12C42C7416F9578E2F8EB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
