VALUES ('doc-09-mitre-attack-p0-1714', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:30:42.222Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "When a file is opened, the default program used to open the file (also called the file association or handler) is checked. File association selections are stored in the Windows Registry and can be edited by users, administrators, or programs that have Registry access (Citation: Microsoft Change Default Programs) (Citation: Microsoft File Handlers) or by administrators using the built-in assoc utility. (Citation: Microsoft Assoc Oct 2017) Applications can modify the file association for a given file extension to call an arbitrary program when a file with the given extension is opened.\n\nSystem file associations are listed under HKEY_CLASSES_ROOT\\.[extension] , for example HKEY_CLASSES_ROOT\\.txt . The entries point to a handler for that extension located at HKEY_CLASSES_ROOT\\[handler] . The various commands are then listed as subkeys underneath the shell key at HKEY_CLASSES_ROOT\\[handler]\\shell\\[action]\\command . For example:\n* HKEY_CLASSES_ROOT\\txtfile\\shell\\open\\command \n* HKEY_CLASSES_ROOT\\txtfile\\shell\\print\\command \n* HKEY_CLASSES_ROOT\\txtfile\\shell\\printto\\command \n\nThe values of the keys listed are commands that are executed when the handler opens the file extension. Adversaries can modify these values to continually execute arbitrary commands. (Citation: TrendMicro TROJ-FAKEAV OCT 2012)", "external_references": [{"external_id": "T1042", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1042"}, {"external_id": "CAPEC-556", "source_name": "capec", "url": "https://capec.mitre.org/data/definitions/556.html"}, {"description": "Microsoft. (n.d.). Change which programs Windows 7 uses by default. Retrieved July 26, 2016.", "source_name": "Microsoft Change Default Programs", "url": "https://support.microsoft.com/en-us/help/18539/windows-7-change-default-programs"}, {"description": "Microsoft. (n.d.). Specifying File Handlers for File Name Extensions. Retrieved November 13, 2014.", "source_name": "Microsoft File Handlers", "url": "http://msdn.microsoft.com/en-us/library/bb166549.aspx"}, {"description": "Plett, C. et al.. (2017, October 15). assoc. Retrieved August 7, 2018.", "source_name": "Microsoft Assoc Oct 2017", "url": "https://docs.microsoft.com/windows-server/administration/windows-commands/assoc"}, {"description": "Sioting, S. (2012, October 8). TROJ_FAKEAV.GZD. Retrieved August 8, 2018.", "source_name": "TrendMicro TROJ-FAKEAV OCT 2012", "url": "https://www.trendmicro.com/vinfo/us/threat-encyclopedia/malware/troj_fakeav.gzd"}], "id": "attack-pattern--68c96494-1a50-403e-8844-69a6af278c68", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "persistence"}], "modified": "2025-10-24T17:48:53.818Z", "name": "Change Default File Association", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Stefan Kanthak", "Travis Smith, Tripwire"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-1714', 0, 310, '09-mitre-attack', 'retrieved', '1C70374AFAC502A4526C00BEFDF487D15806DF88906545087FB9B118988A8FA9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1715', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:31:26.966Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Regsvr32.exe is a command-line program used to register and unregister object linking and embedding controls, including dynamic link libraries (DLLs), on Windows systems. Regsvr32.exe can be used to execute arbitrary binaries. (Citation: Microsoft Regsvr32)\n\nAdversaries may take advantage of this functionality to proxy execution of code to avoid triggering security tools that may not monitor execution of, and modules loaded by, the regsvr32.exe process because of whitelists or false positives from Windows using regsvr32.exe for normal operations. Regsvr32.exe is also a Microsoft signed binary.\n\nRegsvr32.exe can also be used to specifically bypass process whitelisting using functionality to load COM scriptlets to execute DLLs under user permissions. Since regsvr32.exe is network and proxy aware, the scripts can be loaded by passing a uniform resource locator (URL) to file on an external Web server as an argument during invocation. This method makes no changes to the Registry as the COM object is not actually registered, only executed. (Citation: LOLBAS Regsvr32) This variation of the technique is often referred to as a \"Squiblydoo\" attack and has been used in campaigns targeting governments. (Citation: Carbon Black Squiblydoo Apr 2016) (Citation: FireEye Regsvr32 Targeting Mongolian Gov)\n\nRegsvr32.exe can also be leveraged to register a COM Object used to establish Persistence via [Component Object Model Hijacking](https://attack.mitre.org/techniques/T1122). (Citation: Carbon Black Squiblydoo Apr 2016)", "external_references": [{"external_id": "T1117", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1117"}, {"description": "Microsoft. (2015, August 14). How to use the Regsvr32 tool and troubleshoot Regsvr32 error messages. Retrieved June 22, 2016.", "source_name": "Microsoft Regsvr32", "url": "https://support.microsoft.com/en-us/kb/249873"}, {"description": "LOLBAS. (n.d.). Regsvr32.exe. Retrieved July 31, 2019.", "source_name": "LOLBAS Regsvr32", "url": "https://lolbas-project.github.io/lolbas/Binaries/Regsvr32/"}, {"description": "Nolen, R. et al.. (2016, April 28). Threat Advisory: “Squiblydoo” Continues Trend of Attackers Using Native OS Tools to “Live off the Land”. Retrieved April 9, 2018.", "source_name": "Carbon Black Squiblydoo Apr 2016", "url": "https://www.carbonblack.com/2016/04/28/threat-advisory-squiblydoo-continues-trend-of-attackers-using-native-os-tools-to-live-off-the-land/"}, {"description": "Anubhav, A., Kizhakkinan, D. (2017, February 22). Spear Phishing Techniques Used in Attacks Targeting the Mongolian Government. Retrieved February 24, 2017.", "source_name": "FireEye Regsvr32 Targeting Mongolian Gov", "url": "https://www.fireeye.com/blog/threat-research/2017/02/spear_phishing_techn.html"}], "id": "attack-pattern--68f7e3a1-f09f-4164-9a62-16b648a0dd5a", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}, {"kill_chain_name": "mitre-attack", "phase_name": "execution"}], "modified": "2026-04-14T22:53:15.259Z", "name": "Regsvr32", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Casey Smith"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1715', 0, 369, '09-mitre-attack', 'retrieved', 'F2DFC401BD32A96FB4CE9DB7323FB72A6A779A1DDD4E2374491F183C7E611E45', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
