VALUES ('doc-09-mitre-attack-p0-1790', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:30:58.938Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may stage collected data in a central location or directory prior to Exfiltration. Data may be kept in separate files or combined into one file through techniques such as [Archive Collected Data](https://attack.mitre.org/techniques/T1560). Interactive command shells may be used, and common functionality within [cmd](https://attack.mitre.org/software/S0106) and bash may be used to copy data into a staging location.(Citation: PWC Cloud Hopper April 2017)\n\nIn cloud environments, adversaries may stage data within a particular instance or virtual machine before exfiltration. An adversary may [Create Cloud Instance](https://attack.mitre.org/techniques/T1578/002) and stage data in that instance.(Citation: Mandiant M-Trends 2020)\n\nAdversaries may choose to stage data from a victim network in a centralized location prior to Exfiltration to minimize the number of connections made to their C2 server and better evade detection.", "external_references": [{"external_id": "T1074", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1074"}, {"description": "Mandiant. (2020, February). M-Trends 2020. Retrieved November 17, 2024.", "source_name": "Mandiant M-Trends 2020", "url": "https://www.mandiant.com/sites/default/files/2021-09/mtrends-2020.pdf"}, {"description": "PwC and BAE Systems. (2017, April). Operation Cloud Hopper. Retrieved April 5, 2017.", "source_name": "PWC Cloud Hopper April 2017", "url": "https://web.archive.org/web/20220224041316/https:/www.pwc.co.uk/cyber-security/pdf/cloud-hopper-report-final-v4.pdf"}], "id": "attack-pattern--7dd95ff6-712e-4056-9626-312ea4ab4c5e", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "collection"}], "modified": "2026-05-12T15:12:00.645Z", "name": "Data Staged", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Praetorian", "Shane Tully, @securitygypsy"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["ESXi", "IaaS", "Linux", "macOS", "Windows"], "x_mitre_version": "1.5"}', 'kb-doc-09-mitre-attack-p0-1790', 0, 215, '09-mitre-attack', 'retrieved', '833136541894C9B7FD4DC942E1E8F15A4D72C7FA74205530645C0446581E047B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
