INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1799', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-30T17:54:03.944Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may build a container image directly on a host to bypass defenses that monitor for the retrieval of malicious images from a public registry. A remote build request may be sent to the Docker API that includes a Dockerfile that pulls a vanilla base image, such as alpine, from a public or local registry and then builds a custom image upon it.(Citation: Docker Build Image)\n\nAn adversary may take advantage of that build API to build a custom image on the host that includes malware downloaded from their C2 server, and then they may utilize [Deploy Container](https://attack.mitre.org/techniques/T1610) using that custom image.(Citation: Aqua Build Images on Hosts)(Citation: Aqua Security Cloud Native Threat Report June 2021) If the base image is pulled from a public registry, defenses will likely not detect the image as malicious since it’s a vanilla image. If the base image already resides in a local registry, the pull may be considered even less suspicious since the image is already in the environment. ", "external_references": [{"external_id": "T1612", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1612"}, {"description": "Assaf Morag. (2020, July 15). Threat Alert: Attackers Building Malicious Images on Your Hosts. Retrieved March 29, 2021.", "source_name": "Aqua Build Images on Hosts", "url": "https://blog.aquasec.com/malicious-container-image-docker-container-host"}, {"description": "Docker. ( null). Docker Engine API v1.41 Reference - Build an Image. Retrieved March 30, 2021.", "source_name": "Docker Build Image", "url": "https://docs.docker.com/engine/api/v1.41/#operation/ImageBuild"}, {"description": "Team Nautilus. (2021, June). Attacks in the Wild on the Container Supply Chain and Infrastructure. Retrieved August 26, 2021.", "source_name": "Aqua Security Cloud Native Threat Report June 2021", "url": "https://info.aquasec.com/hubfs/Threat%20reports/AquaSecurity_Cloud_Native_Threat_Report_2021.pdf?utm_campaign=WP%20-%20Jun2021%20Nautilus%202021%20Threat%20Research%20Report&utm_medium=email&_hsmi=132931006&_hsenc=p2ANqtz-_8oopT5Uhqab8B7kE0l3iFo1koirxtyfTehxF7N-EdGYrwk30gfiwp5SiNlW3G0TNKZxUcDkYOtwQ9S6nNVNyEO-Dgrw&utm_content=132931006&utm_source=hs_automation"}], "id": "attack-pattern--800f9819-7007-4540-a520-40e655876800", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}], "modified": "2026-05-12T15:12:00.662Z", "name": "Build Image on Host", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_contributors": ["Assaf Morag, @MoragAssaf, Team Nautilus Aqua Security", "Roi Kol, @roykol1, Team Nautilus Aqua Security", "Michael Katchinskiy, @michael64194968, Team Nautilus Aqua Security", "Vishwas Manral, McAfee"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Containers"], "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-1799', 0, 319, '09-mitre-attack', 'retrieved', 'A740AFC2036CCB1CC71EB930D1863B952CE7602AC7BF0E1B63DCFDFD03F12FA7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
