INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-1899', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-12T17:50:31.584Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may abuse systemd timers to perform task scheduling for initial or recurring execution of malicious code. Systemd timers are unit files with file extension .timer that control services. Timers can be set to run on a calendar event or after a time span relative to a starting point. They can be used as an alternative to [Cron](https://attack.mitre.org/techniques/T1053/003) in Linux environments.(Citation: archlinux Systemd Timers Aug 2020) Systemd timers may be activated remotely via the systemctl command line utility, which operates over [SSH](https://attack.mitre.org/techniques/T1021/004).(Citation: Systemd Remote Control)\n\nEach .timer file must have a corresponding .service file with the same name, e.g., example.timer and example.service . .service files are [Systemd Service](https://attack.mitre.org/techniques/T1543/002) unit files that are managed by the systemd system and service manager.(Citation: Linux man-pages: systemd January 2014) Privileged timers are written to /etc/systemd/system/ and /usr/lib/systemd/system while user level are written to ~/.config/systemd/user/ .\n\nAn adversary may use systemd timers to execute malicious code at system startup or on a scheduled basis for persistence.(Citation: Arch Linux Package Systemd Compromise BleepingComputer 10JUL2018)(Citation: gist Arch package compromise 10JUL2018)(Citation: acroread package compromised Arch Linux Mail 8JUL2018) Timers installed using privileged paths may be used to maintain root level persistence. Adversaries may also install user level timers to achieve user level persistence.(Citation: Falcon Sandbox smp: 28553b3a9d)", "external_references": [{"external_id": "T1053.006", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1053/006"}, {"description": "Aaron Kili. (2018, January 16). How to Control Systemd Services on Remote Linux Server. Retrieved July 26, 2021.", "source_name": "Systemd Remote Control", "url": "https://www.tecmint.com/control-systemd-services-on-remote-linux-server/"}, {"description": "archlinux. (2020, August 11). systemd/Timers. Retrieved October 12, 2020.", "source_name": "archlinux Systemd Timers Aug 2020", "url": "https://wiki.archlinux.org/index.php/Systemd/Timers"}, {"description": "Catalin Cimpanu. (2018, July 10). ~x file downloaded in public Arch package compromise. Retrieved April 23, 2019.", "source_name": "gist Arch package compromise 10JUL2018", "url": "https://gist.github.com/campuscodi/74d0d2e35d8fd9499c76333ce027345a"}, {"description": "Catalin Cimpanu. (2018, July 10). Malware Found in Arch Linux AUR Package Repository. Retrieved April 23, 2019.", "source_name": "Arch Linux Package Systemd Compromise BleepingComputer 10JUL2018", "url": "https://www.bleepingcomputer.com/news/security/malware-found-in-arch-linux-aur-package-repository/"}, {"description": "Eli Schwartz. (2018, June 8). acroread package compromised. Retrieved April 23, 2019.", "source_name": "acroread package compromised Arch Linux Mail 8JUL2018", "url": "https://lists.archlinux.org/pipermail/aur-general/2018-July/034153.html"}, {"description": "Hybrid Analysis. (2018, July 11). HybridAnalsysis of sample 28553b3a9d2ad4361d33d29ac4bf771d008e0073cec01b5561c6348a608f8dd7. Retrieved September 8, 2023.", "source_name": "Falcon Sandbox smp: 28553b3a9d", "url": "https://www.hybrid-analysis.com/sample/28553b3a9d2ad4361d33d29ac4bf771d008e0073cec01b5561c6348a608f8dd7?environmentId=300"}, {"description": "Linux man-pages. (2014, January). systemd(1) - Linux manual page. Retrieved April 23, 2019.", "source_name": "Linux man-pages: systemd January 2014", "url": "http://man7.org/linux/man-pages/man1/systemd.1.html"}], "id": "attack-pattern--a542bac9-7bc1-4da7-9a09-96f69e23cc21", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "execution"}, {"kill_chain_name": "mitre-attack", "phase_name": "persistence"}, {"kill_chain_name": "mitre-attack", "phase_name": "privilege-escalation"}], "modified": "2025-10-24T17:49:11.261Z", "name": "Systemd Timers", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["SarathKumar Rajendran, Trimble Inc"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": true, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux"], "x_mitre_remote_support": false, "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-1899', 0, 431, '09-mitre-attack', 'retrieved', 'D3DE9C763B6351E2DD5148CF97C90814CB1D7DA6CE3D52DE0E2BBB4C3F1C9173', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
