VALUES ('doc-09-mitre-attack-p0-1942', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The trap command allows programs and shells to specify commands that will be executed upon receiving interrupt signals. A common situation is a script allowing for graceful termination and handling of common keyboard interrupts like ctrl+c and ctrl+d . Adversaries can use this to register code to be executed when the shell encounters specific interrupts either to gain execution or as a persistence mechanism. Trap commands are of the following format trap ''command list'' signals where \"command list\" will be executed when \"signals\" are received.(Citation: Trap Manual)(Citation: Cyberciti Trap Statements)", "external_references": [{"external_id": "T1154", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1154"}, {"description": "ss64. (n.d.). trap. Retrieved May 21, 2019.", "source_name": "Trap Manual", "url": "https://ss64.com/bash/trap.html"}, {"description": "Cyberciti. (2016, March 29). Trap statement. Retrieved May 21, 2019.", "source_name": "Cyberciti Trap Statements", "url": "https://bash.cyberciti.biz/guide/Trap_statement"}], "id": "attack-pattern--b53dbcc6-147d-48bb-9df4-bcb8bb808ff6", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "execution"}, {"kill_chain_name": "mitre-attack", "phase_name": "persistence"}], "modified": "2025-10-24T17:49:15.696Z", "name": "Trap", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Linux", "macOS"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-1942', 0, 170, '09-mitre-attack', 'retrieved', 'A169ECBD5AE38E9A085B3DADD38BBC39256DE646DE0B3296A640D5896801C85E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
