INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2002', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:30:33.723Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Windows Remote Management (WinRM) is the name of both a Windows service and a protocol that allows a user to interact with a remote system (e.g., run an executable, modify the Registry, modify services). (Citation: Microsoft WinRM) It may be called with the winrm command or by any number of programs such as PowerShell. (Citation: Jacobsen 2014)", "external_references": [{"external_id": "T1028", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1028"}, {"external_id": "CAPEC-555", "source_name": "capec", "url": "https://capec.mitre.org/data/definitions/555.html"}, {"description": "Microsoft. (n.d.). Windows Remote Management. Retrieved November 12, 2014.", "source_name": "Microsoft WinRM", "url": "http://msdn.microsoft.com/en-us/library/aa384426"}, {"description": "Jacobsen, K. (2014, May 16). Lateral Movement with PowerShell[slides]. Retrieved November 12, 2014.", "source_name": "Jacobsen 2014", "url": "https://www.slideshare.net/kieranjacobsen/lateral-movement-with-power-shell-2"}, {"description": "French, D. (2018, September 30). Detecting Lateral Movement Using Sysmon and Splunk. Retrieved October 11, 2019.", "source_name": "Medium Detecting Lateral Movement", "url": "https://medium.com/threatpunter/detecting-lateral-movement-using-sysmon-and-splunk-318d3be141bc"}], "id": "attack-pattern--c3bce4f4-9795-46c6-976e-8676300bbc39", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "execution"}, {"kill_chain_name": "mitre-attack", "phase_name": "lateral-movement"}], "modified": "2025-10-24T17:49:20.857Z", "name": "Windows Remote Management", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.2"}', 'kb-doc-09-mitre-attack-p0-2002', 0, 172, '09-mitre-attack', 'retrieved', 'D6E5DBF8B08BE2756EF1637E7092A96AF9A9150F370725CF689ED5CEDBD1AC75', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
