INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2108', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-16T17:52:44.147Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may attempt to get a listing of software and software versions that are installed on a system or in a cloud environment. Adversaries may use the information from [Software Discovery](https://attack.mitre.org/techniques/T1518) during automated discovery to shape follow-on behaviors, including whether or not the adversary fully infects the target and/or attempts specific actions.\n\nSuch software may be deployed widely across the environment for configuration management or security reasons, such as [Software Deployment Tools](https://attack.mitre.org/techniques/T1072), and may allow adversaries broad access to infect devices or move laterally.\n\nAdversaries may attempt to enumerate software for a variety of reasons, such as figuring out what security measures are present or if the compromised system has a version of software that is vulnerable to [Exploitation for Privilege Escalation](https://attack.mitre.org/techniques/T1068).", "external_references": [{"external_id": "T1518", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1518"}], "id": "attack-pattern--e3b6daca-e963-4a69-aee6-ed4fd653ad58", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "discovery"}], "modified": "2026-05-12T15:12:00.723Z", "name": "Software Discovery", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["ESXi", "IaaS", "Linux", "macOS", "Windows"], "x_mitre_version": "1.5"}', 'kb-doc-09-mitre-attack-p0-2108', 0, 170, '09-mitre-attack', 'retrieved', '61DF62FF4775CC48C19AB5B9EA4B4B472F81A58D9B82C6443CB322EF5582D578', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2109', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-08-30T18:11:24.582Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An adversary may use a cloud service dashboard GUI with stolen credentials to gain useful information from an operational cloud environment, such as specific services, resources, and features. For example, the GCP Command Center can be used to view all assets, review findings of potential security risks, and run additional queries, such as finding public IP addresses and open ports.(Citation: Google Command Center Dashboard)\n\nDepending on the configuration of the environment, an adversary may be able to enumerate more information via the graphical dashboard than an API. This also allows the adversary to gain information without manually making any API requests.", "external_references": [{"external_id": "T1538", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1538"}, {"description": "Amazon. (n.d.). AWS Console Sign-in Events. Retrieved October 23, 2019.", "source_name": "AWS Console Sign-in Events", "url": "https://docs.aws.amazon.com/awscloudtrail/latest/userguide/cloudtrail-event-reference-aws-console-sign-in-events.html"}, {"description": "Google. (2019, October 3). Quickstart: Using the dashboard. Retrieved October 8, 2019.", "source_name": "Google Command Center Dashboard", "url": "https://cloud.google.com/security-command-center/docs/quickstart-scc-dashboard"}], "id": "attack-pattern--e49920b0-6c54-40c1-9571-73723653205f", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "discovery"}], "modified": "2025-10-24T17:49:32.022Z", "name": "Cloud Service Dashboard", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Praetorian", "Obsidian Security"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["IaaS", "SaaS", "Office Suite", "Identity Provider"], "x_mitre_version": "1.5"}', 'kb-doc-09-mitre-attack-p0-2109', 0, 194, '09-mitre-attack', 'retrieved', '0816D424EE2E78674F48173491F5F1D0E01112190F0219E473328431E5B9198C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
