INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2122', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:31:38.350Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries may remove share connections that are no longer useful in order to clean up traces of their operation. Windows shared drive and [Windows Admin Shares](https://attack.mitre.org/techniques/T1077) connections can be removed when no longer needed. [Net](https://attack.mitre.org/software/S0039) is an example utility that can be used to remove network share connections with the net use \\\\system\\share /delete command. (Citation: Technet Net Use)\n\n", "external_references": [{"external_id": "T1126", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1126"}, {"description": "Microsoft. (n.d.). Net Use. Retrieved November 25, 2016.", "source_name": "Technet Net Use", "url": "https://technet.microsoft.com/bb490717.aspx"}], "id": "attack-pattern--e7eab98d-ae11-4491-bd28-a53ba875865a", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}], "modified": "2026-04-14T22:53:15.777Z", "name": "Network Share Connection Removal", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-2122', 0, 122, '09-mitre-attack', 'retrieved', 'E834BB1B0306329FF14A32DD240F7101B61908032C06DC86961D8A279C041E51', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
