VALUES ('doc-09-mitre-attack-p0-2178', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:31:27.510Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "InstallUtil is a command-line utility that allows for installation and uninstallation of resources by executing specific installer components specified in .NET binaries. (Citation: MSDN InstallUtil) InstallUtil is located in the .NET directories on a Windows system: C:\\Windows\\Microsoft.NET\\Framework\\v \\InstallUtil.exe and C:\\Windows\\Microsoft.NET\\Framework64\\v \\InstallUtil.exe . InstallUtil.exe is digitally signed by Microsoft.\n\nAdversaries may use InstallUtil to proxy execution of code through a trusted Windows utility. InstallUtil may also be used to bypass process whitelisting through use of attributes within the binary that execute the class decorated with the attribute [System.ComponentModel.RunInstaller(true)] . (Citation: LOLBAS Installutil)", "external_references": [{"external_id": "T1118", "source_name": "mitre-attack", "url": "https://attack.mitre.org/techniques/T1118"}, {"description": "Microsoft. (n.d.). Installutil.exe (Installer Tool). Retrieved July 1, 2016.", "source_name": "MSDN InstallUtil", "url": "https://msdn.microsoft.com/en-us/library/50614e95.aspx"}, {"description": "LOLBAS. (n.d.). Installutil.exe. Retrieved July 31, 2019.", "source_name": "LOLBAS Installutil", "url": "https://lolbas-project.github.io/lolbas/Binaries/Installutil/"}], "id": "attack-pattern--f792d02f-813d-402b-86a5-ab98cb391d3b", "kill_chain_phases": [{"kill_chain_name": "mitre-attack", "phase_name": "stealth"}, {"kill_chain_name": "mitre-attack", "phase_name": "execution"}], "modified": "2026-04-14T22:53:15.873Z", "name": "InstallUtil", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": true, "spec_version": "2.1", "type": "attack-pattern", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_contributors": ["Casey Smith", "Travis Smith, Tripwire"], "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_is_subtechnique": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.3"}', 'kb-doc-09-mitre-attack-p0-2178', 0, 173, '09-mitre-attack', 'retrieved', 'D36563196A887DAEC929DD024A5209C0C48C649251B7AE1F62C9B3A33D811908', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
