INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2203', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Below are the tactics and techniques representing the MITRE ATT&CK Matrix for Enterprise. The Matrix contains information for the following platforms: Windows, macOS, Linux, PRE, Office Suite, Identity Provider, SaaS, IaaS, Network Devices, Containers, ESXi.", "external_references": [{"external_id": "enterprise-attack", "source_name": "mitre-attack", "url": "https://attack.mitre.org/matrices/enterprise"}], "id": "x-mitre-matrix--eafc1b4c-5e56-4965-bd4e-66a6a89c88cc", "modified": "2026-07-31T18:48:31.315Z", "name": "Enterprise ATT&CK", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "tactic_refs": ["x-mitre-tactic--daa4cbb1-b4f4-4723-a824-7f1efd6e0592", "x-mitre-tactic--d679bca2-e57d-4935-8650-8031c87a4400", "x-mitre-tactic--ffd5bcee-6e16-4dd2-8eca-7b3beedf33ca", "x-mitre-tactic--4ca45d45-df4d-4613-8980-bac22d278fa5", "x-mitre-tactic--5bc1d813-693e-4823-9961-abf9af4b0e92", "x-mitre-tactic--5e29b093-294e-49e9-a803-dab3d73b77dd", "x-mitre-tactic--78b23412-0651-46d7-a540-170a1ce8bd5a", "x-mitre-tactic--43c49635-f2fa-44f2-92b9-0ee980bbf4ef", "x-mitre-tactic--2558fd61-8c75-4730-94c4-11926db2a263", "x-mitre-tactic--c17c5845-175e-4421-9713-829d0573dbc9", "x-mitre-tactic--7141578b-e50b-4dcc-bfa4-08a8dd689e9e", "x-mitre-tactic--d108ce10-2419-4cf9-a774-46161d6c6cfe", "x-mitre-tactic--f72804c5-f15a-449e-a5da-2eecd181f813", "x-mitre-tactic--9a4e74ab-5008-408c-84bf-a10dfbc53462", "x-mitre-tactic--5569339b-94c2-49ee-afb3-2222936582c8"], "type": "x-mitre-matrix", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_version": "2.0"}', 'kb-doc-09-mitre-attack-p0-2203', 0, 88, '09-mitre-attack', 'retrieved', 'AC08773ABE4479D0256E6A40E7183916CECBCCAD33974F047E9DBC0518936F6C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
