INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2211', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary is trying to hide and conceal their actions, appearing as normal behavior.\n\nStealth consists of techniques that reduce the likelihood of detection by blending in with legitimate activity or minimizing observable signals. These techniques are characterized by concealment behaviors, such as avoiding, obfuscating, or mimicking normal operations, without modifying security controls or compromising collection and monitoring feeds. The goal is to remain indistinguishable from benign activity while leaving defensive systems intact.", "external_references": [{"external_id": "TA0005", "source_name": "mitre-attack", "url": "https://attack.mitre.org/tactics/TA0005"}], "id": "x-mitre-tactic--78b23412-0651-46d7-a540-170a1ce8bd5a", "modified": "2026-05-12T15:12:00.780Z", "name": "Stealth", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-tactic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_shortname": "stealth", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2211', 0, 110, '09-mitre-attack', 'retrieved', '95AF4E6270BBE37BF64DB13C2870B08EF14D15268CFFE03E00BDD3A18EE7D108', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2212', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary is trying to steal data.\n\nExfiltration consists of techniques that adversaries may use to steal data from your network. Once they’ve collected data, adversaries often package it to avoid detection while removing it. This can include compression and encryption. Techniques for getting data out of a target network typically include transferring it over their command and control channel or an alternate channel and may also include putting size limits on the transmission.", "external_references": [{"external_id": "TA0010", "source_name": "mitre-attack", "url": "https://attack.mitre.org/tactics/TA0010"}], "id": "x-mitre-tactic--9a4e74ab-5008-408c-84bf-a10dfbc53462", "modified": "2025-04-25T14:45:34.933Z", "name": "Exfiltration", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-tactic", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_shortname": "exfiltration", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2212', 0, 109, '09-mitre-attack', 'retrieved', '1E637F265093A001179D98F63F49B5DCA8ECBB65ECEBC3C88898DD85536B6E98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2213', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary is trying to figure out your environment.\n\nDiscovery consists of techniques an adversary may use to gain knowledge about the system and internal network. These techniques help adversaries observe the environment and orient themselves before deciding how to act. They also allow adversaries to explore what they can control and what’s around their entry point in order to discover how it could benefit their current objective. Native operating system tools are often used toward this post-compromise information-gathering objective. ", "external_references": [{"external_id": "TA0007", "source_name": "mitre-attack", "url": "https://attack.mitre.org/tactics/TA0007"}], "id": "x-mitre-tactic--c17c5845-175e-4421-9713-829d0573dbc9", "modified": "2025-04-25T14:45:35.302Z", "name": "Discovery", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-tactic", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_shortname": "discovery", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2213', 0, 116, '09-mitre-attack', 'retrieved', '3AF13C7A097E031A10D56DF344B87BD05D1BDCC7D1FFDB7DB161430A2BF2154D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2214', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary is trying to gather data of interest to their goal.\n\nCollection consists of techniques adversaries may use to gather information and the sources information is collected from that are relevant to following through on the adversary''s objectives. Frequently, the next goal after collecting data is to either steal (exfiltrate) the data or to use the data to gain more information about the target environment. Common target sources include various drive types, browsers, audio, video, and email. Common collection methods include capturing screenshots and keyboard input.", "external_references": [{"external_id": "TA0009", "source_name": "mitre-attack", "url": "https://attack.mitre.org/tactics/TA0009"}], "id": "x-mitre-tactic--d108ce10-2419-4cf9-a774-46161d6c6cfe", "modified": "2024-09-05T18:27:09.070Z", "name": "Collection", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-tactic", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_shortname": "collection", "x_mitre_version": "1.1"}', 'kb-doc-09-mitre-attack-p0-2214', 0, 124, '09-mitre-attack', 'retrieved', 'E785FA84AD239C3293A3C73DC4DBC27232DCD60EDF3BF2D5B3E642A70A269C83', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2215', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-09-30T16:11:59.650Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary is trying to establish resources they can use to support operations.\n\nResource Development consists of techniques that involve adversaries creating, purchasing, or compromising/stealing resources that can be used to support targeting. Such resources include infrastructure, accounts, or capabilities. These resources can be leveraged by the adversary to aid in other phases of the adversary lifecycle, such as using purchased domains to support Command and Control, email accounts for phishing as a part of Initial Access, or stealing code signing certificates to help with Defense Evasion.", "external_references": [{"external_id": "TA0042", "source_name": "mitre-attack", "url": "https://attack.mitre.org/tactics/TA0042"}], "id": "x-mitre-tactic--d679bca2-e57d-4935-8650-8031c87a4400", "modified": "2025-04-25T14:45:35.841Z", "name": "Resource Development", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-tactic", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_shortname": "resource-development", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2215', 0, 123, '09-mitre-attack', 'retrieved', 'E788EDC254C7A2031D9D4BBD3A46E77D1414151C47E651E935AAAF72E9AA8B77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2216', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-02T14:48:41.809Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary is trying to gather information they can use to plan future operations.\n\nReconnaissance consists of techniques that involve adversaries actively or passively gathering information that can be used to support targeting. Such information may include details of the victim organization, infrastructure, or staff/personnel. This information can be leveraged by the adversary to aid in other phases of the adversary lifecycle, such as using gathered information to plan and execute Initial Access, to scope and prioritize post-compromise objectives, or to drive and lead further Reconnaissance efforts.", "external_references": [{"external_id": "TA0043", "source_name": "mitre-attack", "url": "https://attack.mitre.org/tactics/TA0043"}], "id": "x-mitre-tactic--daa4cbb1-b4f4-4723-a824-7f1efd6e0592", "modified": "2025-04-25T14:45:36.201Z", "name": "Reconnaissance", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-tactic", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_shortname": "reconnaissance", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2216', 0, 122, '09-mitre-attack', 'retrieved', '13B0782423DB753B76C9C2D3004694D403ACE3DA91DC06F52E2C47FF012695AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2217', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary is trying to communicate with compromised systems to control them.\n\nCommand and Control consists of techniques that adversaries may use to communicate with systems under their control within a victim network. Adversaries commonly attempt to mimic normal, expected traffic to avoid detection. There are many ways an adversary can establish command and control with various levels of stealth depending on the victim’s network structure and defenses.", "external_references": [{"external_id": "TA0011", "source_name": "mitre-attack", "url": "https://attack.mitre.org/tactics/TA0011"}], "id": "x-mitre-tactic--f72804c5-f15a-449e-a5da-2eecd181f813", "modified": "2025-04-25T14:45:36.561Z", "name": "Command and Control", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-tactic", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_shortname": "command-and-control", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2217', 0, 105, '09-mitre-attack', 'retrieved', '2D2339E63E010A61B1DEFDA2BCED64A5CBAE5D8847EA5FC11A38D4420B8BA951', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2218', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary is trying to get into your network.\n\nInitial Access consists of techniques that use various entry vectors to gain their initial foothold within a network. Techniques used to gain a foothold include targeted spearphishing and exploiting weaknesses on public-facing web servers. Footholds gained through initial access may allow for continued access, like valid accounts and use of external remote services, or may be limited-use due to changing passwords.", "external_references": [{"external_id": "TA0001", "source_name": "mitre-attack", "url": "https://attack.mitre.org/tactics/TA0001"}], "id": "x-mitre-tactic--ffd5bcee-6e16-4dd2-8eca-7b3beedf33ca", "modified": "2025-04-25T14:45:36.917Z", "name": "Initial Access", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-tactic", "x_mitre_attack_spec_version": "3.2.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_shortname": "initial-access", "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2218', 0, 106, '09-mitre-attack', 'retrieved', 'EBA6E96B7FCBA69223C08E771DED6127D7907194037A6744E23E37F6B48CF70C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2219', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor /var/log/audit/audit.log and DNS resolver logs for repeated failed lookups or connections to high-entropy domain names. Correlate suspicious DNS queries with process lineage (e.g., Python, bash, or unusual system daemons).", "external_references": [{"external_id": "AN0110", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0039#AN0110"}], "id": "x-mitre-analytic--00112bcc-174f-4201-ac81-fe3edd1292e6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0110", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket/connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Query to suspicious domain with high entropy or low reputation", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelist/blacklist tuned with external threat intel sources", "field": "DomainReputationFeed"}, {"description": "Known safe daemons that frequently query domains", "field": "ProcessWhitelist"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2219', 0, 110, '09-mitre-attack', 'retrieved', '0F02618D4CDD77352824D4F899EAFF1C52DA59B1FA6EE76C81D26AA903AD22C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2220', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of Linux container escape attempts via syscalls (`unshare`, `keyctl`, `mount`) or process execution outside container namespaces. Defenders may correlate unusual system calls from containerized processes with subsequent process creation on the host or modification of host resources.", "external_references": [{"external_id": "AN0613", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0219#AN0613"}], "id": "x-mitre-analytic--0021ecae-778a-4726-aa66-1cf4ca01943e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0613", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "unshare, mount, keyctl, setns syscalls executed by containerized processes", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "process creation events linked to container namespaces executing host-level binaries", "name": "linux:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected syscalls by containerized workloads. Deviations may signal an escape attempt.", "field": "SyscallWhitelist"}, {"description": "Defines correlation window (e.g., 60s) between suspicious syscalls and follow-on host process activity.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2220', 0, 136, '09-mitre-attack', 'retrieved', 'F2B063878E6798EA460159F7D2B35815661E4E5810510DEC55D1D44965B8E43C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
