INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2221', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The adversary invokes built-in scripting or decoding tools like base64, plutil, or AppleScript-based utilities to decode files embedded in staging artifacts. Decoding often occurs post-download or as part of post-exploitation payload deployment via zsh, python, or osascript.", "external_references": [{"external_id": "AN0769", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0275#AN0769"}], "id": "x-mitre-analytic--0029e7e7-d42c-4a91-8d00-6bf6fd72962f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0769", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "base64 -d or osascript invoked on staged file", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Could involve base64, osascript, python, perl, or plutil", "field": "DecodeInterpreter"}, {"description": "Deobfuscation may happen within GUI app context or LaunchAgent/Daemon", "field": "ExecutionContext"}, {"description": "May differ depending on local user, root escalation, or persistence method", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2221', 0, 126, '09-mitre-attack', 'retrieved', '791239589F8E822C8BBDE51B1F59F1887EF9F89947D4A75FB1FAD7D5FB6F36A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
