VALUES ('doc-09-mitre-attack-p0-2222', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of packed Mach-O binaries unpacking into memory and transferring control to dynamically modified code segments.", "external_references": [{"external_id": "AN0068", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0023#AN0068"}], "id": "x-mitre-analytic--003c2ca3-a9a8-4a56-9163-f6733f19b41d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0068", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process::exec", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ES_EVENT_MMAP", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Helps to distinguish between signed/unsigned packed binaries (common in legitimate vs. malicious cases).", "field": "SignedBinaryContext"}, {"description": "Can be used to scope to specific users or service accounts targeted in attacks.", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2222', 0, 100, '09-mitre-attack', 'retrieved', 'F08D22091C31F7BF85DBD3A36138AC4DBF7630106A3141A549B54DC1C39D5A4A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
