INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2223', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of commands that stop or kill processes associated with logging or security daemons (auditd, syslog, falco). Detect modifications to iptables or disabling SELinux/AppArmor enforcement. Correlate sudo/root context with abrupt service halts.", "external_references": [{"external_id": "AN0887", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0317#AN0887"}], "id": "x-mitre-analytic--003dd2ae-b156-4ebd-8a59-76f993056552", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0887", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "systemctl stop auditd, kill -9 , or modifications to /etc/selinux/config", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "kill syscalls targeting logging/security processes", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}, {"channel": "iptables or nftables rule changes", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust monitored security service names depending on host configuration.", "field": "ServiceList"}, {"description": "Correlate multiple kill/stop events in short succession.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2223', 0, 128, '09-mitre-attack', 'retrieved', '191E4F23BF511598D68CEB36CDE8DFC29F5724B000FCA791C6B5D26D4C1E8F54', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
