VALUES ('doc-09-mitre-attack-p0-2225', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of vulnerable kernel extensions or entitlements abused via setuid or AppleScript injection chains.", "external_references": [{"external_id": "AN1421", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0514#AN1421"}], "id": "x-mitre-analytic--0066bac9-599a-4f7b-a667-9cb1dca94347", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1421", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process:exec and kext load events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ES_EVENT_TYPE_NOTIFY_KEXTLOAD", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Entitlements vary by app and OS version; some allow unexpected behavior.", "field": "EntitlementList"}, {"description": "Correlate SUID execution or AppleScript injection with privilege gain or module load.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2225', 0, 99, '09-mitre-attack', 'retrieved', 'C6B95430B64BE638B2365D3153F621A608D9FD21BC9C64D3D3D4F7C3AD030CD5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
