VALUES ('doc-09-mitre-attack-p0-2226', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Sudden valid logins from accounts that previously had credentials dumped but had not authenticated successfully in the past; correlated with timeline of suspected hash cracking", "external_references": [{"external_id": "AN0295", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0105#AN0295"}], "id": "x-mitre-analytic--0084089f-6e5f-42c4-8b0d-78e95cd55d0f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0295", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Success logs from high-risk accounts", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection window after credential dumping to watch for successful logins", "field": "PostDumpTimeWindow"}, {"description": "Use IP/geolocation risk scoring to flag unusual access", "field": "LoginLocationRisk"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2226', 0, 99, '09-mitre-attack', 'retrieved', '812389A8B01E7885EB46F01C8BD58FE269B624C4B105530EE24C1EDE9BDE56B2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
