INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2227', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious sign-ins to Graph API or sensitive resources using non-browser scripting agents (e.g., Python, PowerShell), often for programmatic access to mailbox or OneDrive content.", "external_references": [{"external_id": "AN0534", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0186#AN0534"}], "id": "x-mitre-analytic--00b2801f-752e-4b70-95fd-c2644ccef671", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0534", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Operation=UserLogin", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter for scripting agents (e.g., Python, PowerShell) which may vary by org.", "field": "UserAgentFilter"}, {"description": "Set of known internal or managed IPs to filter benign automation.", "field": "ExpectedClientIPList"}, {"description": "Expected managed device profiles used to detect unmanaged devices.", "field": "DeviceProperties"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2227', 0, 110, '09-mitre-attack', 'retrieved', 'CDD37A32FC29A9AC92A453E4D2FCBAB5CC4524D0A2164D7BBDFD3305C1495E77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
