INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2228', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "User modification of the $PATH environment variable in shell configuration files or direct runtime PATH changes, followed by execution of binaries from user-controlled directories. Defender observes file edits to ~/.bashrc, ~/.profile, or /etc/paths.d and process execution resolving to unexpected binary locations.", "external_references": [{"external_id": "AN0010", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0004#AN0010"}], "id": "x-mitre-analytic--00b5d9a8-a794-4d7c-90df-71c4021e0a46", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0010", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/write calls modifying ~/.bashrc, ~/.profile, or /etc/paths.d", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Execution of binary resolved from $PATH not located in /usr/bin or /bin", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set of shell startup files where PATH changes should be flagged.", "field": "MonitoredShellConfigs"}, {"description": "Directories (e.g., /usr/local/bin) considered safe to avoid FP.", "field": "AllowedUserBins"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2228', 0, 134, '09-mitre-attack', 'retrieved', 'F95DBFDD4FEF55147F56A40163D6D1E4B5263B212E5B9690F455FAB167AA916E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
