VALUES ('doc-09-mitre-attack-p0-2229', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Flood of incoming TLS or HTTP(S) connections to macOS-hosted services (e.g., MAMP, Apache), causing high CPU usage and system unresponsiveness.", "external_references": [{"external_id": "AN0491", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0173#AN0491"}], "id": "x-mitre-analytic--00bf6b2e-444a-4a83-aafd-43bc8eea4594", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0491", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Web service process (e.g., httpd) entering crash loop or consuming excessive CPU", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "Rapid incoming TLS handshakes or HTTP requests in quick succession", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Number of renegotiations per minute considered suspicious", "field": "TLSHandshakeRate"}, {"description": "Threshold of crashes before alerting on instability", "field": "ServiceCrashFrequency"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2229', 0, 111, '09-mitre-attack', 'retrieved', 'D898C75F438776E4BC7F43E1842380DA1F2A62A5860D5A2356E88DA148EFB5CB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
