VALUES ('doc-09-mitre-attack-p0-2230', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary uses ''esxcli software vib list'' to enumerate installed VIBs, drivers, and modules.", "external_references": [{"external_id": "AN1104", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0392#AN1104"}], "id": "x-mitre-analytic--0119786d-ee1e-4857-b31a-3a43830e28e7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1104", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "esxcli software vib list", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Host daemon command log entries related to vib enumeration", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection may vary based on whether enumeration is local or remote.", "field": "HostAccessMode"}, {"description": "Presence of enumeration in broader scripted sequence.", "field": "ScriptChain"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2230', 0, 99, '09-mitre-attack', 'retrieved', 'A0F2E0DBEF56571EAFDAE5C1BB043D08C538076AAC356E76DD62C4F830F2E43C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
