VALUES ('doc-09-mitre-attack-p0-2232', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of hcitool, bluetoothctl, or rfcomm to initialize Bluetooth connection paired with recent file reads by the same user or session.", "external_references": [{"external_id": "AN1532", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0554#AN1532"}], "id": "x-mitre-analytic--01588556-4b25-4418-b746-9bca0279be2c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1532", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "None", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "None", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of CLI tools to monitor (e.g., hcitool, rfcomm, obexftp).", "field": "BluetoothUtility"}, {"description": "Amount of time after interface config a file must be accessed to be linked.", "field": "SessionWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2232', 0, 108, '09-mitre-attack', 'retrieved', 'FCBD5A25D4148544885E27CCDD8121CD204ADE4EBF3A1FDE7D121BE155923079', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
