VALUES ('doc-09-mitre-attack-p0-2233', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary gains access to cloud-hosted services such as AWS SES, SNS, or OpenAI API, enables or modifies usage policies, and initiates resource-intensive actions (e.g., mass email/SMS or LLM queries), often from unauthorized regions or under anomalous identity conditions.", "external_references": [{"external_id": "AN0417", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0147#AN0417"}], "id": "x-mitre-analytic--01967eb2-5169-4113-aff0-ac2180fd14d9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0417", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "PutIdentityPolicy", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "SendEmail", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "AssumeRole", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define threshold period over which request spikes are measured. E.g., 10 min or 1 hour windows.", "field": "TimeWindow"}, {"description": "Alert only if role/user is outside expected automation identity list.", "field": "UserContext"}, {"description": "Customize the number of emails/SMS or API calls considered anomalous.", "field": "RequestVolumeThreshold"}, {"description": "Tune geolocation jump logic (e.g., login from US, then use service in Asia within minutes).", "field": "GeoVelocityThreshold"}, {"description": "Set maximum allowable deviation from past 7-day average OpenAI/GPT token usage.", "field": "ModelUsageQuotaSpike"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2233', 0, 172, '09-mitre-attack', 'retrieved', 'F564F5AFCFF92CD010A21A1342BE25345135867E7D3D3DEABA70EFF7991C021A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
