VALUES ('doc-09-mitre-attack-p0-2234', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects staged data aggregated in /Users/Shared, /private/tmp with compression tools like ditto or zip, initiated via Terminal or AppleScript.", "external_references": [{"external_id": "AN0726", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0261#AN0726"}], "id": "x-mitre-analytic--01a3cc24-df78-4ff7-8a25-67545d830229", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0726", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "exec logs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Shared dirs commonly abused for local collection", "field": "StagingTargets"}, {"description": "zip, tar, ditto", "field": "CompressionBinaries"}, {"description": "Seconds/minutes between source file read and output staging write", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2234', 0, 100, '09-mitre-attack', 'retrieved', '5B20CE85DF5E31E8B0AA80BF1BD33F98B6739A09EB25BE6880984B4D52E054D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
