VALUES ('doc-09-mitre-attack-p0-2235', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects PowerShell `Clear-History` invocation or deletion of `ConsoleHost_history.txt` to erase past PowerShell session history.", "external_references": [{"external_id": "AN0469", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0165#AN0469"}], "id": "x-mitre-analytic--01b79770-a269-4b4d-bf09-a4760bae9c94", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0469", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=23", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path to PSReadLine file, typically in APPDATA.", "field": "HistoryFilePath"}, {"description": "User account or role performing deletion (e.g., low-priv user deleting history).", "field": "UserContext"}, {"description": "Support detection of `Clear-History` and variations.", "field": "CommandPattern"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2235', 0, 109, '09-mitre-attack', 'retrieved', '23719211B716A057930EA491F29CB8B14E