VALUES ('doc-09-mitre-attack-p0-2236', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process loads a shared object (.so) via dlopen/LD_PRELOAD/open from non-standard or temporary locations (e.g., /tmp, /dev/shm), especially shortly after that .so is written or fetched, or linked via manipulated environment variables (LD_PRELOAD/LD_LIBRARY_PATH).", "external_references": [{"external_id": "AN0053", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0018#AN0053"}], "id": "x-mitre-analytic--01c969ef-7057-44bd-bced-9b64a98234ec", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0053", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "openat/read/mmap: Open/mmap .so files from non-standard paths", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "execve: Processes launched with LD_PRELOAD/LD_LIBRARY_PATH pointing to non-system dirs", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "sudo or service accounts invoking loaders with suspicious env vars", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "http/file-xfer: Inbound/outbound transfer of ELF shared objects", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "(/tmp, /dev/shm, /var/tmp, user home dirs) – adjust to your environment.", "field": "SuspiciousDirs"}, {"description": "Correlate write/fetch of .so to its load (e.g., 0–30 minutes).", "field": "TimeWindow"}, {"description": "LD_PRELOAD, LD_LIBRARY_PATH, LD_AUDIT.", "field": "EnvVarWatchlist"}, {"description": "Known-good signed or hashed shared objects.", "field": "AllowedSigning/HashList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2236', 0, 167, '09-mitre-attack', 'retrieved', '7FD2609900982A167C3CCA160DAA09CC382B73B7AA6024384C6D6DD1370F26A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
