VALUES ('doc-09-mitre-attack-p0-2237', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Access to local credential/config files (e.g., ~/.aws/credentials) followed by metadata API calls or cloud role assumptions.", "external_references": [{"external_id": "AN0860", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0307#AN0860"}], "id": "x-mitre-analytic--01d19202-019e-43c9-a5e9-e1e2a38eb738", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0860", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "sensitive credential files in buckets or local image storage", "name": "CloudTrail:GetObject", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "command-line execution invoking credential enumeration", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "sudden role assumption after credential file access", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex to match common credential files (e.g., *.aws/credentials, token.txt)", "field": "CredentialFilePattern"}, {"description": "Adjust scope of roles monitored (e.g., admin, service accounts)", "field": "RoleAssumptionScope"}, {"description": "Correlation timing between file access and AssumeRole", "field": "TimeWindow"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2237', 0, 125, '09-mitre-attack', 'retrieved', '77E19A789C691C6365E69A3B9E8C38EF4F669E1E078754FEB56508C7E48041D4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
