VALUES ('doc-09-mitre-attack-p0-2238', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates interface mode changes to promiscuous with execution of sniffing tools like tcpdump, tshark, or custom pcap libraries. Detects abnormal NIC configurations and unauthorized sniffing from non-root sessions.", "external_references": [{"external_id": "AN0876", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0314#AN0876"}], "id": "x-mitre-analytic--01ef3337-0585-4eaa-acb2-df363f7d5463", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0876", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve, setifflags", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "promiscuous mode transitions (ioctl or ifconfig)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "interface flag PROMISC, netstat | ip link | ethtool", "name": "networkconfig ", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Limit analysis to external interfaces (e.g., eth0, wlan0) and exclude virtual adapters.", "field": "InterfaceList"}, {"description": "Raise alerts if interface remains in PROMISC longer than threshold duration.", "field": "PromiscuousSessionThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2238', 0, 129, '09-mitre-attack', 'retrieved', 'FD2FADB86314F634983FCDDD361B2CF8C05989ECEBD0A7C7C333FE58EA4E8600', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
