VALUES ('doc-09-mitre-attack-p0-2239', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary modifies or replaces the Terminal Services DLL (`termsrv.dll`) or changes the associated `ServiceDll` Registry value to load an arbitrary or patched DLL that enables persistent and enhanced RDP access. This may include binary replacement, registry tampering, and unexpected module loads by the `svchost.exe -k termsvcs` process.", "external_references": [{"external_id": "AN0595", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0212#AN0595"}], "id": "x-mitre-analytic--01f18cc1-2948-4ea7-adaf-017da939b9ff", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0595", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4657", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defenders may tune for non-standard DLLs loaded by svchost.exe or termsrv.exe processes.", "field": "TargetDLLPath"}, {"description": "Environment-specific variations in the path to `ServiceDll` registry key (e.g., nested group policies).", "field": "RegistryKeyTarget"}, {"description": "Correlation time window for registry change followed by DLL load or svchost restart.", "field": "TimeWindow"}, {"description": "Some environments may spawn registry changes from automation tools or administrative scripts.", "field": "ParentProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2239', 0, 172, '09-mitre-attack', 'retrieved', 'F79F11EE1404AF16D363BD6CE8702A751B897934E21920A85598193E52651B23', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
