VALUES ('doc-09-mitre-attack-p0-2240', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Phishing attachments executed on Linux systems are detected by linking email logs to file creation in mail directories and subsequent suspicious process execution. Look for unexpected binaries or scripts spawned from user mail directories and anomalous outbound network activity.", "external_references": [{"external_id": "AN0656", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0236#AN0656"}], "id": "x-mitre-analytic--02309791-384c-4ca9-b25c-6a6bc754795f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0656", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Inbound email attachments logged from MTAs with suspicious metadata", "name": "Application:Mail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "execve: Execution of files saved in mail or download directories", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Outbound traffic from suspicious new processes post-attachment execution", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitored directories for email attachments (e.g., /var/mail, ~/Maildir, ~/Downloads).", "field": "AttachmentStoragePaths"}, {"description": "List of interpreters to monitor when spawned by mail clients (e.g., bash, python, perl).", "field": "ScriptInterpreters"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2240', 0, 149, '09-mitre-attack', 'retrieved', '89B8F3F88C07EC309AB9DB1DDE568AA790B4145307C8A54E0B204D9C32F7EAAE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
