VALUES ('doc-09-mitre-attack-p0-2241', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of unsigned kernel extensions (KEXTs), tampering with LaunchDaemons, or userspace hooks into system libraries.", "external_references": [{"external_id": "AN1063", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0377#AN1063"}], "id": "x-mitre-analytic--0248d3dc-266e-45c3-89e4-4865f9174cfd", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1063", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "subsystem=com.apple.kextd", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "launch_daemons", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "Extensions", "name": "fs:fsevents", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowable level of unsigned/3rd-party kernel extensions varies by organization.", "field": "KextSignatureStatus"}, {"description": "Detect whether the extension was loaded by an untrusted process or non-root user.", "field": "KextLoadOrigin"}, {"description": "Detection tuned based on deviation from known/approved LaunchDaemon plist files.", "field": "AnomalousLaunchAgent"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2241', 0, 113, '09-mitre-attack', 'retrieved', '350E06D6D0