VALUES ('doc-09-mitre-attack-p0-2242', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary creation of cloud or IdP accounts whose names resemble existing privileged or service accounts. May indicate preparation for privilege escalation or defense evasion.", "external_references": [{"external_id": "AN1079", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0383#AN1079"}], "id": "x-mitre-analytic--0252a0ff-a4fb-4196-9b43-d759af950d55", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1079", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Add user", "name": "azure:audit", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"channel": "Rename user", "name": "azure:audit", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "User lifecycle events", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whether created users have privileged or scoped roles assigned at creation.", "field": "RoleScope"}, {"description": "Regex patterns or heuristics for detecting suspicious naming conventions (e.g., helpdesk_support_, root-admin).", "field": "NamingHeuristics"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2242', 0, 116, '09-mitre-attack', 'retrieved', 'CC9EDD051249CBFA7DBBE0F85D3862FC6C0FF5E0BF36F3FBA17624598DD6DC2D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
