VALUES ('doc-09-mitre-attack-p0-2243', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous authentication activity such as sign-ins from impossible geolocations or legacy protocols from high-privileged accounts.", "external_references": [{"external_id": "AN1503", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0546#AN1503"}], "id": "x-mitre-analytic--02571f27-8fa6-47cb-9097-0b84016a1dda", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1503", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Sign-in activity", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "user.authentication.sso", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines geographic separation (e.g., impossible travel) considered suspicious.", "field": "AnomalousLocationThreshold"}, {"description": "Filter based on legacy or deprecated authentication mechanisms.", "field": "ProtocolType"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2243', 0, 91, '09-mitre-attack', 'retrieved', '9FE97AD4A67DC0CE16C80C1E30056B77A2703E9FE263469B93FBD19054B1F1E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
