VALUES ('doc-09-mitre-attack-p0-2244', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Opening of Office files where VBA source code appears benign or missing, but p-code remains active. Defender perspective: process execution of Office apps with macro execution lacking visible source components.", "external_references": [{"external_id": "AN0036", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0012#AN0036"}], "id": "x-mitre-analytic--025e89c6-9383-48b5-b9f2-85ab31b6a7bb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0036", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process execution of Microsoft Word, Excel, PowerPoint with macro execution attempts", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Detection of altered _VBA_PROJECT or PerformanceCache streams", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjust for specific Office versions in use across macOS endpoints.", "field": "OfficeVersionScope"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2244', 0, 110, '09-mitre-attack', 'retrieved', '4CFDD6BA44290A33CBF8F2CD68A8EF374189AC9770ADF30F48AF7AC912CF2AF3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
