VALUES ('doc-09-mitre-attack-p0-2245', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlated file access to insecure credential files (e.g., *.env, *.xml, *.ps1) followed by suspicious process execution or authentication using retrieved credentials. Detected through Sysmon logs and Windows Security Event logs.", "external_references": [{"external_id": "AN0856", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0307#AN0856"}], "id": "x-mitre-analytic--0277e29a-af6d-4242-a187-32673328664a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0856", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Patterns like *.env, *credential* can be tuned to reduce noise or catch custom implementations", "field": "FileNamePattern"}, {"description": "Defines scope of access (e.g., only untrusted parent processes or high-risk processes)", "field": "ProcessAccessScope"}, {"description": "Time delta between credential file access and use in logon attempt", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2245', 0, 134, '09-mitre-attack', 'retrieved', '5B1B9CA333BC059BACF71411C363384CD4B540FCC749062430DABA2F2F303742', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
