VALUES ('doc-09-mitre-attack-p0-2246', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abuse of launchctl to execute or manage Launch Agents and Daemons. Defender perspective: correlation of suspicious plist file creation or modification in LaunchAgents/LaunchDaemons directories with subsequent execution of the launchctl command. Abnormal executable paths (e.g., /tmp, /Shared) or launchctl activity followed by network connections are highly suspicious.", "external_references": [{"external_id": "AN0736", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0265#AN0736"}], "id": "x-mitre-analytic--0297fd45-97bc-4913-8d38-218eae431544", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0736", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execution of launchctl load/unload/start commands", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "write of plist files in /Library/LaunchAgents or /Library/LaunchDaemons", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "launchctl spawning new processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "creation or loading of new launchd services", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Paths to monitor for suspicious plist files, such as /Library/LaunchAgents, /Library/LaunchDaemons, ~/Library/LaunchAgents.", "field": "MonitoredPaths"}, {"description": "Uncommon executable paths (e.g., /tmp, /Shared) that should raise alerts when associated with launchctl services.", "field": "SuspiciousExecPaths"}, {"description": "Correlation window for detecting plist file creation and subsequent launchctl execution.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2246', 0, 177, '09-mitre-attack', 'retrieved', 'B103CE2C35995BC569EAD34850020B4C24117B1F57774A3BBD64E34DB2AE6D49', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
