VALUES ('doc-09-mitre-attack-p0-2247', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Offline cracking inferred by subsequent successful CLI or web-based authentications into routers or switches from previously dumped accounts", "external_references": [{"external_id": "AN0296", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0105#AN0296"}], "id": "x-mitre-analytic--029db14d-fb94-49ee-9d6d-3c7212671377", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0296", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "config access, authentication logs", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Window to link credential theft and reuse", "field": "LogonTimeCorrelation"}, {"description": "Filters based on where cracking may have occurred externally", "field": "SourceDeviceTag"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2247', 0, 89, '09-mitre-attack', 'retrieved', '9ABFDDFFE19B3880C3D30F0225C85FDD9D65CFADBCB859B6E0D37FFA22757AAC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
