VALUES ('doc-09-mitre-attack-p0-2248', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of non-interactive or suspicious processes accessing Bluetooth interfaces and transmitting outbound traffic following file access or staging activity.", "external_references": [{"external_id": "AN1531", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0554#AN1531"}], "id": "x-mitre-analytic--02fb4d83-d2db-4d49-acbc-85eff3b517d6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1531", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=8001", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines how quickly a file access and Bluetooth activity must occur to be correlated.", "field": "TimeWindow"}, {"description": "May focus on Bluetooth-specific interfaces or drivers like ''bthport.sys''.", "field": "InterfaceType"}, {"description": "Tune to trigger only on significant exfiltratable file reads.", "field": "FileSizeThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2248', 0, 117, '09-mitre-attack', 'retrieved', 'D23E812AA46E3CDF7C4A622FCFC6BBA994924DDC80D619B8EF8432CD17ABB580', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
