VALUES ('doc-09-mitre-attack-p0-2249', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Observation of LaunchAgents or LaunchDaemons establishing periodic external connections indicative of automated data transfer.", "external_references": [{"external_id": "AN1115", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0397#AN1115"}], "id": "x-mitre-analytic--031ed94b-50d9-451e-a853-29ee8d845773", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1115", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process: exec", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "network", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "cron/launchd", "name": "macos:cron", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Frequency of task recurrence linked to external communication.", "field": "LaunchInterval"}, {"description": "Port number used for detection filtering.", "field": "DestinationPort"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2249', 0, 92, '09-mitre-attack', 'retrieved', '12C2449F43E92CA8E275504A6300FB7329EDD6416E969AC3EAC948446358AF98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
