VALUES ('doc-09-mitre-attack-p0-2250', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Compromised service account tokens mounted inside containers and reused for external API calls or lateral movement across services.", "external_references": [{"external_id": "AN0530", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0185#AN0530"}], "id": "x-mitre-analytic--03216652-ada9-4c1e-88c4-923c2cb60614", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0530", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "serviceAccount token used in API requests not tied to workload identity", "name": "kubernetes:apiserver", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"channel": "AssumeRoleWithWebIdentity", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict token use to specific namespaces or workloads", "field": "NamespaceScope"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2250', 0, 90, '09-mitre-attack', 'retrieved', '6D0F86B2A38F3A4F8C339B2FF27AF458CDCDECAAF60BD59FF783C10E103B200C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
