VALUES ('doc-09-mitre-attack-p0-2252', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "macOS clients joined to AD via LDAP may script account provisioning via `dsconfigad`, `dscl`, or LDAP scripts. Detection occurs when such tools run on a domain-joined system, followed by authentication attempts by a previously unseen account.", "external_references": [{"external_id": "AN0008", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0003#AN0008"}], "id": "x-mitre-analytic--03513eb2-6dbd-4160-94dd-25d2bce349be", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0008", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "dsconfigad or dscl with create or append options for AD-bound users", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "UserLoggedIn", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Only flag on AD-bound systems with valid LDAP context", "field": "EnrollmentStatus"}, {"description": "Distinguish between user accounts and computer accounts", "field": "AccountType"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2252', 0, 119, '09-mitre-attack', 'retrieved', 'F4056683C4F247455FE4766BF888D9AFD863C34C1E667C667F0A54F7A18A5146', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "