VALUES ('doc-09-mitre-attack-p0-2253', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous SaaS application integration activity across environments such as Slack, Salesforce, or other enterprise SaaS services. Focus is on unauthorized app additions, unusual permission grants, and persistence through service principal tokens.", "external_references": [{"external_id": "AN1488", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0539#AN1488"}], "id": "x-mitre-analytic--036a6a5d-bd87-45c7-bd68-43df76167786", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1488", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "New or modified third-party application integrations with elevated permissions", "name": "saas:integration", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "Application added or consent granted: Integration persisting after original user disabled", "name": "saas:audit", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines approved SaaS integrations for the enterprise; deviations indicate suspicious persistence.", "field": "AppWhitelist"}, {"description": "Threshold for which users can self-consent integrations; lowering this may reduce false positives.", "field": "ConsentDelegationPolicy"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2253', 0, 131, '09-mitre-attack', 'retrieved', '57A9B1246D524D4A893CB02A9345FF4947D6C4C01F1C4004A4336ED0549806FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
