INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2254', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous CI/CD workflow execution originating from forked repositories, with pull request (PR) metadata or commit messages containing suspicious patterns (e.g., encoded payloads), coupled with the use of insecure pipeline triggers like `pull_request_target` or excessive API usage of CI/CD secrets. Correlation with unusual artifact generation or secret exfiltration via encoded or external network destination URLs confirms suspicious behavior.", "external_references": [{"external_id": "AN1473", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0533#AN1473"}], "id": "x-mitre-analytic--0391c880-fcb3-457f-b625-18f9453659b8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1473", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Workflow triggered via pull_request_target from forked repo", "name": "saas:github", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "CI/CD secret accessed or exported", "name": "saas:github", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"channel": "Artifact generated includes base64/encoded exfil payload or URL", "name": "saas:github", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"channel": "New file added or modified in PR targeting CI/CD or build config (e.g., `gitlab-ci.yml`, `build.gradle`, `pom.xml`, `.github/workflows/*.yml`)", "name": "saas:RepoEvents", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "Commit message or branch name contains encoded strings or payload indicators", "name": "saas:PRMetadata", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time delta between PR creation and workflow execution to flag rapid attempts", "field": "TimeWindow"}, {"description": "Forked or external user accounts triggering workflows; may differ across orgs", "field": "UserContext"}, {"description": "CI trigger types (e.g., `pull_request_target`) that should or shouldn''t be used for forks", "field": "TriggerTypeAllowlist"}, {"description": "Entropy threshold for detecting encoded payloads in artifacts", "field": "ArtifactEntropyThreshold"}, {"description": "Rate of secret access in a single workflow run that might indicate abuse", "field": "SecretAccessRateThreshold"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2254', 0, 242, '09-mitre-attack', 'retrieved', '077C81729FD7DA839D1EA13699F5000004301198521F05779E9044471B4AF421', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
