VALUES ('doc-09-mitre-attack-p0-2255', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of `dseditgroup` or `dscl` to add users to privileged macOS groups (e.g., admin).", "external_references": [{"external_id": "AN0867", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0310#AN0867"}], "id": "x-mitre-analytic--03b0d93e-955a-49f6-83ad-8cf72b678367", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0867", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process execution or directory service changes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Focus on ''admin'' or ''com.apple.access_ssh''", "field": "GroupName"}, {"description": "Detect unknown or transient users making group changes", "field": "UserContext"}, {"description": "Detect group modifications at suspicious times", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2255', 0, 93, '09-mitre-attack', 'retrieved', 'DF8286BD34B026309155AEF0E0F55A0C867A086334C6C8740A2882C93190B758', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
