VALUES ('doc-09-mitre-attack-p0-2256', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unauthorized or anomalous loading of kernel-mode drivers or DLLs, concealed services, or abnormal modification of boot components indicative of rootkit activity.", "external_references": [{"external_id": "AN1061", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0377#AN1061"}], "id": "x-mitre-analytic--03f2259d-45c2-4422-83ad-58955f89350c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1061", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=6", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"channel": "EventCode=7045", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Signed vs unsigned drivers; many environments restrict unsigned drivers, but some legacy systems allow them.", "field": "DriverSignatureStatus"}, {"description": "Suspicious driver or DLL drop locations, e.g., \\System32\\Drivers\\ or \\Temp\\", "field": "TargetDirectory"}, {"description": "Rootkit installation via admin or SYSTEM account.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2256', 0, 119, '09-mitre-attack', 'retrieved', '4A35D8E79B6788701DA2753D5A397300F9A222EE49BECB05A8F5516E93843C92', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
