VALUES ('doc-09-mitre-attack-p0-2257', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Database enumeration and export activity (e.g., `SELECT * FROM`, `SHOW DATABASES`) issued via ephemeral VMs, admin APIs, or cloud shell from non-monitoring accounts. Defender correlates audit logs (CloudTrail, GCP Admin, AzureDiagnostics), storage write ops, and cross-region transfers by identities not tied to DB operations.", "external_references": [{"external_id": "AN0679", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0242#AN0679"}], "id": "x-mitre-analytic--041812fa-5446-47cc-8ca0-1106f4874c10", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0679", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "rds:ExecuteStatement: Large data access via RDS or Aurora with unknown session context", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"channel": "PutObject: S3 writes with .sql/.csv extension by same identity or within 5 min of DB access", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"channel": "Large transfer volume (>20MB) from RDS IP range to external public IPs", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define which IAM roles/accounts are allowed DB operations", "field": "IAMAccessPatterns"}, {"description": "Size threshold (MB) or file pattern for S3-based exfil monitoring", "field": "S3ExportThreshold"}, {"description": "Number of rows/columns or duration to flag long-running queries", "field": "DBQueryVerbosityThreshold"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2257', 0, 174, '09-mitre-attack', 'retrieved', '742F46C8521E285E78D2BBA82FEA72793F2A70A51212883691ABE020D79BA435', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
