VALUES ('doc-09-mitre-attack-p0-2258', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects successful login to cloud identity portals (e.g., Okta, Azure AD, Google Identity) from atypical geolocations, devices, or user agents immediately followed by dashboard/portal navigation to sensitive pages such as user or app configuration.", "external_references": [{"external_id": "AN0809", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0291#AN0809"}], "id": "x-mitre-analytic--041c0b93-fda4-478f-b847-d10619db729c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0809", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Sign-in with unfamiliar location/device + portal navigation", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "user.session.start", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "WebUI access to administrator dashboard", "name": "saas:okta", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for location anomalies per user profile", "field": "GeoIPAnomalyThreshold"}, {"description": "Unknown browser/device fingerprint list", "field": "UserAgentReputation"}, {"description": "List of sensitive dashboard views for alerting", "field": "PrivilegedPageAccess"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2258', 0, 129, '09-mitre-attack', 'retrieved', '641D6081F2D8350542D98B5D49CE4A0C1F4C00DF4EC828055D9E2A6052C5886E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
