VALUES ('doc-09-mitre-attack-p0-2259', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of new IAM roles or policies attached to a user/service in AWS/GCP/Azure outside normal patterns or hours, often following account compromise.", "external_references": [{"external_id": "AN0771", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0277#AN0771"}], "id": "x-mitre-analytic--04412d94-62ac-4484-9408-c4ca1c206f1b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0771", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "AttachUserPolicy, CreatePolicyVersion, PutRolePolicy", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "IAM Role type or privilege level assigned (e.g., Admin, Billing, Viewer)", "field": "RoleScope"}, {"description": "User, service account, or external federated identity context performing the action", "field": "UserContext"}, {"description": "How quickly multiple roles or policies are added after initial access", "field": "PolicyChangeTimeWindow"}, {"description": "Cross-account roles from outside trusted tenant list", "field": "ExternalRoleOrigin"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2259', 0, 121, '09-mitre-attack', 'retrieved', '29CC3AC4C0E5AB9A1A95AC648E2E482D42DFCE85FE836533A26880AD44565D72', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
