INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2260', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection focuses on identifying abuse of LD_PRELOAD and related linker variables. Defender perspective: monitor unexpected setting or modification of LD_PRELOAD in shell initialization scripts or environment exports, file creation of suspicious shared libraries, and correlation of these modifications with anomalous process execution. Key signals include execve events with LD_PRELOAD defined, newly created .so files in user directories, and processes hooking libc functions exhibiting abnormal behavior.", "external_references": [{"external_id": "AN1209", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0435#AN1209"}], "id": "x-mitre-analytic--048adb6e-49a1-463e-bc0d-0a9a543cf0ce", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1209", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve with LD_PRELOAD or linker-related environment variables set", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "creation of .so files in non-standard directories (e.g., /tmp, /home/*)", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "process environment variables containing LD_PRELOAD", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Environment variables like LD_PRELOAD, LD_LIBRARY_PATH. Defenders can tune based on development vs. production systems.", "field": "WatchedEnvVars"}, {"description": "Non-standard library paths (e.g., /tmp, user home dirs). May be tuned to reduce false positives from benign development activity.", "field": "MonitoredDirectories"}, {"description": "Timeframe to correlate suspicious library creation with process execution that loads it.", "field": "CorrelationWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2260', 0, 196, '09-mitre-attack', 'retrieved', 'E379E135ECEBD0E99E8A0EBFE8DEF70405BF691869AD45DA93506F1C995ECBE2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
