VALUES ('doc-09-mitre-attack-p0-2261', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Script or binary performs a rapid sequence of system discovery checks (e.g., CPU count, RAM size, registry keys, running processes) indicative of VM detection", "external_references": [{"external_id": "AN0478", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0168#AN0478"}], "id": "x-mitre-analytic--04bcbbb7-bfa9-41a5-9fb8-72a6df9ad50b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0478", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Sequence of system enumeration events within X seconds", "field": "TimeWindow"}, {"description": "Parent-child lineage to identify potentially suspicious launch sources (e.g., Office, browser, WMI, PowerShell)", "field": "ProcessAncestry"}, {"description": "Limit to non-admin or interactive sessions if desired", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2261', 0, 119, '09-mitre-attack', 'retrieved', '84B254B9B4