VALUES ('doc-09-mitre-attack-p0-2262', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious changes to macOS authorization and PAM plugin files. Correlates file modifications under /etc/pam.d/ or /Library/Security/SecurityAgentPlugins with unexpected authentication attempts or anomalous account usage.", "external_references": [{"external_id": "AN1251", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0454#AN1251"}], "id": "x-mitre-analytic--04cd1c76-d01d-482c-83e2-4bb5109e9764", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1251", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "authentication plugin load or modification events", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "write", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected set of PAM and authorization plugins; unknown additions may indicate malicious insertion.", "field": "WatchedPlugins"}, {"description": "Cross-correlation with VPN/physical access logs to identify impossible or anomalous login patterns.", "field": "CorrelatedSources"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2262', 0, 112, '09-mitre-attack', 'retrieved', '62ADB9C55F215428B10FCAFA0321ED97A7655B9BD04DB76EFC95F15373CE9BBF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
