VALUES ('doc-09-mitre-attack-p0-2263', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Insertion of USB-based hardware proxies (e.g., PiKVM) which register under predictable names (e.g., tinypilot) or mount under known paths (e.g., /opt/tinypilot-privileged).", "external_references": [{"external_id": "AN0447", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0159#AN0447"}], "id": "x-mitre-analytic--04e9470e-676f-4af0-add4-8103300ebd19", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0447", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "udev events or drive enumeration involving TinyPilot paths or device classes", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Different hardware may present differently; names like ''TinyPilot'' may need expanding to cover custom implants.", "field": "FriendlyName"}, {"description": "Path matching (e.g., /opt/tinypilot) is mutable based on distro, customization, and staging.", "field": "MountPath"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2263', 0, 109, '09-mitre-attack', 'retrieved', 'D7A90638902958FE53B89FAEB29C8E0FFE3BD6A5A6FAF9EB64C58FAC250D2E58', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
