VALUES ('doc-09-mitre-attack-p0-2264', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Connections to exposed container services (e.g., Docker API, Kubernetes API server) from unauthorized external IPs → abnormal container creation/start → lateral activity within cluster nodes.", "external_references": [{"external_id": "AN1007", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0354#AN1007"}], "id": "x-mitre-analytic--04fcf3d4-4547-4e64-bbb7-9faa46dda1f6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1007", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Docker/Kubernetes API access from external sources", "name": "ApplicationLog:API", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Unauthorized container creation or kubelet exec logs", "name": "kubernetes:audit", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "External access to container ports (2375, 6443)", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Approved external IP ranges for container APIs.", "field": "AllowedCIDRs"}, {"description": "Correlation window for API calls and container starts.", "field": "TimeWindow"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2264', 0, 120, '09-mitre-attack', 'retrieved', 'B394648B2BD5AFAAE3B5367E1B63305BE63C