VALUES ('doc-09-mitre-attack-p0-2265', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unexpected or high-volume HTTP/S/WebSocket communication from suspicious processes (e.g., PowerShell, rundll32) using uncommon user agents or mimicking browser traffic to unusual domains or IPs.", "external_references": [{"external_id": "AN0075", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0027#AN0075"}], "id": "x-mitre-analytic--04fe83c3-d8d3-4c96-91a4-9167fa8f405a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0075", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "http.log, ssl.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter out legitimate browser/network utilities", "field": "ProcessNameExclusions"}, {"description": "Detect non-browser user-agents or spoofed headers", "field": "UserAgentAnomalies"}, {"description": "Flag when outbound > inbound volume by 90%+", "field": "OutboundByteRatioThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2265', 0, 106, '09-mitre-attack', 'retrieved', 'EB45606A1F580380E286A73C9F6A457A1F444C0FEC6C8BC38B948EB9F05FC887', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_obj