VALUES ('doc-09-mitre-attack-p0-2267', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of system calls or commands accessing system locale (e.g., ''defaults read -g AppleLocale'', ''systemsetup -gettimezone''). Correlate with unusual parent processes or execution contexts.", "external_references": [{"external_id": "AN0121", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0043#AN0121"}], "id": "x-mitre-analytic--0521835b-bc02-41ed-8e6a-153e6422ee9c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0121", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "defaults read -g AppleLocale, systemsetup -gettimezone", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "execve", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict known binaries allowed to query system locale on macOS.", "field": "ExecutionPath"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2267', 0, 93, '09-mitre-attack', 'retrieved', '4ACBE570F92B80FABCC3ABC2C31E611D246BD463A2994DCB8AA51504D7E0CD8B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
