VALUES ('doc-09-mitre-attack-p0-2268', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Sign-in failures across enterprise SSO applications or SaaS platforms from same IP address using the same password against multiple user identities", "external_references": [{"external_id": "AN1339", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0487#AN1339"}], "id": "x-mitre-analytic--0527196a-1551-445c-bdd7-943dfda9b718", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1339", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Failure Reason + UserPrincipalName", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Use geolocation mismatches to strengthen signal", "field": "GeoIPAnomalyCheck"}, {"description": "Proportion of total user base affected to filter noise", "field": "FailedUserRatio"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2268', 0, 91, '09-mitre-attack', 'retrieved', '9B69CAA8AC1B44E6BD83FAB4B17DC188958A9B72FEB7D1A0776A30B1FEA5BA5B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
