VALUES ('doc-09-mitre-attack-p0-2269', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes such as curl, wget, or custom scripts initiating POST requests to webhook endpoints with encoded or bulk data. Defender perspective: abnormal chaining of file compression or access followed by outbound data to webhook URLs.", "external_references": [{"external_id": "AN0437", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0153#AN0437"}], "id": "x-mitre-analytic--053dd0c5-9746-46ea-bdeb-b385bf5cbbf8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0437", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "curl -X POST, wget --post-data", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "read/open of sensitive files", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "large HTTPS POST requests to webhook endpoints", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected command-line utilities allowed to interact with webhooks in enterprise environments.", "field": "AllowedTools"}, {"description": "Expected timeframe for legitimate webhook traffic (e.g., CI/CD deployments).", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2269', 0, 131, '09-mitre-attack', 'retrieved', '5584F69A1EA0D153C2868659A6087A8F9E1F050B7815B690E46FC63355FBAAA4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
