INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2273', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects rogue DHCP activity by monitoring syslog for dhclient messages assigning unauthorized DNS/gateway values. Packet capture or IDS can detect multiple competing DHCP OFFERs from non-authorized servers.", "external_references": [{"external_id": "AN1291", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0468#AN1291"}], "id": "x-mitre-analytic--05d8ce15-eaeb-47f5-abb7-8f8868dd8aaa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1291", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "suspicious DHCP lease assignment with unexpected DNS or gateway", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Gratuitous or duplicate DHCP OFFER packets from non-legitimate servers", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expected MAC addresses of DHCP servers on subnet.", "field": "AllowedDHCPMACs"}, {"description": "Number of suspicious DHCP leases before raising an alert.", "field": "DHCPLeaseChangeThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2273', 0, 117, '09-mitre-attack', 'retrieved', '087E2C020C7F3F32099CE77B9CAD2DFEBF7B84EB8D6A36B73A46DD719B369DB9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2274', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of suspicious use of ioctl/sysfs calls to access device firmware, unexpected flashing tools execution, and anomalous firmware checksums logged by SMART or kernel audit mechanisms.", "external_references": [{"external_id": "AN0917", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0323#AN0917"}], "id": "x-mitre-analytic--062580eb-eb79-4b31-b3fd-e500ebcfc128", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0917", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ioctl/write: Direct firmware update or device memory manipulation syscalls", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"channel": "Driver load events or firmware load failures for hardware devices", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Baseline firmware checksums for comparison", "field": "FirmwareImageBaseline"}, {"description": "Tolerance levels for SMART errors before triggering alerts", "field": "AlertThresholds"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2274', 0, 113, '09-mitre-attack', 'retrieved', '1138722CDDCE364808F790BE003ACC05DAB5F1154A5501C651E7A2D2F784FC96', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2275', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cause→effect chain: (1) A client app (browser, Office, PDF/Flash/reader) experiences a crash/abnormal exit or loads from an unusual location, then (2) drops or modifies a file in user-writable paths, and/or (3) spawns an unexpected child (e.g., powershell/cmd/mshta/rundll32/wscript/installer), and (4) establishes outbound C2-like connections shortly after. Correlate application logs, file writes, process lineage, and network egress within a short window.", "external_references": [{"external_id": "AN0797", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0287#AN0797"}], "id": "x-mitre-analytic--065f2c96-6903-4cd1-a737-99ecf1fdc73e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0797", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1000", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window (e.g., 15m) between crash/write/child/network.", "field": "TimeWindow"}, {"description": "List of child processes that should rarely spawn from Office/browsers (powershell.exe, cmd.exe, wscript.exe, mshta.exe, rundll32.exe, regsvr32.exe, msiexec.exe, curl.exe).", "field": "HighRiskChildren"}, {"description": "Writable paths to watch (Downloads, %TEMP%, %APPDATA%, OneDrive, Office startup folders).", "field": "UserPaths"}, {"description": "Known add-ins/extensions and updater binaries to reduce noise.", "field": "AllowedPlugins"}, {"description": "Known update/CDN domains and proxy egress CIDRs for suppression.", "field": "EgressAllowlist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2275', 0, 190, '09-mitre-attack', 'retrieved', '71BB920F83838D7D0E3FE8E0840F7FDCD8B5FD0B1A6E909BF4CCF80998223547', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2276', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary exploits exposed OpenSLP on ESXi or vCenter public endpoints. Chain: inbound request pattern to mgmt service → hostd/vpxd error/crash/restart → unexpected process behavior or datastore access → outbound callback.", "external_references": [{"external_id": "AN0224", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0080#AN0224"}], "id": "x-mitre-analytic--0668f39a-d319-427f-b29b-160399e6f79a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0224", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/hostd.log anomalies (faults, crashes, restarts) around inbound connections", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Connections to TCP 427 (SLP) or vCenter web services from untrusted sources", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Only trusted admin networks should reach ESXi/vCenter.", "field": "MgmtCIDR"}, {"description": "Join errors and inbound flows.", "field": "TimeWindow"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2276', 0, 117, '09-mitre-attack', 'retrieved', '46862826554DC1313BC32D8BC62EE43412C4C51E98C8C876763408264E73CF0C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
