VALUES ('doc-09-mitre-attack-p0-2278', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Programmatic access to user content via stolen access tokens in platforms like Slack, GitHub, Google Workspace — especially from new IPs, apps, or excessive resource access.", "external_references": [{"external_id": "AN1427", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0515#AN1427"}], "id": "x-mitre-analytic--0677b819-0586-454c-9f4d-c861ccaf1b73", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1427", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Access via OAuth credentials with unusual scopes or from anomalous IPs", "name": "saas:googleworkspace", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "OAuth token use by unknown app client_id accessing private channels or files", "name": "saas:slack", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag when token use appears across geographically distant logins", "field": "GeoVelocity"}, {"description": "Weight certain scopes (admin, file.read) as higher risk", "field": "OAuthScopeSensitivity"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2278', 0, 121, '09-mitre-attack', 'retrieved', '9801269AAA956112760F29231196506D52FE950C0AD44B3C3C7E70DB30D1D3F6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
