VALUES ('doc-09-mitre-attack-p0-2280', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Account discovery via VBA macros, COM objects, or embedded scripting.", "external_references": [{"external_id": "AN1619", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0587#AN1619"}], "id": "x-mitre-analytic--06e0501e-a87e-452d-9ab5-93ed9a5eade5", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1619", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Scripted Activity", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Alert on auto-running macros accessing directory or user info.", "field": "MacroName"}, {"description": "Focus on macros invoking LDAP, ADODB, or WMI queries.", "field": "ExecutionScope"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2280', 0, 81, '09-mitre-attack', 'retrieved', '7F6FBBF7AF05A972ECFB050F8C340D3BE6231AA979B71ED85F6DB9A6A00FE623', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
