VALUES ('doc-09-mitre-attack-p0-2282', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unauthorized mirroring sessions initiated on routers/switches (e.g., via `monitor session`, `mirror port`) coupled with outbound traffic from mirrored interface to unexpected destinations.", "external_references": [{"external_id": "AN1132", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0403#AN1132"}], "id": "x-mitre-analytic--0729dd54-2fda-460a-8bb3-eee02f0f3c4e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1132", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Config change: CLI/NETCONF/SNMP – ''monitor session'', ''mirror port''", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Traffic from mirrored interface to mirror target IP", "name": "networkdevice:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune based on accepted interface config changes (e.g., audit only mirror session creation)", "field": "ConfigChangeType"}, {"description": "Define high-risk ports used for exfil (e.g., 4443, 8443, 2055)", "field": "MirrorDestinationPort"}, {"description": "Define whether mirroring is expected on edge vs core vs distribution devices", "field": "DeviceRole"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2282', 0, 132, '09-mitre-attack', 'retrieved', '296182094318662C94662704E0C86A13CF6B2FECDA7112F36AC3A2DD8A778581', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
