INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2284', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identifies custom or previously unseen userland processes initiating high-volume HTTP connections with low response volume.", "external_references": [{"external_id": "AN0145", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0053#AN0145"}], "id": "x-mitre-analytic--07deb060-c373-4059-b73b-736688a25c80", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0145", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines what is considered abnormal for a user-initiated process context", "field": "UserProcessBaseline"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2284', 0, 73, '09-mitre-attack', 'retrieved', '6C58D09996DB2D80E870A5EF0E1656AEDCB926B646A6573AC3BD0371FFC69834', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
