VALUES ('doc-09-mitre-attack-p0-2285', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Observation of chmod commands setting setuid/setgid bits, paired with launch of binaries under elevated execution context (e.g., root-owned binaries launched by unprivileged users).", "external_references": [{"external_id": "AN0308", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0110#AN0308"}], "id": "x-mitre-analytic--08314a8b-becd-4853-8a6c-dd5a947b36c0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0308", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "chmod command with arguments including ''+s'', ''u+s'', or numeric values 4000–6777", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "exec of binary with setuid/setgid and EUID != UID", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitor execution chains where UID != EUID or child process inherits root without known sudo context", "field": "UserContext"}, {"description": "Focus on binaries in user-writable locations or abnormal directories", "field": "ExecutionPath"}, {"description": "Tailor detection to chmod commands that imply privilege elevation via numeric mode or symbolic mode", "field": "ChmodPattern"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2285', 0, 141, '09-mitre-attack', 'retrieved', '6F926953E57F5F5EB0778A2041106ED90EB11E65E966E4830D6ADA85EE9E71DB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
