INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2286', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects abuse of Mono/.NET Core environments to execute VB-like scripts, often in environments with Office emulation or WINE. Focus is on rare invocations of scripting hosts like mono.exe or .NET shells, often seen in spam filtering or forensic labs with Office support.", "external_references": [{"external_id": "AN0211", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0076#AN0211"}], "id": "x-mitre-analytic--08318de4-1327-48ac-a686-403162d3891f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0211", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "/var/log/syslog", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Mono/.NET Core binary location may differ per distro or Docker container.", "field": "InterpreterPath"}, {"description": ".vbs, .vb, or .vba run under non-standard interpreters.", "field": "FileExtension"}, {"description": "Execution by low-privilege users or from /tmp/.", "field": "ExecContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2286', 0, 128, '09-mitre-attack', 'retrieved', 'C321104C5F5E71C2B5D84FC8B9E997534E8152B669C4661CBB4A2C96D6C28B18', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
