INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2288', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Outbound encrypted traffic initiated from hypervisor shell or via VM backdoor mechanisms to relays in VPS infrastructure, especially if traversing multiple nodes before reaching Internet destination. Packet captures or firewall logs show non-VM communication paths.", "external_references": [{"external_id": "AN1023", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0359#AN1023"}], "id": "x-mitre-analytic--08370ff8-9442-42c0-bfb5-c7f5792c74ea", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1023", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/esxupdate.log or /var/log/vmksummary.log", "name": "esxi:esxupdate", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "/var/log/vmkernel.log", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Relay patterns across IP hops", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold on number of IPs contacted in sequence without DNS resolution.", "field": "HopCount"}, {"description": "Flag if relay communication initiated by ESXi shell or unknown VM agent.", "field": "ShellAccess"}, {"description": "Filter for known Tor/VPS egress networks.", "field": "VPSIPRange"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2288', 0, 136, '09-mitre-attack', 'retrieved', '5C7351E9E5C72B48A2F67D2D3F601370400AE6721C77C9CB68D15422E1C921B0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
