INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2289', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A remote host sends a short sequence of failed connection attempts (RST/ICMP unreachable) to a set of closed ports. Within a brief window the endpoint (a) adds/enables a firewall rule or (b) a sniffer-backed process begins listening or opens a new socket, after which a successful connection occurs. Also detects Wake-on-LAN magic packets seen on local segment.", "external_references": [{"external_id": "AN1448", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0524#AN1448"}], "id": "x-mitre-analytic--0848a778-7bcf-48d9-a14a-d29d1e71e656", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1448", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=2004, 2005, 2006", "name": "WinEventLog:Microsoft-Windows-Windows Firewall With Advanced Security/Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Window to correlate knock sequence → rule change → successful connect (e.g., 120s).", "field": "TimeWindowKnock"}, {"description": "Minimum number of distinct closed ports hit before success (e.g., 3).", "field": "PortSequenceMinLen"}, {"description": "List of binaries that commonly toggle firewall/sniff (netsh.exe, powershell.exe, npcapservice.exe, windivert, rawsock tools).", "field": "SuspiciousProcesses"}, {"description": "Service accounts or software update agents allowed to change firewall.", "field": "AllowedFirewallChangers"}, {"description": "Maintenance windows when magic packets are expected.", "field": "WoLAllowedWindows"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2289', 0, 199, '09-mitre-attack', 'retrieved', 'A1670944BCA8CD223B4BD909CBAB03D182AD2206806795F6CCAD3421C1131158', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
