INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2292', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Cloud-hosted VM or container generates spoofed UDP requests to third-party services on known amplifier ports, with high outbound-to-inbound traffic ratios in VPC Flow Logs", "external_references": [{"external_id": "AN1143", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0408#AN1143"}], "id": "x-mitre-analytic--08c69003-044c-46a5-b17a-7cb5b25f2d50", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1143", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Create egress rule allowing UDP to port 53, 123, 11211", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"channel": "Large outbound UDP traffic to multiple public reflector IPs", "name": "AWS:VPCFlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Sudden spike in network output without a corresponding inbound request ratio", "name": "AWS:CloudWatch", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Cloud security group rules permitting UDP to reflector protocols", "field": "EgressRulePorts"}, {"description": "Ratio threshold to flag traffic as potential reflection behavior", "field": "OutboundToInboundRatio"}, {"description": "Cloud metadata that can help scope anomalous behavior to development, testing, or external-facing services", "field": "VMInstanceTagContext"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2292', 0, 149, '09-mitre-attack', 'retrieved', '476EE81A71A6E87A1050BA1543217B16F88F6FC813F270EA1E5D0CCA93249964', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
