VALUES ('doc-09-mitre-attack-p0-2293', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of writes to /boot or EFI directories outside of expected package manager updates. Monitoring kernel log and auditd events for attempts to overwrite bootloader binaries (e.g., grub, shim). Unexpected execution of efibootmgr or dd writing to /dev/sdX devices followed by boot parameter changes.", "external_references": [{"external_id": "AN0775", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0278#AN0775"}], "id": "x-mitre-analytic--08dd2c3b-e07c-4b47-bae6-aa09c2a86d87", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0775", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, write: Modification of /boot/grub/* or /boot/efi/*", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "exec: Execution of dd, efibootmgr, or flashrom modifying firmware/boot partitions", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowlist of legitimate grub/shim updates via apt, yum, or rpm.", "field": "PackageManagerUpdateWhitelist"}, {"description": "Directories (e.g., /boot/efi, /boot/grub) monitored for unauthorized modification.", "field": "FilesystemPaths"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2293', 0, 134, '09-mitre-attack', 'retrieved', 'BB83863965162BEAD8A7E3B04E8700E53CB5CB17BA4AE945AF21ED0460EC1978', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
