INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2294', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Shell scripts or binaries implement custom mapping tables (tr/sed/awk/golang/rust/python encode loops), or emit long high-entropy tokens that fail Base64/Hex validation → correlated with egress showing asymmetric flow, protocol-mismatch payloads, or DNS/HTTP bodies containing low-diversity-but-long custom alphabets.", "external_references": [{"external_id": "AN0928", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0326#AN0928"}], "id": "x-mitre-analytic--09125bb1-29eb-4d40-994a-2e1aa7bcd105", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0928", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve of interpreters (python, perl), custom binaries, or shell utilities with long arguments containing non-standard tokens", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "http: HTTP bodies/headers contain long tokens with non-standard alphabets or constant-size periodic POSTs", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Payload entropy minimum.", "field": "EntropyThreshold"}, {"description": "Length threshold for suspect tokens.", "field": "TokenLengthThreshold"}, {"description": "Asymmetry cutoff for flows.", "field": "BytesOutToInRatio"}, {"description": "Correlation join window.", "field": "TimeWindow"}, {"description": "Legitimate internal tools/agents.", "field": "KnownEncoders"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2294', 0, 154, '09-mitre-attack', 'retrieved', '33E92CFCE9D52176E1240DFC58C156994184292F7E89124D6819AD201E2487C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
