INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2296', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect user-initiated kextload commands or modifications to /Library/Extensions. Correlate with changes to KextPolicy database or unauthorized developer signing identities. Alert on attempts to disable SIP or load legacy extensions from unsigned sources.", "external_references": [{"external_id": "AN1244", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0450#AN1244"}], "id": "x-mitre-analytic--092689c7-be8a-4d11-99d8-7dd96afa938d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1244", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "kextload execution from Terminal or suspicious paths", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Processes executing kextload, spctl, or modifying kernel extension directories", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "New kext entries not signed by Apple or outside standard identifier prefix", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--23e4ee78-26f3-4fcf-ba43-ab953962f96c"}, {"channel": "Modifications to /var/db/SystemPolicyConfiguration/KextPolicy or kext_policy table", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Approved developer IDs whose kexts should not trigger alerts", "field": "DeveloperIDAllowlist"}, {"description": "Threshold for detecting kext loads outside standard install/update operations", "field": "KextLoadTimeWindow"}, {"description": "Flag to enforce strict signing checks depending on SIP status", "field": "SignatureCheckFlag"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2296', 0, 162, '09-mitre-attack', 'retrieved', 'CFC292FC87272B52D0044FC8065A1ED30E61F049281E5A8AC7FFE4AD923D037A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
