INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2297', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process (often after stealing/creating a token) calls CreateProcessWithTokenW/CreateProcessAsUserW or uses runas to spawn a **new** process whose security context (SID/LogonId/IntegrityLevel) differs from its parent. Chain: (1) suspicious command/API → (2) privileged handle or token duplication/open → (3) new child process running as another user / higher integrity → (4) optional follow‑on privileged/lateral actions.", "external_references": [{"external_id": "AN1253", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0456#AN1253"}], "id": "x-mitre-analytic--0929e9c5-2e1a-4cc1-a9c5-df081b180201", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1253", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "api_call: CreateProcessWithTokenW, CreateProcessAsUserW", "name": "ETW:ProcThread", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "EventCode=4672, 4634", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "EventCode=5136", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window between API/handle access and the spawned process (default 5–10 minutes).", "field": "TimeWindow"}, {"description": "Service accounts/binaries legitimately using CreateProcessWithTokenW (e.g., PsExec service, SCCM, backup agents).", "field": "AllowedImpersonators"}, {"description": "Minimum jump in integrity level (e.g., Medium→System) to flag.", "field": "IntegrityEscalationDelta"}, {"description": "Treat any parent/child SID or LogonId mismatch as suspicious unless on allow-list.", "field": "ParentChildUserMismatch"}, {"description": "List of processes (e.g., lsass.exe, winlogon.exe, services.exe) whose token access prior to the spawn raises score.", "field": "SensitiveTargets"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2297', 0, 201, '09-mitre-attack', 'retrieved', '510F0A61AF344E4FAE5F209901F69F25551037D5A75E13E1633FAD4CA4A6344D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
