INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2298', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Bulk enumeration of cloud user email identities through `Get-Recipient`, `Get-Mailbox`, `Get-User`, or Graph API directory listings by abnormal accounts or suspicious sessions.", "external_references": [{"external_id": "AN1089", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0386#AN1089"}], "id": "x-mitre-analytic--0961ff0c-8c36-4820-948d-12855b7f5cc7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1089", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CmdletName: Get-Recipient, Get-User", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "users.list, directoryObjects.getByIds", "name": "Microsoft Graph API Logs", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune threshold for recipient/mailbox queries by volume per hour.", "field": "CmdletVolume"}, {"description": "Match known admin consoles and exclude sanctioned tools like MSOL PowerShell.", "field": "UserAgent"}, {"description": "Elevate sessions from unmanaged or external endpoints.", "field": "SessionContext"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2298', 0, 116, '09-mitre-attack', 'retrieved', '55F1A606802F7A31C3C1CBC9B1AB9B5A2D43EC489C608A65EC2D397376394E10', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
