INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2299', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary uses `dscl`, `who`, or environment variables like `$USER` to identify accounts or sessions via Terminal or malicious LaunchAgents.", "external_references": [{"external_id": "AN0256", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0093#AN0256"}], "id": "x-mitre-analytic--0979e7f1-9d0a-4549-be8f-88979df5c8d7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0256", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "subsystem:com.apple.Terminal", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate dscl usage with known persistence vectors", "field": "LaunchAgentPersistence"}, {"description": "Distinguish between user-initiated terminal vs. script execution", "field": "CommandExecutionPath"}, {"description": "Regex-based pattern tuning for `dscl . -list /Users` + grep filters", "field": "UsernameEnumerationPattern"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2299', 0, 104, '09-mitre-attack', 'retrieved', '4DB80A4F7730935330A1A9700295F1D94AA29EA97F3507B90ADEA06A9E980F09', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
