VALUES ('doc-09-mitre-attack-p0-2300', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects timestamp changes using `touch`, `SetFile`, or direct metadata tampering (e.g., xattr manipulation) from Terminal, scripts, or low-level APIs.", "external_references": [{"external_id": "AN1628", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0591#AN1628"}], "id": "x-mitre-analytic--097ce8cb-9a38-4c8a-836c-cee15ccdf258", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1628", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --predicate", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Touch/setfile and backdated timestamps", "field": "CommandMatch"}, {"description": "Detects execution under non-interactive/system accounts", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2300', 0, 87, '09-mitre-attack', 'retrieved', '14DB5D6A49EDF37FA1A4B852BBF597E9713DECBB6901CECDFA7985B13C8965D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
