VALUES ('doc-09-mitre-attack-p0-2301', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T20:40:20.993Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process with no prior history or outside of known whitelisted tools initiates file or registry modifications to configure exclusion rules for antivirus, backup, or file-handling systems. Or a file system enumeration for specific file names andcritical extensions like .dll, .exe, .sys, or specific directories such as ''Program Files'' or security tool paths or system component discovery for the exclusion of the files or components.", "external_references": [{"external_id": "AN2030", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0897#AN2030"}], "id": "x-mitre-analytic--098f0607-df17-4291-a1b1-a8e3374c075a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 2030", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate multiply discovery activities and file enumeration activities.", "field": "TimeWindow"}, {"description": "Minimum number of different discovery techniques within time window to trigger detection - balance between false positives and coverage (default: 4 activities)", "field": "DiscoveryActivityThreshold"}, {"description": "List of extensions or folders considered suspicious when excluded (e.g., .dll, .exe, C:\\\\Program Files\\\\)", "field": "ExclusionTargetList"}, {"description": "Whitelist of known system management tools/processes allowed to modify exclusion settings", "field": "AuthorizedExclusionModifiers"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2301', 0, 196, '09-mitre-attack', 'retrieved', 'F1FD9EE65FF39B1CA703CCDC2A2D816F46E344F6FD5889F154B1899A4E720A35', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
