INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2302', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlate command executions involving ''sudo'' with elevated effective user ID (euid=0), especially when tty_tickets is disabled or timestamp_timeout is actively abused.", "external_references": [{"external_id": "AN0142", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0052#AN0142"}], "id": "x-mitre-analytic--0994985d-1d45-478e-9f1c-f407eb297007", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0142", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve call for sudo where euid != uid", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "execve call for modification of /etc/sudoers or writing to /var/db/sudo", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune the valid sudo session duration to reduce false positives", "field": "timestamp_timeout_threshold"}, {"description": "Filter benign sudo usage (e.g., approved admin scripts)", "field": "command_allowlist"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2302', 0, 112, '09-mitre-attack', 'retrieved', '3B458306D9F625AA68C1D89AF70EBEADEAA51D042AAEA261CE4BD333C8ED6754', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
