INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2303', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Phishing attempts targeting IdPs often manifest as anomalous login attempts from suspicious email invitations or fake SSO prompts. Detection correlates login flows, MFA bypass attempts, and anomalous geographic patterns following phishing email delivery.", "external_references": [{"external_id": "AN0192", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0070#AN0192"}], "id": "x-mitre-analytic--09df0b88-e1ae-4a1e-86c4-8bb00e79baed", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0192", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Failed MFA attempts, unusual conditional access triggers, login attempts from unexpected IP ranges", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowed distance/time delta between user sign-ins.", "field": "GeoAnomalyThreshold"}, {"description": "Signals of repeated or anomalous MFA failures linked to phishing campaigns.", "field": "MFABypassIndicators"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2303', 0, 114, '09-mitre-attack', 'retrieved', '8DAADAE73F35778DD27E0DC2E633DA3642C4556717D28D11AB2B5C418B2716AF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
