VALUES ('doc-09-mitre-attack-p0-2304', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary installs or modifies IIS components (ISAPI filters, extensions, or modules) using DLL files registered via configuration changes or administrative tools like AppCmd.exe. These components intercept or manipulate HTTP requests/responses for persistence or C2.", "external_references": [{"external_id": "AN0184", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0068#AN0184"}], "id": "x-mitre-analytic--09ef4725-8e20-452d-b08c-f7db3cbee174", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0184", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Changes to applicationhost.config or DLLs loaded by w3wp.exe", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Module or ISAPI filter registration events", "name": "WinEventLog:Microsoft-IIS-Configuration", "x_mitre_data_component_ref": "x-mitre-data-component--66531bc6-a509-4868-8314-4d599e91d222"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Adjustable time frame for detecting chained events (e.g., config change + module load)", "field": "TimeWindow"}, {"description": "Scope detection to specific users or roles allowed to modify IIS components", "field": "UserContext"}, {"description": "Specific directories such as %windir%\\System32\\inetsrv\\ for DLL monitoring", "field": "WatchedPaths"}, {"description": "Entropy or name patterns to flag suspicious DLLs registered as components", "field": "DLLNameEntropyThreshold"}, {"description": "Restrict to DLLs loaded by w3wp.exe or invoked via AppCmd.exe", "field": "ParentProcessName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2304', 0, 192, '09-mitre-attack', 'retrieved', 'AEEDB7FDCE1B21821FF7FB58ACDD989EB9649FC05D6F733BFA09198DFABE9973', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
