INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2305', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary attempts to monopolize control of compromised systems by issuing service stop commands, unloading vulnerable modules, or forcefully killing competing processes. Defenders should monitor audit logs and syslog for administrative utilities (systemctl, service, kill) being invoked outside of normal change management.", "external_references": [{"external_id": "AN0046", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0015#AN0046"}], "id": "x-mitre-analytic--0a1f9686-4fd6-4719-84ef-7a590d02d1fb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0046", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: Commands like systemctl stop , service stop, or kill -9 ", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Unexpected termination of daemons or critical services not aligned with admin change tickets", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines specific Linux daemons and processes that should not be terminated outside maintenance windows.", "field": "CriticalProcessList"}, {"description": "Defines expected accounts permitted to execute service stop commands; deviations may be suspicious.", "field": "AdminUserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2305', 0, 149, '09-mitre-attack', 'retrieved', 'CB9F8037DB8E6733F04B47F434C01F0E1FF938B8AEBA9FCDC116DB88811CC78A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
