INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2307', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Anomalous or bulk download activity from private or restricted repositories by non-developer or privileged accounts, often preceded by unusual login behavior (e.g., unfamiliar geo, OAuth token use, elevated API rate).", "external_references": [{"external_id": "AN0732", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0263#AN0732"}], "id": "x-mitre-analytic--0aa20e10-ec46-4acf-810e-e8ed038d7744", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0732", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "repo.download, repo.clone, oauth.authorize, repo.getContent", "name": "saas:github", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"channel": "Login from unusual IP, device fingerprint, or location; access token creation from new client", "name": "saas:github", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Bulk access to multiple files or large volume of repo requests within short time window", "name": "saas:github", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for file access volume over short duration (e.g., 10+ repos accessed in <5 min)", "field": "TimeWindow"}, {"description": "Role or permission profile expected to interact with repositories (e.g., developers vs. admins)", "field": "UserContext"}, {"description": "Distance or variance allowed before a login is flagged as anomalous", "field": "GeoAnomalyThreshold"}, {"description": "Whether a repository is labeled sensitive or restricted", "field": "RepoSensitivityTag"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2307', 0, 176, '09-mitre-attack', 'retrieved', 'D3544610AFDCC855DBBBC2C5F245149E955C828CD50A830C36A6166DF7627167', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
