VALUES ('doc-09-mitre-attack-p0-2308', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversaries accessing datastore or configuration files via `vim-cmd`, `esxcli`, or SCP to extract logs, VMs, or host configurations.", "external_references": [{"external_id": "AN1074", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0380#AN1074"}], "id": "x-mitre-analytic--0abb4122-0795-46ef-b162-7570db42596a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1074", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Datastore Access", "name": "esxis:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "Command Execution", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex for filtering targeted VM paths or files like *.vmdk, *.vmx.", "field": "AccessPathRegex"}, {"description": "Tune to distinguish between interactive and script-driven data access.", "field": "InteractiveShellUsage"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2308', 0, 97, '09-mitre-attack', 'retrieved', '31C950808E80AA512CC1A34370FD72F130FC5604564DA9E4299FD15912A95024', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
