VALUES ('doc-09-mitre-attack-p0-2309', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Chain: (1) IdP policy/read operations by a principal (e.g., Microsoft Entra/Graph requests to read password or authentication policies); (2) adjacent risky changes (role assignment, app consent) by same principal. Use IdP audit logs.", "external_references": [{"external_id": "AN0459", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0161#AN0459"}], "id": "x-mitre-analytic--0b0d50a0-d07b-4cf1-9cb0-23c95e8321b2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0459", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "operation contains ''Get*Password*Policy'' OR ''List*Authentication*Policy'' OR ''Get-ADDefaultDomainPasswordPolicy''", "name": "azure:audit", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate partner apps that enumerate policies.", "field": "TrustedPartnerAppIds"}, {"description": "Raise risk for unusual geo or TOR/VPN egress.", "field": "GeoRiskTolerance"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2309', 0, 105, '09-mitre-attack', 'retrieved', 'A8FFDFA635B94B4253A90AF6B566AE249216F924D6E7A7D3D0A4E39A37B5DC9F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
