INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2310', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Repeated invocation of high-resource application endpoints or GUI components causing CPU and memory spikes, logged as elevated request volumes, prolonged handle locks, or frequent crash recoveries.", "external_references": [{"external_id": "AN1165", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0415#AN1165"}], "id": "x-mitre-analytic--0b514d96-12ce-41e2-b870-b35933d7faa6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1165", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "High-frequency errors or hangs from resource-intensive application components (e.g., .NET, IIS, Office Suite)", "name": "WinEventLog:Application", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Sudden spikes in CPU/Memory usage linked to specific application processes", "name": "Windows:perfmon", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Define what percentage of CPU usage indicates abnormal behavior.", "field": "CPUThreshold"}, {"description": "Window (e.g., 5 mins) during which sustained memory usage may be abnormal.", "field": "MemoryConsumptionWindow"}, {"description": "Threshold for frequency of application faults within a specific interval.", "field": "AppCrashFrequency"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2310', 0, 144, '09-mitre-attack', 'retrieved', 'E0542D827B6F10174C2B4C5A822B66F1BC365962FAEC3E44FDD9C7C9E1FE57C6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
