INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2311', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation of vulnerabilities in cloud identity providers (IdPs) such as Azure AD or Okta for credential access. Defender perspective includes anomalous token creation or renewal, authentication bypass events, and API abuse to mint unauthorized tokens. Correlation highlights exploitation attempts tied to absent or inconsistent audit logs.", "external_references": [{"external_id": "AN0496", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0174#AN0496"}], "id": "x-mitre-analytic--0b8b8557-0393-4c63-963f-e5a3b5cc6ad8", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0496", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "TokenIssued, TokenRenewed: Unexpected or anomalous token issuance events", "name": "azure:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"channel": "ConsentGranted: Abuse of application integrations to mint tokens bypassing MFA", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for anomalous token creation or renewal before alerting.", "field": "TokenAnomalyThreshold"}, {"description": "Applications with privileged access that should be tightly monitored for misuse.", "field": "MonitoredAppIntegrations"}], "x_mitre_platforms": ["Identity Provider"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2311', 0, 141, '09-mitre-attack', 'retrieved', '05962E6BC5C2D518DE2DED15CC2307A657FA25E9498FA66DCABC280EB8D63DB4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
