INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2314', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Multi-event correlation of Registry creation under Active Setup with anomalous execution of processes at user logon. Behavioral patterns include creation/modification of HKLM Active Setup keys with non-standard StubPath values, followed by process execution from uncommon paths, unsigned binaries, or unusual parent-child lineage post-user login.", "external_references": [{"external_id": "AN0871", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0312#AN0871"}], "id": "x-mitre-analytic--0be2ac94-5f56-4bdc-bf07-ec9ea08c8bb7", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0871", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4672", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=13, 14", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"channel": "EventCode=12", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate registry change and process execution within a specific user logon session (e.g., 5–10 minutes)", "field": "TimeWindow"}, {"description": "Expected parent processes for Active Setup launched binaries (e.g., explorer.exe). Deviations may indicate abuse.", "field": "ParentProcessName"}, {"description": "Degree of randomness/uncommonness in StubPath values. High entropy may indicate obfuscation.", "field": "StubPathValueEntropy"}, {"description": "Flag if launched binary in StubPath is unsigned or uncommon for baseline", "field": "SignedBinaryStatus"}, {"description": "Check which user/context added the Active Setup key to detect privilege abuse", "field": "RegistryKeyOwner"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2314', 0, 187, '09-mitre-attack', 'retrieved', '794ADDF49E7681662B8C97B48A2A5D08C50201CC1BE5A563C611899C9A13DF44', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
