VALUES ('doc-09-mitre-attack-p0-2316', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects non-system processes accessing /dev/input/* or issuing ptrace/evdev syscalls used for reading keystroke buffers directly.", "external_references": [{"external_id": "AN0244", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0089#AN0244"}], "id": "x-mitre-analytic--0c122a8e-bcb0-4756-8a63-193c52d61d90", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0244", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open, read", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "ptrace, ioctl", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Exclude known good applications (e.g. Xorg, GNOME Shell)", "field": "ProcessName"}, {"description": "Typically /dev/input/event*, but tunable to match custom input buses", "field": "DevicePath"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2316', 0, 91, '09-mitre-attack', 'retrieved', 'A8CCADF293CF58C0C66F9D15D4C829C2750F84CF29C459F06564E76B4E0D19C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
