VALUES ('doc-09-mitre-attack-p0-2317', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious inbound mail traffic where SPF/DKIM/DMARC authentication fails or where sender and return-path domains mismatch, observable in Apple Mail unified logs or MDM-controlled logging pipelines.", "external_references": [{"external_id": "AN1204", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0431#AN1204"}], "id": "x-mitre-analytic--0c4a2cfd-a064-4f45-9c07-eb5c1044dd61", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1204", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "SPF fail OR DKIM fail OR DMARC fail OR mismatched header vs envelope domains", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allows tuning based on which users (e.g., executives, finance staff) receive stricter spoofing detection policies.", "field": "RecipientSensitivity"}, {"description": "Defines tolerance for minor discrepancies in domain alignment, balancing detection with usability.", "field": "HeaderMismatchTolerance"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2317', 0, 117, '09-mitre-attack', 'retrieved', '5EBF5BEB66F575E743DB09C0A828A20B19F35A4E807735CEA3293716560FE6A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
