INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2318', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous use of COM, DDE, or named pipes for execution. Correlates creation or access of IPC mechanisms (e.g., named pipes, COM objects) with unusual parent-child process relationships or code injection patterns (e.g., Office spawning cmd.exe via DDE).", "external_references": [{"external_id": "AN1357", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0493#AN1357"}], "id": "x-mitre-analytic--0c6a8e7a-f9d0-479a-88c1-4ce26edba81c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1357", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=17", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--b9a1578e-8653-4103-be23-cb52e0b1816e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Environment-specific pipe names used legitimately vs anomalous (e.g., \\\\.\\pipe\\svcctl).", "field": "PipeNamePattern"}, {"description": "Expected parent-child process lineage to minimize false positives (e.g., explorer.exe spawning outlook.exe).", "field": "AllowedParentChildPairs"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2318', 0, 118, '09-mitre-attack', 'retrieved', '7057BB6BE352F947B13F3C5872F9A11B428946E2766AE2B2BC7022F2E81FD3C8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
