VALUES ('doc-09-mitre-attack-p0-2319', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious access to Microsoft Teams chat messages via eDiscovery, Graph API, or export methods after rare or compromised sign-in. Often associated with excessive file access, sensitive content review, or anomaly from expected user behavior.", "external_references": [{"external_id": "AN1566", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0567#AN1566"}], "id": "x-mitre-analytic--0c833a56-ca8e-41d8-b79a-3f3c89c63a48", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1566", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "TeamsMessagesAccessedViaEDiscovery, TeamsGraphMessageExport", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "UserLoggedIn", "name": "m365:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whether user is part of InfoSec, Legal, or expected to use Teams eDiscovery tools", "field": "UserRole"}, {"description": "Unusual country/IP sign-in patterns prior to Teams data export", "field": "GeoRiskScore"}, {"description": "Message or file threshold for triggering alert", "field": "AccessVolume"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2319', 0, 126, '09-mitre-attack', 'retrieved', '16891FF2DD4C8E5117AEE316A8586F761AC68B6ED014CF9E917E3E44D9ACE000', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
