VALUES ('doc-09-mitre-attack-p0-2320', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi shell or guest VM tools initiate external connections via scripted traffic forwarding to Internet-based proxies. Detected by firewall or shell audit logs showing outbound connection spikes from hypervisor or guest VM to remote proxy nodes.", "external_references": [{"external_id": "AN0925", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0325#AN0925"}], "id": "x-mitre-analytic--0c8a9540-51d7-4ba3-8594-8860b3fa8485", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0925", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "None", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "conn.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect when VMs communicate with Internet IPs not in workload profiles.", "field": "VMOutboundPatterns"}, {"description": "Regex for proxy-related tools/scripts executed on the host.", "field": "ProxyHostPattern"}, {"description": "Outbound only connections from ESXi to new IPs.", "field": "ConnectionDirectionality"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2320', 0, 129, '09-mitre-attack', 'retrieved', '7A7EBD066746AE2C7AF8F6E0D9842205D6B49475353980332DA108AE458B4C45', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
