VALUES ('doc-09-mitre-attack-p0-2324', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects remote writes or snapshots mounted from other systems into a central ESXi VMFS path or NFS store used for remote staging of files before exfiltration.", "external_references": [{"external_id": "AN0197", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0071#AN0197"}], "id": "x-mitre-analytic--0e2094fe-6912-4bde-9e5a-9d95c640646a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0197", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "VMFS file creation", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "NFS/remote access logs", "name": "esxi:vob", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "invoked remote scripts (esxcli)", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "How often snapshots are mounted or restored from peer nodes", "field": "SnapshotFrequency"}, {"description": "Threshold for staging behavior vs. backup/operational activity", "field": "RemoteWriteVolume"}, {"description": "Common local destinations for incoming data", "field": "StorageMountPaths"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2324', 0, 122, '09-mitre-attack', 'retrieved', '3CA2B479C26EEAD63A8F3E736EC48FB950104C