VALUES ('doc-09-mitre-attack-p0-2326', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of encoded payloads being decoded and executed in-memory using scripting tools or third-party decoders.", "external_references": [{"external_id": "AN0239", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0087#AN0239"}], "id": "x-mitre-analytic--0e832ea1-a261-4bdd-8fc8-ae049468c347", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0239", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "es_event_exec", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "memory mapping", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Encoded payload content varies across adversaries.", "field": "ScriptContent"}, {"description": "Sequence of tools or scripts executed can differ.", "field": "ExecutionChain"}, {"description": "May depend on whether user is admin, daemon, or system account.", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2326', 0, 108, '09-mitre-attack', 'retrieved', '6AAC16023C0A8DA9B605BD77D29AD04EDB9F1201E5DAEA3006EF133D4742B87E', 'v1', '{"source_id": "09-mitre-attack", "