VALUES ('doc-09-mitre-attack-p0-2327', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Suspicious process spawning (e.g., `rundll32`, `svchost`, `powershell`, or `netsh`) followed by network connection creation to internal hosts or uncommon external endpoints on high or non-standard ports.", "external_references": [{"external_id": "AN1229", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0445#AN1229"}], "id": "x-mitre-analytic--0e9add05-93bd-47b2-acf5-1817f03e804a", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1229", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Outbound Connection", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate system processes that may rarely spawn network-capable child processes (e.g., `rundll32`, `svchost`).", "field": "ParentProcessName"}, {"description": "Watch for high-numbered ports or well-known proxy ports like 1080, 8080, 4444.", "field": "DestinationPort"}, {"description": "Capture unusual spikes in outbound connections over a short period.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2327', 0, 129, '09-mitre-attack', 'retrieved', 'B987CC390F51483AC34AF4A1DF29BD402B05321ED8ACBABCE6365B298211E542', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
