VALUES ('doc-09-mitre-attack-p0-2328', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Discrepancies between VBA source code and p-code inside Office documents. Defender perspective: anomalies in file metadata streams, execution of Office processes loading macros without source code consistency, and script execution with no corresponding source metadata.", "external_references": [{"external_id": "AN0034", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0012#AN0034"}], "id": "x-mitre-analytic--0ea214f3-5d66-4170-b33d-58a6577bb074", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0034", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Expand or restrict which Office file types (.docm, .xlsm, .pptm) are flagged for VBA project analysis.", "field": "MonitoredExtensions"}, {"description": "Correlate Office process execution with subsequent script execution within a narrow window.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2328', 0, 120, '09-mitre-attack', 'retrieved', 'B86A9D9582E92D6FFB942BF168B79B4E93CA5B46F5C44CD6342F66442AD575D0', 'v1', '{"source_id": "09-mitre-attack", "version":