VALUES ('doc-09-mitre-attack-p0-2329', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of native tools or scripting (e.g., `usermod`, `passwd`, `groupmod`) to escalate permissions or persist access on existing users, correlated with login or process events.", "external_references": [{"external_id": "AN0266", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0096#AN0266"}], "id": "x-mitre-analytic--0eb6cf59-4ba8-4cea-b64a-686ce7c69f70", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0266", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "usermod, groupmod, passwd", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"channel": "/etc/passwd or /etc/group file write", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Common sudo or privilege escalation paths (e.g., `/usr/bin/passwd`).", "field": "SudoPath"}, {"description": "Detect if user shell is changed to unusual one (e.g., /bin/sh -> /bin/bash).", "field": "ModifiedShellList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2329', 0, 109, '09-mitre-attack', 'retrieved', 'C33953A94658CBF6D886D9D0C7388F69C5771139FC5F358C13421F9170C0F2E9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
