VALUES ('doc-09-mitre-attack-p0-2330', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary behavior clearing command history via `history -c`, deletion or modification of ~/.bash_history, or manipulation of the HISTFILE environment variable post-login.", "external_references": [{"external_id": "AN0467", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0165#AN0467"}], "id": "x-mitre-analytic--0ebcdeba-7b02-4f1c-96c9-a602b3663446", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0467", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "PATH", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect shell history clearing shortly after login or command execution.", "field": "TimeWindow"}, {"description": "Elevated shell sessions (e.g., root or sudo) without command history may be more suspicious.", "field": "UserContext"}, {"description": "Bash/Zsh history file paths (e.g., ~/.bash_history, ~/.zsh_history).", "field": "HistoryFilePath"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2330', 0, 113, '09-mitre-attack', 'retrieved', '2B99DF67C4CE2DA15EB21EB9367B3BA792CE36006C9F6E826F6612A31B92A0C7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v