VALUES ('doc-09-mitre-attack-p0-2333', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects suspicious USB HID device enumeration and keystroke injection patterns, such as rapid sequences of input with no user context, scripts executed through simulated keystrokes, or rogue devices presenting themselves as keyboards.", "external_references": [{"external_id": "AN1567", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0568#AN1567"}], "id": "x-mitre-analytic--0f05915c-e146-4921-840b-1a08774ca4d2", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1567", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=2003", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of known, legitimate USB vendor/product IDs authorized for use in the enterprise.", "field": "AuthorizedUSBDevices"}, {"description": "Restrict detection to times when no user is logged in or activity is outside business hours.", "field": "ExecutionTimeWindow"}, {"description": "List of legitimate parent processes expected to spawn PowerShell or scripting engines.", "field": "ParentProcessWhitelist"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2333', 0, 144, '09-mitre-attack', 'retrieved', '828CEEFB8DD08D0A55191A0C3EA779334B35E6F06D82F6C7067D7DE93E493201', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
