INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2335', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of macOS-native archiving or encryption tools (zip, ditto, hdiutil) for staging collected data. Identifies unexpected invocation of archive utilities by Office apps, browsers, or background daemons. Correlates file creation of .zip/.dmg containers with process lineage anomalies.", "external_references": [{"external_id": "AN1460", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0526#AN1460"}], "id": "x-mitre-analytic--0f4789c9-7946-473f-967b-e8ca59fa3c8c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1460", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of zip, ditto, hdiutil, or openssl by non-terminal parent processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Creation of .zip or .dmg files in user-accessible or temporary directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Business-approved applications (e.g., Time Machine, backup agents) that generate archives.", "field": "AllowedArchiveUtilities"}, {"description": "Threshold for flagging archive creation under privileged or service accounts.", "field": "UserContext"}, {"description": "Entropy threshold for detecting encrypted archives versus standard compressed files.", "field": "PayloadEntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2335', 0, 148, '09-mitre-attack', 'retrieved', '4A81633D5183160CADC84B17E47932C87E5FABBA0B373EE489A199589A73EB33', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
