VALUES ('doc-09-mitre-attack-p0-2336', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of inconsistencies between reported sensor health and actual process/service state. For example, Windows Defender tray icon/UI showing healthy status while corresponding Defender services (WinDefend, MsMpEng) are stopped or disabled. Correlates process creation events with missing or terminated security processes and spoofed health events.", "external_references": [{"external_id": "AN0868", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0311#AN0868"}], "id": "x-mitre-analytic--0f4ec296-008e-42aa-95b2-6e4e351d730c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0868", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=7036", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Monitored list of critical security service names; environment-specific.", "field": "ServiceNameList"}, {"description": "Patterns of filenames or paths mimicking Windows Security GUI elements.", "field": "FakeUIProcessPatterns"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2336', 0, 119, '09-mitre-attack', 'retrieved', '7B49D3F54F37D847396261A949FDE93AB8F104A865D7B80CF6E2D620171E056C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
