VALUES ('doc-09-mitre-attack-p0-2337', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of changes or execution of shell initialization scripts like .bashrc, .profile, or /etc/profile for persistence.", "external_references": [{"external_id": "AN0312", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0112#AN0312"}], "id": "x-mitre-analytic--0f8a0af6-7544-4f29-8e08-6b07dda1337e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0312", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EXECVE", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "PATH", "name": "auditd:PATH", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "file_events", "name": "linux:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Initialization script path that can differ across user and system profiles.", "field": "FilePath"}, {"description": "User-level vs root-level configuration.", "field": "UserContext"}, {"description": "Useful to correlate between file change and subsequent execution.", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2337', 0, 106, '09-mitre-attack', 'retrieved', 'F38E882D300ED91A874645D1A86F89A2580FFB34B103E9E9598753FA842BE967', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
