VALUES ('doc-09-mitre-attack-p0-2338', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A remote DCOM invocation by a privileged account using RPC (port 135), followed by abnormal process instantiation or module loading on the remote system indicative of code execution.", "external_references": [{"external_id": "AN0791", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0285#AN0791"}], "id": "x-mitre-analytic--0f94823c-ac95-48d8-9716-58f59d39974c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0791", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlate RPC activity with remote process creation within a configurable time window (e.g., 300s)", "field": "TimeWindow"}, {"description": "Identify rare or first-time DCOM invocations by specific accounts", "field": "UserContext"}, {"description": "List of suspicious executables commonly abused via DCOM (e.g., excel.exe, wmiprvse.exe)", "field": "ProcessName"}, {"description": "Known set of systems that should or should not be invoking DCOM activity", "field": "RemoteHostList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2338', 0, 152, '09-mitre-attack', 'retrieved', '236D7B5A257C12D0D5009D6A9553DE3D7C79B7F415E226A5250030990F53E893', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
