VALUES ('doc-09-mitre-attack-p0-2340', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects anomalous ARP cache changes and unsolicited ARP broadcasts using unified logs and packet capture. Behavioral detection includes multiple IP addresses mapped to the same MAC address and repeated gratuitous ARP traffic.", "external_references": [{"external_id": "AN1093", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0387#AN1093"}], "id": "x-mitre-analytic--0f996058-7524-4759-9d88-a8997e90ff3c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1093", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "ARP table updates inconsistent with expected gateway or DHCP lease assignments", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Excessive gratuitous ARP replies on local subnet", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known MAC addresses for gateways or DHCP servers; used to detect spoofed ARP entries.", "field": "GatewayMACBaseline"}, {"description": "How many ARP inconsistencies to tolerate before escalating detection.", "field": "CorrelationDepth"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2340', 0, 128, '09-mitre-attack', 'retrieved', 'BBDD798F240831066A6B55FDC5117650719F4A4903A62676996A070F346613DF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
