VALUES ('doc-09-mitre-attack-p0-2341', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Identify processes issuing repeated DNS queries to random-looking domains with abnormal entropy or word concatenations. Correlate resolver logs with high NXDOMAIN rates and auditd socket connections.", "external_references": [{"external_id": "AN1179", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0419#AN1179"}], "id": "x-mitre-analytic--0faa41a3-0d4c-42d1-885a-12436fbee9c1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1179", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "socket/connect", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "Multiple NXDOMAIN responses and high entropy domains", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Ratio of failed queries triggering alert (e.g., >40%)", "field": "NXDOMAINThreshold"}, {"description": "Flag queries to domains registered in last 7–30 days", "field": "DomainAge"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2341', 0, 106, '09-mitre-attack', 'retrieved', '31F22142A7887A9E877AACE7C9399B0A70C6845E716F57298B2ED1DC341C2609', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
