VALUES ('doc-09-mitre-attack-p0-2342', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors cloud function creation triggered by specific audit log events (e.g., IAM changes, object creation), followed by anomalous behavior from new service accounts.", "external_references": [{"external_id": "AN0027", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0010#AN0027"}], "id": "x-mitre-analytic--0fb1d87b-e993-447e-8a2f-e9d42f6859c0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0027", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "CreateFunction", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"channel": "InvokeFunction", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific cloud event (e.g., PutObject, CreateRole) that causes function invocation", "field": "TriggerEventType"}, {"description": "Expected permissions for roles used in function execution", "field": "ServiceAccountRole"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2342', 0, 98, '09-mitre-attack', 'retrieved', '229952A735E358FB44CB25F30D799205953D8B22B7B1793CB276E0D1EAA5577E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
