VALUES ('doc-09-mitre-attack-p0-2343', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects creation or modification of crontab entries by non-root users or from abnormal parent processes, followed by the execution of uncommon binaries at scheduled intervals.", "external_references": [{"external_id": "AN0805", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0290#AN0805"}], "id": "x-mitre-analytic--0fbbc547-37a7-4d00-a8a4-5fbcf3d27a1e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0805", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "System-specific crontab paths may vary across distros or deployments.", "field": "CronFilePath"}, {"description": "Define if only root or specific admin users are allowed to schedule jobs.", "field": "RunUser"}, {"description": "Threshold for suspicious repetition (e.g., every minute jobs).", "field": "ExecutionFrequency"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2343', 0, 115, '09-mitre-attack', 'retrieved', '893DBD165283F8301190446FC0A658F7027DCC7DEBBC923B07F216F889FBFDB7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": 