INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2345', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects execution of VB-based scripts or macros (VBS/VBA/VBScript) through cscript.exe/wscript.exe, Office-based process chains, or HTA usage. Focuses on chained behavior: Office or HTML container spawns script host > script host spawns PowerShell, network connections, or process injection.", "external_references": [{"external_id": "AN0209", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0076#AN0209"}], "id": "x-mitre-analytic--0fe7a1db-759d-4d27-8ef1-a71509643594", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0209", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Microsoft Word/Excel or mshta.exe spawning wscript.exe/cscript.exe.", "field": "ParentProcess"}, {"description": "Script execution by non-admin users or service accounts.", "field": "UserContext"}, {"description": "Script execution outside normal business hours or patching cycle.", "field": "TimeWindow"}, {"description": "High entropy indicative of obfuscation or encoding in the script.", "field": "PayloadEntropyThreshold"}, {"description": "Loading of vbscript.dll, scrrun.dll, or other scripting engine modules.", "field": "ModuleName"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2345', 0, 145, '09-mitre-attack', 'retrieved', '20D0925CE782B14205713105AFCD7E6D12A8128EECEE6EA78C9A6933EAFF4F3E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
