VALUES ('doc-09-mitre-attack-p0-2347', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor pmset command executions altering sleep/hibernate/standby parameters. Unexpected modifications to /Library/Preferences/SystemConfiguration/com.apple.PowerManagement.plist or similar files should be correlated with process activity.", "external_references": [{"external_id": "AN1176", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0417#AN1176"}], "id": "x-mitre-analytic--101d4e7f-4282-4fea-89be-e17d97ca0b91", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1176", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Process creation events where command line = pmset with arguments affecting sleep, hibernatemode, displaysleep", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "write: File modification to com.apple.PowerManagement.plist or related system preference files", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowlist expected pmset invocations by IT administrators for power policy enforcement.", "field": "AdminWhitelists"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2347', 0, 107, '09-mitre-attack', 'retrieved', 'B9B606C7BA0133FAB04AD782895419E8C97BDFD9F4522C6449B91C405168ACB3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
