VALUES ('doc-09-mitre-attack-p0-2349', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects enabling of reversible password encryption in Active Directory or Group Policy, suspicious PowerShell commands modifying AD user properties, and unusual account configuration changes correlated with policy modifications. Multi-event correlation links Group Policy edits, PowerShell command execution, and user account property changes to identify tampering with authentication encryption settings.", "external_references": [{"external_id": "AN1621", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0589#AN1621"}], "id": "x-mitre-analytic--105ca36e-c3e0-48c4-ada3-7f8c4aa4430f", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1621", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4739", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Scope of Organizational Units where reversible encryption property monitoring is enabled.", "field": "MonitoredOUs"}, {"description": "Time window in which to correlate Group Policy modification and subsequent user property changes.", "field": "TimeWindow"}, {"description": "List of PowerShell cmdlets to monitor for account configuration changes.", "field": "SuspiciousCmdletList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2349', 0, 153, '09-mitre-attack', 'retrieved', '9588DCEC4DA3EBA64AF24D164F8E51E23EF5B34206A500DBE90393E316C5A330', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
