INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2350', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abnormal invocation of diskutil or asr with destructive flags (eraseDisk, zeroDisk), or low-level IOKit calls that overwrite raw disk content. Detect correlation between elevated process execution and disk erase operations.", "external_references": [{"external_id": "AN0884", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0316#AN0884"}], "id": "x-mitre-analytic--1065ad69-8969-4ae0-9df6-dc7e7b1129c2", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0884", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "diskutil eraseDisk/zeroDisk or asr restore with destructive flags", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "IOKit raw disk write activity targeting physical devices", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Provisioning workflows may legitimately use diskutil/asr — whitelist by user or system context.", "field": "AdminToolWhitelist"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2350', 0, 111, '09-mitre-attack', 'retrieved', '9DD70F65E69C5666688BC5CEA16821FC23CFE38B581E505B4FA97E9F5AD44C0F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
