INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2352', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Process creation involving suspicious delays (e.g., Sleep, ping -n loops, WaitForSingleObject), followed by sensitive system access or lateral movement behaviors.", "external_references": [{"external_id": "AN0396", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0141#AN0396"}], "id": "x-mitre-analytic--10c89810-d298-42d6-80dd-1228e737e33f", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0396", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines maximum allowable sleep duration in milliseconds before triggering anomaly detection.", "field": "SleepDurationThreshold"}, {"description": "Temporal window between initial process and next stage (e.g., lateral movement or persistence), used to correlate dormant activity.", "field": "TimeBetweenExecutionAndNextStage"}, {"description": "Whether the activity occurs in SYSTEM or user context may affect legitimacy scoring.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2352', 0, 122, '09-mitre-attack', 'retrieved', '6F4CDF2FC60745E4C50A45F77EFA39C1BD08E239FD3A257F09CAF635B9B37365', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
