INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2353', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversary behavior where the command-line arguments of a running process are overwritten in memory to spoof the process name, typically replacing it with a benign or misleading string. The detection correlates unexpected null byte sequences, discrepancies between `/proc/ /cmdline` and process ancestry, and suspicious memory writes shortly after process start.", "external_references": [{"external_id": "AN0466", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0164#AN0466"}], "id": "x-mitre-analytic--10d8886b-6cf6-45af-b187-04541e2ffaa4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0466", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve, prctl, or ptrace activity affecting process memory or command-line arguments", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "Runtime memory overwrite of argv[] memory region", "name": "ebpf:tracepoints", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Time threshold after process creation during which argv memory manipulation is expected to be rare; anomalies occurring outside this window may be more suspicious.", "field": "TimeWindow"}, {"description": "List of known legitimate processes where argv[0] mismatch is expected due to application logic or packaging quirks.", "field": "AllowedArgvMismatchPatterns"}, {"description": "Trusted parent binaries allowed to spawn processes with altered command-line names.", "field": "ParentExecutableTrustList"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2353', 0, 179, '09-mitre-attack', 'retrieved', 'E177554844059E5E2C31A6CCF16DA5B33CD3F9934398721FE6518033F71DF378', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
