INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2354', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects use of netstat, ss, lsof, or custom shell scripts to list current network connections. Often paired with privilege escalation or staging.", "external_references": [{"external_id": "AN0904", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0320#AN0904"}], "id": "x-mitre-analytic--10dcfce8-70df-4682-ab04-90279d7292f9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0904", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "command logging", "name": "linux:cli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of binaries used for discovery (e.g., netstat, ss, lsof).", "field": "UtilityNameList"}, {"description": "Limit detection to non-administrative or service accounts performing enumeration.", "field": "UserContextScope"}, {"description": "Unusual number of executions within a short time window.", "field": "ExecutionFrequencyThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2354', 0, 111, '09-mitre-attack', 'retrieved', 'D12174008EB7BB9762478119C6F56FF9B34250C16FA0BDC584A8F93636E468A1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
