INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2355', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "User-initiated processes generating sustained outbound traffic over common or non-standard ports, often outside business hours, potentially linked to scanning or proxyjacking. Includes curl, wget, masscan, or proxy clients.", "external_references": [{"external_id": "AN0081", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0028#AN0081"}], "id": "x-mitre-analytic--10e9d109-0a17-41cd-9d0b-67c679bc94b7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0081", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve calls with high-frequency or known bandwidth-intensive tools", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "large outbound data flows or long-duration connections", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can be tuned for specific bandwidth abuse tools (e.g., proxychains, 3proxy).", "field": "ToolPattern"}, {"description": "Baseline deviation thresholds must be environment-specific.", "field": "TrafficRateThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2355', 0, 115, '09-mitre-attack', 'retrieved', '1DB852FD6780E8A13B2412899C4A040E5C768BF06D2A627AD50BC54706B0E174', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
