INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2356', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "High-frequency file write operations using uncommon extensions, followed by ransom note creation, registry tampering, or shadow copy deletion. Often uses CLI tools like vssadmin, wbadmin, cipher, or PowerShell.", "external_references": [{"external_id": "AN0602", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0215#AN0602"}], "id": "x-mitre-analytic--1155df11-eee4-4fdf-a354-15eda0e90d4c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0602", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=2", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Non-standard or randomly generated file extensions may indicate encrypted content.", "field": "FileExtension"}, {"description": "Focus on user document folders, network shares, or system paths like %System32%.", "field": "TargetFolder"}, {"description": "Correlate rapid writes and renames within seconds across high file count.", "field": "TimeWindow"}, {"description": "Flag common ransomware tools or functions (vssadmin delete shadows /all /quiet).", "field": "CommandLine"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2356', 0, 141, '09-mitre-attack', 'retrieved', '6CF9701104412B54A1E45C84FA110F9AF717BF7FCC60F4CFF7878BAD0F8A26CE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
