VALUES ('doc-09-mitre-attack-p0-2357', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects MFA bypass attempts by modifying tenant-wide authentication policies or excluding high-value accounts from MFA enforcement.", "external_references": [{"external_id": "AN0549", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0190#AN0549"}], "id": "x-mitre-analytic--1193139d-0032-4d0b-88f1-c140abe2c964", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0549", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Set-CsOnlineUser or UpdateAuthPolicy", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific tenant or suite policies tied to MFA enforcement.", "field": "MonitoredPolicies"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2357', 0, 76, '09-mitre-attack', 'retrieved', '7D35A8381343F473ADAAFF231240A16A9906A477DED143CE24372D3A5DD56735', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
