VALUES ('doc-09-mitre-attack-p0-2358', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of cron-based or script-based recurring transfers where the same script, user, or destination reappears at predictable intervals.", "external_references": [{"external_id": "AN1119", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0399#AN1119"}], "id": "x-mitre-analytic--11ac52fe-f8e0-4748-9fbc-2f85c43ad506", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1119", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "cron activity", "name": "linux:cron", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}, {"channel": "Outbound Connections", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Path patterns for shell scripts responsible for scheduled transfers", "field": "ScriptPathRegex"}, {"description": "Minimum repetition frequency (e.g., 24h for daily jobs)", "field": "CronIntervalThreshold"}, {"description": "Suspicious or unexpected users launching scheduled transfers", "field": "ExfilUserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2358', 0, 110, '09-mitre-attack', 'retrieved', '465E3B50AB4D1E23BAB62E9381A5C17FD324D1415FF3CB61CF443358554E8503', '