VALUES ('doc-09-mitre-attack-p0-2359', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection focuses on processes that attempt to locate, access, or exfiltrate local Outlook data files (.pst/.ost) using file system access, native Windows utilities (e.g., PowerShell, WMI), or remote access tools with file browsing capabilities. The behavior chain includes directory enumeration, file access, optional compression or staging, and network transfer.", "external_references": [{"external_id": "AN0130", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0047#AN0130"}], "id": "x-mitre-analytic--11cd0577-97e6-4def-a86b-fe167ae4e33d", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0130", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex or wildcard patterns for sensitive Outlook file paths (.ost/.pst) depending on organizational deployment.", "field": "TargetFilePathPattern"}, {"description": "Timeframe used to correlate related file access, process creation, and exfiltration events.", "field": "TimeWindow"}, {"description": "Limit detection to user accounts not normally interacting with Outlook file locations (e.g., service accounts, low-privileged users).", "field": "UserContext"}, {"description": "Filter known legitimate Outlook-accessing processes to reduce false positives.", "field": "ProcessAllowList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2359', 0, 179, '09-mitre-attack', 'retrieved', '6DDF78723294AAA3E4BDDDEC59CC2EBC151BDAC8B7040EF47D02C9835BF0AA3B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
