VALUES ('doc-09-mitre-attack-p0-2360', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unusual outbound DNS traffic from ESXi hosts, often from shell scripts, custom daemons, or malicious VIBs interacting with external DNS infrastructure outside the management plane.", "external_references": [{"external_id": "AN1125", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0400#AN1125"}], "id": "x-mitre-analytic--11d8dd9d-e8f3-40cd-b9fe-cc82b6c2e790", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1125", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/syslog.log", "name": "esxi:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "dns.log", "name": "NSM:FLow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Threshold for data volume and frequency from ESXi IPs", "field": "OutboundDNSVolume"}, {"description": "Baseline known packages for allowlist comparison", "field": "KnownGoodVIBs"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2360', 0, 98, '09-mitre-attack', 'retrieved', '9B38399459F4F6112132D3DF4C79DE43776DEB5DC7B71FDD680B42B7CC83E3CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
