VALUES ('doc-09-mitre-attack-p0-2361', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates LNK file execution with embedded resource extraction or suspicious network activity following initial launch, often leading to payload delivery via disguised icons.", "external_references": [{"external_id": "AN1134", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0405#AN1134"}], "id": "x-mitre-analytic--11dd0dbf-e880-43d2-99f7-4b6bf9d821fa", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1134", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=15", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can be tuned to focus on common launcher processes like explorer.exe or winword.exe.", "field": "ParentProcessName"}, {"description": "Filtered to exclude known good domains and internal IPs to reduce false positives.", "field": "DestinationIP"}, {"description": "Time between LNK execution and subsequent suspicious activity may vary based on adversary delay.", "field": "TimeWindow"}, {"description": "Could be used to focus on .lnk files only or track associated dropped payloads like .dat, .exe, etc.", "field": "FileExtension"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2361', 0, 151, '09-mitre-attack', 'retrieved', '5726FA5D5A223AE4187C98008C2753B2088D99C31B0C4A028C22B619F02D27CF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
