VALUES ('doc-09-mitre-attack-p0-2363', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of firewall ACL or rule base changes through CLI (e.g., no access-list, permit any any). Monitor configuration commits from unusual users or sessions.", "external_references": [{"external_id": "AN0410", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0145#AN0410"}], "id": "x-mitre-analytic--1216ae5e-bc5c-4672-a216-2706fb9ba3df", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0410", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "firewall disable commands or suspicious ACL modifications", "name": "networkdevice:cli", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of approved admin accounts allowed to modify firewall ACLs.", "field": "AuthorizedAdmins"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2363', 0, 89, '09-mitre-attack', 'retrieved', 'FA28769D84921F8C2EA338979F64885619CE4C38599CF347AB9FE36E91C4B1E7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
