VALUES ('doc-09-mitre-attack-p0-2365', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Processes accessing raw logical drives (e.g., \\.\\C:) to bypass file system protections or directly manipulate data structures.", "external_references": [{"external_id": "AN1193", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0426#AN1193"}], "id": "x-mitre-analytic--126a43e3-7b39-4312-ba15-aab0f7ce78f9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1193", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Regex pattern to detect access to raw disk volumes like `\\Device\\HarddiskVolume` or `\\.\\PhysicalDrive*`.", "field": "TargetObjectPattern"}, {"description": "Tune for known tools/scripts (e.g., powershell.exe, cmd.exe) often used in misuse scenarios.", "field": "ParentProcess"}, {"description": "Correlate file access and creation across a short time window to avoid false positives.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2365', 0, 116, '09-mitre-attack', 'retrieved', 'EB85CBA010E8FFBDCA5807E9132E1629F79EB28BE07D7BC1124D253E54F8C537', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
