VALUES ('doc-09-mitre-attack-p0-2366', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Web session tokens reused in native Office apps (e.g., Outlook, Teams) without associated token refresh or login behavior on the endpoint.", "external_references": [{"external_id": "AN0203", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0074#AN0203"}], "id": "x-mitre-analytic--126cff4b-4ba7-4464-bfc8-4daabed5e05b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0203", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "UserLoggedIn", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowed delta between endpoint login and cloud token reuse", "field": "EndpointTokenSyncGap"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2366', 0, 79, '09-mitre-attack', 'retrieved', '52801F654677DE92CCD30F50820F81CEB26EDB7F284628E6CA828345700FE171', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
