VALUES ('doc-09-mitre-attack-p0-2367', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary-created named mutex using system APIs (e.g., CreateMutexW) followed by conditional process termination or alternate code path indicating malware avoiding reinfection.", "external_references": [{"external_id": "AN0372", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0132#AN0372"}], "id": "x-mitre-analytic--1282f497-ce04-4151-9bd0-4eedbf4530b6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0372", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter out common benign mutex names; highlight suspicious high-entropy/dynamic names.", "field": "mutex_name_entropy_threshold"}, {"description": "Limit alerting to non-standard parent-child relationships indicative of malware staging or self-spawning.", "field": "parent_process_path"}, {"description": "Correlate mutex creation + rapid process exit or lack of further activity within a short timeframe.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2367', 0, 119, '09-mitre-attack', 'retrieved', '0D59A64F4959B99002CBAF592DA88861D14FE12CBAD33BA8AC748564E3FFC318', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
