INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2370', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A process outside of interactive shell context reads ~/.bash_history directly (e.g., using cat, less, grep), often shortly after privilege escalation or user switch (su/sudo). This may be followed by credential scanning in memory or file writes to new locations.", "external_references": [{"external_id": "AN1085", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0385#AN1085"}], "id": "x-mitre-analytic--12be6c5f-213a-464f-b780-ac06f20ab763", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1085", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/read access to ~/.bash_history", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "cat|less|grep accessing .bash_history from a non-shell process", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "write or create file after .bash_history access", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter by users with elevated privileges or service accounts", "field": "UserContext"}, {"description": "Correlate access to .bash_history within X seconds of user switch or privilege escalation", "field": "TimeWindow"}, {"description": "Add/remove CLI utilities used to read bash history", "field": "ProcessNamePatterns"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2370', 0, 150, '09-mitre-attack', 'retrieved', '23DADBE1B695A965D10A2D413EFB29CB661A0FC92D0EE0278DD19231690B8B9D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
