VALUES ('doc-09-mitre-attack-p0-2371', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of files originating from removable media after drive mount, with correlation to file write activity, autorun usage, or lateral spread via staged tools.", "external_references": [{"external_id": "AN0841", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0301#AN0841"}], "id": "x-mitre-analytic--12c748a0-3ce9-4fd2-8a65-f4362b69cafd", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0841", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1006", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Suspicious file execution on removable media path", "name": "WinEventLog:Microsoft-Windows-Windows Defender/Operational", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detect activity on mounted drives typically used by USB (e.g., E:, F:, G:). Tune based on enterprise usage.", "field": "DriveLetterMatch"}, {"description": "Set timing threshold for execution shortly after drive mount (e.g., < 5 minutes).", "field": "FileExecutionWindow"}, {"description": "Restrict detection to suspicious process lineage like explorer.exe, powershell.exe, or unsigned binaries.", "field": "ParentProcess"}, {"description": "Use entropy thresholding to detect packed/obfuscated payloads dropped to removable media.", "field": "FileEntropy"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2371', 0, 160, '09-mitre-attack', 'retrieved', '0237F04EF967376EC6629DA49E72D5D2D7D70D5C0DB18BB4E7A83F5F9629ED18', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
