VALUES ('doc-09-mitre-attack-p0-2373', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor Mail.app activity or unified logs for anomalous SMTP usage, including mismatches between display name and authenticated AppleID or Exchange credentials. Detect use of third-party mail utilities that attempt to send on behalf of corporate identities.", "external_references": [{"external_id": "AN0794", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0286#AN0794"}], "id": "x-mitre-analytic--1305f37f-8333-4d86-9714-340b66c65771", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0794", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Mail.app or third-party clients sending messages with mismatched From headers", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowlist known third-party clients used for legitimate email activity.", "field": "TrustedMailClients"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2373', 0, 102, '09-mitre-attack', 'retrieved', '16F0ED9E1BAFE8689F9A687C549BDAFA92525F0D5C3FE2BD6D05083132B9A2B0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
