VALUES ('doc-09-mitre-attack-p0-2374', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Access token reuse to connect to SharePoint or Outlook APIs without interactive user context.", "external_references": [{"external_id": "AN0959", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0338#AN0959"}], "id": "x-mitre-analytic--1313533a-06c7-44ea-8d75-9a23d3ea23cc", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0959", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "TokenIssued, FileAccessed", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tune to detect access from CLI agents or scripts rather than interactive browsers", "field": "UserAgentCheck"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2374', 0, 77, '09-mitre-attack', 'retrieved', '0F118CDB8B34BCD86D27794934F4F8C7E84640936BBC7306C53C3C30D0B583B6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
