VALUES ('doc-09-mitre-attack-p0-2375', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects osascript, curl, or custom binaries interacting with XMPP/MQTT brokers in unapproved destinations with encrypted payloads or frequent POST-like requests to broker URIs.", "external_references": [{"external_id": "AN0004", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0002#AN0004"}], "id": "x-mitre-analytic--131d3f89-e10d-4ac9-a9d0-fcb4e8e8760a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0004", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream ''eventMessage contains pubsub or broker''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "socket_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Applications not known to use pub/sub protocols", "field": "AppContextFilter"}, {"description": "Custom path patterns to message brokers over HTTPS", "field": "URIPathRegex"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2375', 0, 101, '09-mitre-attack', 'retrieved', 'A5ABEC935B480CFBD16DD3DE09E3B9D7E742ECA7CC08103F8404E26694FD6CE0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
