VALUES ('doc-09-mitre-attack-p0-2376', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects escalation via vulnerable setuid binaries or kernel modules, often chained with unusual access to /proc/kallsyms or /dev/kmem.", "external_references": [{"external_id": "AN1420", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0514#AN1420"}], "id": "x-mitre-analytic--1327b96f-73db-4a5e-8e71-e515fc030bf3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1420", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ACCESS", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "dmesg", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate SUID binaries vary across distributions; false positives may arise.", "field": "SetUIDBinaryList"}, {"description": "Allows chaining kernel module load with privilege spike or privilege-sensitive process activity.", "field": "TimeWindow"}, {"description": "Default is uid=0, but environments may vary with containerized root-like accounts.", "field": "EffectiveUIDThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2376', 0, 117, '09-mitre-attack', 'retrieved', 'A2302B1EBE445E71C6CB23DE484D5ED4B848CF91BED20D423A97FA539067CF8C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
