VALUES ('doc-09-mitre-attack-p0-2377', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Shell utilities or scripts deleting `/etc/systemd/system/rescue.target`, `/etc/fstab` backups, or `/boot/efi` partitions; chattr used to block snapshot auto-recovery", "external_references": [{"external_id": "AN0934", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0329#AN0934"}], "id": "x-mitre-analytic--135452f6-c760-42a6-8a3f-d09c33f05369", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0934", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "chattr, rm, shred, dd run on recovery directories or partitions", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "/etc/fstab, /etc/systemd/*", "name": "auditd:CONFIG_CHANGE", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Modify to include specific OS backup configs or LVM snapshots", "field": "WatchedFilePaths"}, {"description": "Restrict detection to root or sudo users", "field": "ShellProcessUser"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2377', 0, 101, '09-mitre-attack', 'retrieved', 'E0DBBCF1916A8D7F91574AB79735E426E6F70DFF53C2FC9BE78A1C1E047B7F91', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
