VALUES ('doc-09-mitre-attack-p0-2378', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Login attempt failures over SNMP, Telnet, or SSH interface, often reflected in logs or syslog events", "external_references": [{"external_id": "AN1525", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0551#AN1525"}], "id": "x-mitre-analytic--13556e3f-80f0-4aac-83f0-0d6c706e76ff", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1525", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "login failed", "name": "networkdevice:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specify monitoring of Telnet/SSH/SNMP for login activity", "field": "InterfaceType"}, {"description": "How many failures in short succession should trigger alerting", "field": "FailedAttemptThreshold"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2378', 0, 85, '09-mitre-attack', 'retrieved', 'DA32282AD708B1BF616B27F9E7D447D3F2218BD2826041AB32AE538D8B360451', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
