INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2380', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi hypervisor permission modification behavioral chain: (1) SSH access to ESXi host, (2) chmod/chown execution on VMFS datastore files or system configuration, (3) Modification of VM configuration files (.vmx) or virtual disk permissions, (4) Hostd service log correlation, (5) vCenter permission change events if centrally managed", "external_references": [{"external_id": "AN0837", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0299#AN0837"}], "id": "x-mitre-analytic--13a1653f-3d4e-4a4f-9619-f8e8a97ec60d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0837", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "shell command execution for chmod, chown, or file permission modification on VMFS or system files", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "host daemon events related to file or VM permission changes", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"channel": "permission change operations on datastores or VMs", "name": "esxi:vpxd", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "ESXi user accounts authorized for shell access and file system operations", "field": "AuthorizedSSHUsers"}, {"description": "VMFS datastore paths requiring permission change monitoring", "field": "CriticalVMFSPaths"}, {"description": "Time correlation window for linking SSH access with permission modifications", "field": "ShellAccessTimeWindow"}, {"description": "Scope of vCenter audit event correlation with ESXi host activities", "field": "vCenterIntegrationScope"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2380', 0, 182, '09-mitre-attack', 'retrieved', '4077C4433638225252D4981D25E96C8785325A8E0F7F74015772D0817102556B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
