INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2382', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detect manipulation of system or application files in `/Library`, `/System`, or user data directories using FSEvents and Unified Logs. Identify anomalous process execution modifying plist files, structured data, or logs outside expected update cycles.", "external_references": [{"external_id": "AN0164", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0059#AN0164"}], "id": "x-mitre-analytic--13f8d339-8239-4d84-adf2-1abf1a0f3d5d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0164", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Anomalous plist modifications or sensitive file overwrites by non-standard processes", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "open, execve: Unexpected processes accessing or modifying critical files", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Whitelisted processes authorized to modify plist or configuration files.", "field": "AllowedPlistEditors"}, {"description": "Baseline hash values for key files to support integrity validation.", "field": "FileIntegrityBaseline"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2382', 0, 127, '09-mitre-attack', 'retrieved', '00C9B2EC1B2570B51A40EC07E3E225B56BD7B01A3486A55D7D57F5F00D9D5260', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
