VALUES ('doc-09-mitre-attack-p0-2383', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors for TCC-bypassing or unauthorized access to input services like IOHIDSystem or Quartz Event Services used in keylogging or screen monitoring.", "external_references": [{"external_id": "AN0284", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0102#AN0284"}], "id": "x-mitre-analytic--13f8fd10-3982-4a10-85c1-4641712c7286", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0284", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "subsystem=com.apple.TCC", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"channel": "launchd or process_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "com.apple.accessibility, com.apple.quartz, etc. depending on the API path used", "field": "Service"}, {"description": "Unusual parent/child pairings can indicate malicious injection", "field": "ParentProcess"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2383', 0, 96, '09-mitre-attack', 'retrieved', '4ABB1045E4CA35C095D31721331AFB132299A101644B2D5B341894440A3EB746', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
