VALUES ('doc-09-mitre-attack-p0-2384', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Repeated failed SSH login attempts followed by a possible success from the same remote host", "external_references": [{"external_id": "AN1522", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0551#AN1522"}], "id": "x-mitre-analytic--14390641-6cba-4351-a488-bf97c6eee8a7", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1522", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "sshd[pid]: Failed password", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can be tuned to non-standard ports if SSH is moved from default", "field": "PortScope"}, {"description": "Filter high-value or restricted users (e.g., root, service)", "field": "UserScope"}, {"description": "Number of consecutive failures before flagging (e.g., >5 in 2 minutes)", "field": "AttemptThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2384', 0, 102, '09-mitre-attack', 'retrieved', '2E01303BBADC414397982637EEF5023AF2EB889BA0358A66C60397E0634A3AFB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
