INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2385', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects the relocation of malicious executables via copy/move actions across suspicious folders (e.g., from Downloads to System32), followed by deletion of the original source or renaming to blend into legitimate binaries.", "external_references": [{"external_id": "AN1216", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0439#AN1216"}], "id": "x-mitre-analytic--143f3057-237e-427f-911a-2aa7d64721f0", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1216", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=23", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Patterns like \\Windows\\*, \\System32\\*, or temp+execution directories", "field": "SuspiciousTargetPathRegex"}, {"description": "Correlate copy+rename+delete chains within 5-minute window", "field": "TimeWindow"}, {"description": "Limit to .exe, .dll, .js, .bat unless context suggests otherwise", "field": "FileExtensionFilter"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2385', 0, 114, '09-mitre-attack', 'retrieved', '74E3295651B2723DA141234AEB0054D0ACA7EF90A2D12499570900065AFCADB9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
