VALUES ('doc-09-mitre-attack-p0-2386', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of ping, traceroute, or network utility tools to external destinations; may include `scutil` or system_profiler.", "external_references": [{"external_id": "AN1017", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0357#AN1017"}], "id": "x-mitre-analytic--1443f662-d249-4458-b8fe-2c2da7b64569", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1017", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Rare use of ICMP utilities may be tuned based on user/host baselines", "field": "ExecutionFrequency"}, {"description": "Tune data joins with parent process and user activity context", "field": "EnrichmentLevel"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2386', 0, 89, '09-mitre-attack', 'retrieved', 'D3DC5989958CC42CF68D1CCBB59BF558CBB66693C5ED398C18D68BADB4676409', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
