VALUES ('doc-09-mitre-attack-p0-2389', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unexpected inbound or outbound VNC/SSH/Screen Sharing connections from external sources → repeated failed logins followed by success → remote interactive sessions or abnormal file transfers.", "external_references": [{"external_id": "AN1006", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0354#AN1006"}], "id": "x-mitre-analytic--14f4930e-a2a5-45ae-9552-837c0a35e06b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1006", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Remote login (ssh) or screen sharing authentication attempts", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "Inbound connections to VNC/SSH ports", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "External traffic to remote access services", "name": "PF:Logs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of approved VNC/SSH sources.", "field": "KnownVNCServers"}, {"description": "Time correlation between failed attempts and success.", "field": "TimeWindow"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2389', 0, 116, '09-mitre-attack', 'retrieved', '7617817B4D97A36846FAD4D4494FD1AF9CA1A08869E006CCA8DFE66A0FDC3AB9', '