VALUES ('doc-09-mitre-attack-p0-2390', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unusual outbound file transfer behavior using protocols like FTP, SMB, SMTP, or DNS, involving non-standard processes, off-hour activity, or uncommonly high volume.", "external_references": [{"external_id": "AN0367", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0131#AN0367"}], "id": "x-mitre-analytic--1543bc4a-7614-417a-85b9-d67e3da0350c", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0367", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Set threshold for outbound volume (e.g., >50MB in a single connection).", "field": "DataVolumeThresholdMB"}, {"description": "Allow-listed protocols in use for specific machines or users (e.g., FTP allowed for backups).", "field": "ProtocolAllowList"}, {"description": "Define allowed time-of-day windows (e.g., flag after-hours file transfer).", "field": "TimeWindow"}, {"description": "Identify anomalous parent-child process relationships (e.g., `winword.exe` spawning `ftp.exe`).", "field": "ParentProcessAnomaly"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2390', 0, 136, '09-mitre-attack', 'retrieved', '6C9813A9242122A923533FDF9617A882FBFEBC08E30E44E81FF66C23F82ED0EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
