VALUES ('doc-09-mitre-attack-p0-2391', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Correlates creation/modification of systemd service files or /etc/init.d scripts with outlier process behavior during boot", "external_references": [{"external_id": "AN0765", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0274#AN0765"}], "id": "x-mitre-analytic--156387d6-9b9a-49f8-834a-cf3cd5ede09c", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0765", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "creat", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "write", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Execution of binaries located in /etc/init.d/ or systemd service paths", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Organizations may use different init systems or custom startup paths", "field": "FilePath"}, {"description": "Autostart scripts should run as root or system users; deviations are suspect", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2391', 0, 109, '09-mitre-attack', 'retrieved', 'EE3FDDA00314C4F7314DC0CC866C5A8B5DE964B04058337162ADACE085F7D0F0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_