VALUES ('doc-09-mitre-attack-p0-2392', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Flooding tools like hping3 or nping sending large volumes of packets across multiple ports or IPs", "external_references": [{"external_id": "AN1435", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0518#AN1435"}], "id": "x-mitre-analytic--1578f892-0644-4974-bf55-9abb802612fa", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1435", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of network stress tools or anomalies in socket/syscall behavior", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "High volume flows with incomplete TCP sessions or single-packet bursts", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Packets per second beyond normal behavior", "field": "PacketRateThreshold"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2392', 0, 94, '09-mitre-attack', 'retrieved', '58D082412C818A34DC0889611A73FAC8CA35F5E65B57C47F3256F4B773131B49', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
