VALUES ('doc-09-mitre-attack-p0-2393', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Execution of `esxcli system hostname get`, `esxcli system version get`, or `esxcli hardware` commands through SSH or local shell.", "external_references": [{"external_id": "AN1455", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0525#AN1455"}], "id": "x-mitre-analytic--164a04c5-db61-477f-b3fa-8bf806631fbb", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1455", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/vmkernel.log", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Track SSH or console-based entry points.", "field": "SessionOrigin"}, {"description": "Customize detection for expected CLI queries.", "field": "CommandString"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2393', 0, 82, '09-mitre-attack', 'retrieved', '4F4E31DC2CDBAE10527AA5E20774C7B0C33AE6B0307BC0E5CABCA08B39767123', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
