VALUES ('doc-09-mitre-attack-p0-2394', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects unusual command executions and service modifications that indicate self-patching or disabling of vulnerable services post-compromise. Defenders should monitor for service stop commands, suspicious process termination, and execution of binaries or scripts aligned with known patching or service management tools outside of expected admin contexts.", "external_references": [{"external_id": "AN0045", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0015#AN0045"}], "id": "x-mitre-analytic--16e57a41-f305-4aa7-9125-15272052419e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0045", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=5", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable list of critical or vulnerable services that defenders want to monitor for unexpected disabling.", "field": "ServiceList"}, {"description": "Defines correlation window (e.g., 5–15 minutes) between suspicious command execution and subsequent process termination.", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2394', 0, 131, '09-mitre-attack', 'retrieved', '410EEF4A7A954A01D7DF3A76ED3F7C52185223079F730242665F44A74F5F2521', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
