VALUES ('doc-09-mitre-attack-p0-2395', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects usage of FTP, SCP, or TFTP by non-interactive shells or automation scripts transferring large data volumes to untrusted IPs.", "external_references": [{"external_id": "AN1170", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0416#AN1170"}], "id": "x-mitre-analytic--170e84e2-fa22-4e8c-b2f3-3cafc0d96d7e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1170", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "ftp.log, conn.log", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Bytes sent in FTP upload or SCP push", "field": "TransferSizeThreshold"}, {"description": "e.g., scp -r /var/log/* or ftp upload scripts", "field": "CommandLinePatternMatch"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2395', 0, 94, '09-mitre-attack', 'retrieved', '7142985008E3AACF2C70F3C886C905ABBD4BCD993EA8411D4284A4EF41E72CB7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
