VALUES ('doc-09-mitre-attack-p0-2396', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A non-standard process (or script-hosted process) loads camera/video-capture libraries (e.g., avicap32.dll, mf.dll, ksproxy.ax), opens the Camera Frame Server/device, writes video/image artifacts (e.g., .mp4/.avi/.yuv) to unusual locations, and optionally initiates outbound transfer shortly after.", "external_references": [{"external_id": "AN0568", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0197#AN0568"}], "id": "x-mitre-analytic--171803bb-8aa7-42df-861a-18d6d694f909", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0568", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"channel": "Process session start/stop events for camera pipeline by unexpected executables", "name": "WinEventLog:Microsoft-Windows-Windows Camera Frame Server/Operational", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Correlation window (e.g., 0–20 minutes) between device access, file creation, and egress.", "field": "TimeWindow"}, {"description": "Known legitimate camera consumers (e.g., Teams.exe, zoom.exe, obs64.exe) to suppress.", "field": "AllowedProcesses"}, {"description": "List of extensions to flag (.mp4, .avi, .mov, .yuv, .mkv, .h264) – tune for your estate.", "field": "VideoExtensions"}, {"description": "Regex for unusual storage locations (e.g., %TEMP%\\*, C:\\Windows\\Tasks\\*, user profile hidden dirs).", "field": "RarePathRegex"}, {"description": "Minimum size to reduce FP from thumbnails/snapshots.", "field": "MinFileSizeMB"}, {"description": "Service/agent parents permitted to broker camera access.", "field": "ParentProcessAllowList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2396', 0, 205, '09-mitre-attack', 'retrieved', '5C79C7B1C63719502C36126F52BF21039C7828E7A48D25BEDF42B7C5D999431D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
