VALUES ('doc-09-mitre-attack-p0-2397', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary sends crafted HTTP/S (or other service) input to an Internet-facing app (IIS/ASP.NET, API, device portal). Chain: (1) abnormal request patterns to public endpoint → (2) elevated 4xx/5xx or unusual methods/paths → (3) server process (w3wp.exe/other service) spawns shell/LOLbins or loads non-standard modules → (4) optional outbound callback from the host/container.", "external_references": [{"external_id": "AN0219", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0080#AN0219"}], "id": "x-mitre-analytic--17290910-5b25-477a-a0c0-c2661ff2585e", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0219", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "IIS W3C logs in C:\\inetpub\\logs\\LogFiles\\W3SVC* (spikes in 5xx, RCE/SQLi/path traversal/JNDI patterns)", "name": "ApplicationLog:IIS", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of public IPs/hostnames that front apps; used to scope web log and Zeek/proxy data.", "field": "PublicVIPs"}, {"description": "Regex set for exploit-like inputs (../, union select, cmd=, ${jndi:, rO0AB (Java serialization), %00, ${env:}, ${${::-j}ndi}).", "field": "SuspiciousPatterns"}, {"description": "Spike threshold for HTTP status 5xx/4xx per client or URI (e.g., >5 in 5m).", "field": "ErrorRateThreshold"}, {"description": "Correlation horizon between request, error, process spawn, and egress (e.g., 15 minutes).", "field": "TimeWindow"}, {"description": "Known child processes of app pools (e.g., msbuild.exe in CI) to reduce false positives.", "field": "AllowedChildList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2397', 0, 211, '09-mitre-attack', 'retrieved', 'D00C790C2A990E4477BC4ED6393DE88872F7CA31DB1F21FA8E6CBBCD164DDB1F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
