VALUES ('doc-09-mitre-attack-p0-2398', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects removal of adversary artifacts via `rm`, `unlink`, or secure tools, with focus on shell sessions, temp files, and modified LaunchAgents or system directories.", "external_references": [{"external_id": "AN0394", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0140#AN0394"}], "id": "x-mitre-analytic--175bf607-fca6-4555-a30b-3d6cd4cfe876", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0394", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "unlink, write", "name": "fs:fsusage", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "process", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Focus on LaunchAgents, /tmp/, or user folders.", "field": "FilePathRegex"}, {"description": "Detecting use of unfamiliar tools by common users.", "field": "ToolUsageAnomaly"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2398', 0, 97, '09-mitre-attack', 'retrieved', 'DC0E5B9CC027F9CD53CD551299F60C3C9CCA843739E01E4536D4E77772826C11', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
