VALUES ('doc-09-mitre-attack-p0-2400', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects adversarial abuse of WMI to execute local or remote commands via WMIC, PowerShell, or COM API through a multi-event chain: process creation, command execution, and corresponding network connection if remote.", "external_references": [{"external_id": "AN1031", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0364#AN1031"}], "id": "x-mitre-analytic--17687fa0-bfbf-4ff2-9eb0-520538e6af31", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1031", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=5857, 5858, 5860, 5861", "name": "WinEventLog:WMI", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Restrict detection scope to suspicious WMI namespaces like `\\root\\cimv2`, `\\root\\subscription`.", "field": "WMIQueryScope"}, {"description": "Set maximum allowable time window to correlate WMI process creation and remote connections.", "field": "TimeWindow"}, {"description": "Tune based on interactive vs. system-level execution (e.g., via SYSTEM or low-privileged users).", "field": "UserContext"}, {"description": "Number of unique remote hosts contacted using WMI within a time window.", "field": "RemoteDestinationThreshold"}, {"description": "Regex patterns to identify adversary-like usage (e.g., `wmic process call`, `powershell Invoke-WmiMethod`).", "field": "SuspiciousCommandPatterns"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2400', 0, 167, '09-mitre-attack', 'retrieved', '0CB3357341FAADD744EA77E7F90E8F0AE4746727DBD86A2BE63C90585C0D3900', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
