INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2401', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abnormal API calls from user accounts invoking file upload endpoints outside normal baselines (M365, Google Drive, Box). Defender perspective: monitor unified audit logs for elevated frequency of Upload, Create, or Copy operations from compromised accounts.", "external_references": [{"external_id": "AN1514", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0548#AN1514"}], "id": "x-mitre-analytic--177bb119-93cc-4319-b9a7-e8d308d958c4", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1514", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "FileUploaded or FileCopied events", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "API calls exceeding baseline thresholds", "name": "saas:box", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Maximum number of API calls per user/session before triggering alert.", "field": "APICallThreshold"}, {"description": "Baseline normal data transfer patterns by user/role.", "field": "UserBaselineProfiles"}], "x_mitre_platforms": ["SaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2401', 0, 116, '09-mitre-attack', 'retrieved', 'BA4F6A010EF9ACEC17898949EBF0A12C6B16C57695C62B61CAA87A7FBA115F88', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
