INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2402', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects exploitation targeting ESXi/vCenter by correlating attempts to reach known exploitable endpoints (OpenSLP 427, CIM 5989, Hostd/Vpxa HTTPS 443, ESXi SOAP) with vmkernel/hostd crashes, unexpected hostd/vpxa restarts, or new reverse/outbound connections from ESXi host/vCenter to internal assets.", "external_references": [{"external_id": "AN0329", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0118#AN0329"}], "id": "x-mitre-analytic--17b82342-cc75-4dcd-ad98-f313cd2a2b69", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0329", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Keywords: ''Backtrace'',''Signal 11'',''PANIC'',''hostd restarted'',''assert'' or ''Service terminated unexpectedly'' in /var/log/hostd.log, /var/log/vmkernel.log, /var/log/syslog.log.", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "Inbound to tcp/427 (OpenSLP), tcp/443 (vSphere APIs), tcp/902, tcp/5989 followed by new unexpected outbound sessions from the ESXi/vCenter host.", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "427, 443, 902, 5989; modify per version/hardening.", "field": "ESXiServicePorts"}, {"description": "Legit management networks for vCenter/ESXi.", "field": "MgmtCIDRs"}, {"description": "Crash/restart patterns to match in logs.", "field": "RestartKeywords"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2402', 0, 144, '09-mitre-attack', 'retrieved', '822783FD215C87BC772AF17F0C70EC1DF785AA7E91F03B25F9308CC1F0E50B22', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
