INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2403', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Malicious VBA macros embedded in base templates like Normal.dotm or Personal.xlsb are automatically loaded and executed at startup. Template path may be hijacked to load a remote or attacker-controlled template via GlobalDotName registry setting.", "external_references": [{"external_id": "AN1437", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0519#AN1437"}], "id": "x-mitre-analytic--17bc7c97-7322-4619-84c5-50e45aa6627d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1437", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Set-Mailbox, Set-MailboxPolicy, Set-TrustedLocation", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Macros may be embedded in local user templates or retrieved from shared network paths", "field": "TemplateSource"}, {"description": "Macro execution policy (disabled, warn, enabled) varies by tenant or user configuration", "field": "MacroSecurityLevel"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2403', 0, 114, '09-mitre-attack', 'retrieved', 'FA97DE4267FFD5E384A35964D294DF11594A89F968EC288F8CF21822242CD31C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2404', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defender observes configuration changes on firewall/network appliance involving rule creation, modification, or deletion from abnormal management IPs or non-console channels (e.g., remote CLI, API). These are often correlated with a spike in previously blocked outbound traffic, unexpected allow-all rules, or bulk rule deletions. Behavior often follows unauthorized login, privilege escalation, or API abuse.", "external_references": [{"external_id": "AN0855", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0306#AN0855"}], "id": "x-mitre-analytic--17ce541a-23fa-4b33-affc-c6ba906e9956", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0855", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "update_rule: Access control or NAT rule modified or disabled outside maintenance window", "name": "networkdevice:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"channel": "Login from untrusted IP, or new admin account accessing firewall console/API", "name": "networkdevice:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "Audit trail or CLI/API access indicating commands like no access-list, delete rule-set, clear config", "name": "networkdevice:Firewall", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "Outbound traffic spike through formerly blocked ports/subnets following config change", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Allowlisted IPs/subnets where administrative access is expected (e.g., jump box, VPN mgmt)", "field": "TrustedAdminIPs"}, {"description": "Expected maintenance window (e.g., 02:00–04:00 UTC) to filter benign changes", "field": "ConfigChangeWindow"}, {"description": "Number of rules affected or port ranges modified to determine severity", "field": "RuleScopeThreshold"}, {"description": "Flag new users making changes without observed privilege elevation path", "field": "NewUserPrivilegeThreshold"}], "x_mitre_platforms": ["Network Devices"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2404', 0, 215, '09-mitre-attack', 'retrieved', '8B217517C35972E701EA75E84E8927B09BF5249F6BA181E63B52152AC6292CA2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
