VALUES ('doc-09-mitre-attack-p0-2406', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors for compression tool usage (e.g., 7zip, WinRAR, MakeCab) that follows or precedes file modification, suspicious file types (e.g., .exe, .dll) being compressed, or dropped from self-extracting archives followed by immediate execution.", "external_references": [{"external_id": "AN0782", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0281#AN0782"}], "id": "x-mitre-analytic--18253101-bce9-453e-ab03-603bbd174552", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0782", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Zip, .rar, .cab, .gz – tune based on expected legitimate use of compression in environment", "field": "CompressedFileType"}, {"description": "Expected time between archive unpacking and first execution – short delays are suspicious", "field": "SFXExecutionDelay"}, {"description": "Restrict detection to non-admin or interactive users if excessive FPs from sys admin activity", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2406', 0, 134, '09-mitre-attack', 'retrieved', '277686FF9D59183CB6C2B33F29BBCF2B539DEB66175B1EA0A7F8A39D41189920', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
