VALUES ('doc-09-mitre-attack-p0-2407', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "User pastes a multi-line or one-liner into a terminal (bash/zsh) that downloads/decodes and executes content. Chain: terminal exec of curl/wget/bash/sh with pipe to interpreter or base64-decode → transient file under /tmp|~/.cache → immediate outbound egress.", "external_references": [{"external_id": "AN0963", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0340#AN0963"}], "id": "x-mitre-analytic--1895e723-dcfb-45d4-80fc-aaa0c3963cc9", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0963", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve: exe in (/usr/bin/bash,/usr/bin/sh,/usr/bin/zsh,/usr/bin/python*) AND cmdline matches ''(curl|wget).*(\\||\\|\\s*sh|bash)|base64\\s*-d|python\\s*-c''", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "open: File creation under /tmp, /var/tmp, ~/.cache with executable bit or shell shebang", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "New egress to Internet by the same UID/host shortly after terminal exec", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Gui/tty terminals to monitor (gnome-terminal, konsole, iTerm2, tmux).", "field": "TerminalProcessNames"}, {"description": "Temp/cache paths to watch for first-stage drops.", "field": "RiskyFilePaths"}, {"description": "Users who should never run curl/wget or compilers.", "field": "AnomalousUserSet"}, {"description": "Exec→file→egress correlation window (e.g., 10 minutes).", "field": "TimeWindow"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2407', 0, 163, '09-mitre-attack', 'retrieved', '809435C143F68418A955EB7165FB352ACED1559407D65665A65392632C132801', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
