VALUES ('doc-09-mitre-attack-p0-2408', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of suspicious access to password manager processes (KeePass, 1Password, LastPass, Bitwarden) through abnormal process injection, memory reads, or command-line usage of vault-related DLLs. Correlates process creation with OS API calls and file access to vault databases (.kdbx, .opvault, .ldb).", "external_references": [{"external_id": "AN1641", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0597#AN1641"}], "id": "x-mitre-analytic--18ab8a54-68bc-4d43-884d-2b9284eb723e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1641", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=10", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "EventCode=15", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of monitored binaries and file formats for password managers in use (e.g., KeePass, 1Password, Bitwarden, LastPass).", "field": "PasswordManagerBinaries"}, {"description": "Window to correlate process creation, API access, and file reads indicative of credential extraction.", "field": "TimeWindow"}, {"description": "Filter for administrative accounts vs. expected users of password managers.", "field": "UserContext"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2408', 0, 147, '09-mitre-attack', 'retrieved', '5DF088540A2732D0CADDCA71705D9EE735948EB1424C1D44ECDD3B6941CDE629', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
