INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2410', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Analyze ESXi syslogs for management agents or VMs making outbound connections to dynamically calculated ports derived from DNS responses. Cross-check with VM traffic baselines to identify anomalies.", "external_references": [{"external_id": "AN0731", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0262#AN0731"}], "id": "x-mitre-analytic--18c20664-b820-4a14-a7bf-5a75ac2fae92", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0731", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "DNS resolution events leading to outbound traffic on unexpected ports", "name": "esxi:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Known trusted ESXi management plane IPs to exclude from alerts", "field": "ManagementPlaneIPs"}, {"description": "Integrate external feeds for reputation context on DNS-derived domains", "field": "DomainReputationFeed"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2410', 0, 106, '09-mitre-attack', 'retrieved', '7F953913D1FCEDBB4D9EF3EA97F42DE0F7462318C3E050A933A86F4AAC12B2EB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
