VALUES ('doc-09-mitre-attack-p0-2411', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects invocation of macOS-native archiving utilities (zip, ditto, hdiutil) or openssl used for encryption. Correlates execution with archive or encrypted file creation (.zip, .dmg, .tar.gz) in user or temporary directories. Identifies anomalous use of archiving commands by Office applications or daemons.", "external_references": [{"external_id": "AN0833", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0298#AN0833"}], "id": "x-mitre-analytic--18cf5cf7-f46b-4258-a0aa-503881c9c88e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0833", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Execution of zip, ditto, hdiutil, or openssl by processes not normally associated with archiving", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Creation of .zip, .dmg, .tar.gz files in /Users, /tmp, or application directories", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Business-approved applications permitted to create archives (e.g., backup agents).", "field": "AllowedArchivers"}, {"description": "Flag archiving under privileged or service accounts as higher risk.", "field": "UserContext"}, {"description": "Entropy threshold for detecting encrypted archives versus normal compression.", "field": "PayloadEntropyThreshold"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2411', 0, 153, '09-mitre-attack', 'retrieved', '6D7B3D787B12BA822427B132E8DD958A4A1F3E17A9951DE6CBAB63EC165A0A24', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
