VALUES ('doc-09-mitre-attack-p0-2413', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Unusual use of steganographic or media processing binaries (e.g., `steghide`, `ffmpeg`, `imagemagick`) followed by outbound communication to external IPs with high data output and media MIME types.", "external_references": [{"external_id": "AN0652", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0235#AN0652"}], "id": "x-mitre-analytic--191d5ea7-ff08-4433-ba1b-1c0ed755ca67", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0652", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Captured File Content", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"channel": "Observed File Transfers", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specify which binaries to monitor (e.g., steghide, outguess).", "field": "ToolNameMatch"}, {"description": "Adjust based on known normal file upload services.", "field": "OutboundTrafficPattern"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2413', 0, 110, '09-mitre-attack', 'retrieved', '5D842C94D27ED973DE0458C38938FB1D8F69748F51593BE589ED801DCA68AA56', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
