INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2415', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Defenders should monitor for anomalous or unauthorized changes to cloud compute configurations that alter quotas, tenant-wide policies, subscription associations, or allowed deployment regions. From a defender’s perspective, suspicious behavior chains include a sudden increase in compute quota requests followed by new instance or resource creation, policy modifications that weaken security restrictions, or enabling previously unused/unsupported cloud regions. Correlation across identity, configuration, and subsequent provisioning logs is critical to distinguish legitimate administrative activity from adversarial abuse.", "external_references": [{"external_id": "AN1356", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0492#AN1356"}], "id": "x-mitre-analytic--193f0293-0a53-430f-83c0-a69d0663479a", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1356", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "RequestServiceQuotaIncrease", "name": "AWS:CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Identity performing the quota or configuration change; tuned to filter known admins or automation accounts.", "field": "UserContext"}, {"description": "Correlation period for configuration change followed by resource creation; tuned to environment norms.", "field": "TimeWindow"}, {"description": "Type of configuration being modified (quota, policy, region); tuned to organization-specific risk thresholds.", "field": "ChangeType"}, {"description": "Region where the configuration change originates; tuned to enterprise’s expected operational geography.", "field": "GeoLocation"}], "x_mitre_platforms": ["IaaS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2415', 0, 185, '09-mitre-attack', 'retrieved', '47801E17D2B40E0CD5098634C482A6A7ABF7CAE1DDF20E61F4B9F1AC42197BD0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
