VALUES ('doc-09-mitre-attack-p0-2416', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects removable drive insertion followed by unusual file access, compression, or staging activity by unauthorized users or unexpected processes.", "external_references": [{"external_id": "AN0342", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0123#AN0342"}], "id": "x-mitre-analytic--198d4196-25f0-4e28-a95b-c89709f452ab", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0342", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=4663, 4670, 4656", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "EventCode=1006, 10001", "name": "WinEventLog:System", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Filter on removable (e.g., USB) drives only.", "field": "DriveTypeFilter"}, {"description": "Exclude known, approved backup or sync utilities.", "field": "ProcessNameExclusionList"}, {"description": "Limit correlation of file access and device mount to a defined window (e.g., <5 minutes).", "field": "TimeWindow"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2416', 0, 123, '09-mitre-attack', 'retrieved', '0707A25A33226CEE1A2F1F681AE6188CA9DEA14428EBC7CD91F6B4769A58850B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
