INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-2417', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Discovery of SaaS services connected to productivity platforms (e.g., Microsoft 365, Google Workspace). Defender perspective includes unexpected enumeration of enabled services, API integrations, or OAuth applications tied to user accounts.", "external_references": [{"external_id": "AN1129", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0402#AN1129"}], "id": "x-mitre-analytic--19b6de3a-032f-4dc8-aa72-7cd952dfed59", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1129", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Get-MsolServicePrincipal, ListAppRoles: Service discovery operations executed by accounts not normally performing administrative tasks", "name": "m365:unified", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"channel": "UserLogin: Discovery operations shortly after account logins from new geolocations", "name": "m365:signinlogs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Specific Office Suite applications or plugins that may be enumerated or targeted.", "field": "MonitoredAppIntegrations"}, {"description": "Geographic deviation threshold for discovery actions linked to recent logins.", "field": "GeoLocationDeviation"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2417', 0, 131, '09-mitre-attack', 'retrieved', '3A255ED6FD98E336AB2DF037511F467FEC6D9ACD356E39CB6A7CE29AB06C7FE0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
