VALUES ('doc-09-mitre-attack-p0-2418', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitor for creation of WMI EventFilter, EventConsumer, and FilterToConsumerBinding objects through WMI or MOF file execution. Detect command-line execution of `mofcomp.exe`, usage of `Register-WmiEvent` via PowerShell, and anomalous child processes of `WmiPrvSE.exe` that indicate triggered execution. Look for lateral anomalies in process lineage and WMI logging channels.", "external_references": [{"external_id": "AN0236", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0086#AN0236"}], "id": "x-mitre-analytic--1a0640f0-e286-405f-9ab3-507c1abb77da", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 0236", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=5857, 5858, 5860, 5861", "name": "WinEventLog:WMI", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Defines temporal correlation range between WMI creation and child process execution", "field": "TimeWindow"}, {"description": "Tune for specific accounts (e.g., SYSTEM or attacker-controlled users)", "field": "UserContext"}, {"description": "Used to exclude known benign consumers triggered via WMI (e.g., backup tools)", "field": "ProcessNameAllowlist"}, {"description": "Defines what constitutes anomalous spawning from WmiPrvSE.exe", "field": "ParentProcessAnomalyThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2418', 0, 158, '09-mitre-attack', 'retrieved', '62C1ECC63373C6FF28AF45A8FF1CB7FCEB95BD716E8D8260F7E762734CB60291', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
