VALUES ('doc-09-mitre-attack-p0-2420', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection of unauthorized keylogger behavior through access to `/dev/input`, loading kernel modules (e.g., via insmod), or polling user input devices from non-user shells", "external_references": [{"external_id": "AN0688", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0246#AN0688"}], "id": "x-mitre-analytic--1a13d795-7c26-44b6-ad1b-2ad732dc33c3", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0688", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "syscalls (open, read, ioctl) on /dev/input or /proc/*/fd/*", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"channel": "dmesg or syslog for module loads", "name": "linux:syslog", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Can tune based on device paths accessed for keyboard input (e.g., /dev/input/event0)", "field": "PathTarget"}, {"description": "Exclude root or admin-auth shell sessions if needed", "field": "UserContext"}, {"description": "Set a known list of allowed kernel modules", "field": "ModuleWhitelist"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2420', 0, 123, '09-mitre-attack', 'retrieved', '1E7D97DA725A58BC7ADFBE5FC9CDD00A7EFD868B0626700C4FC4EB56B4F99143', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
