VALUES ('doc-09-mitre-attack-p0-2421', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An SMB-based remote file share access followed by lateral movement actions such as remote service creation, task scheduling, or suspicious process execution on the target host using ADMIN$ or C$ shares.", "external_references": [{"external_id": "AN1468", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0530#AN1468"}], "id": "x-mitre-analytic--1a18402e-efb1-49c7-8615-dc907f838320", "modified": "2025-11-12T22:03:39.105Z", "name": "Analytic 1468", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=4624, 4648", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Targeted admin share path, such as C$, ADMIN$, IPC$", "field": "ShareName"}, {"description": "Correlation window between remote file access and remote execution (e.g., 5-10 minutes)", "field": "TimeWindow"}, {"description": "Distinguish expected remote administrators vs. rare/first-time access by specific users", "field": "UserContext"}, {"description": "List of suspicious binaries or tools executed post remote copy (e.g., cmd.exe, powershell.exe, runonce.exe)", "field": "ProcessList"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2421', 0, 147, '09-mitre-attack', 'retrieved', 'C23D8B9179FE29F9EF93B706CA2EC545B857EB30E1154553115F7FBEE83F1E81', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
