VALUES ('doc-09-mitre-attack-p0-2422', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects custom archiving by monitoring execution of Swift/Objective-C apps or scripts producing high-entropy files with non-standard headers. Correlates unified logs of abnormal NSFileHandle/NSData operations, memory use of XOR/bitwise operations, and file creation events.", "external_references": [{"external_id": "AN1215", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0438#AN1215"}], "id": "x-mitre-analytic--1a39005f-28e7-4b07-85e2-14ffa0f6ea3b", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1215", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Suspicious Swift/Objective-C or scripting processes writing archive-like outputs", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "Creation of files with anomalous headers and entropy values", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "Abnormal memory operations (XOR/bitwise loops) during archive generation", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Flag if archiving occurs under privileged/system accounts.", "field": "UserContext"}, {"description": "Entropy score cutoff for identifying custom compressed or encrypted files.", "field": "EntropyThreshold"}, {"description": "Applications legitimately using custom archiving for business purposes.", "field": "AllowedApps"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2422', 0, 146, '09-mitre-attack', 'retrieved', 'DBF9D53483B2388029919E36DFA746570DF981B817617C59B1000E5EE3DE63CC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
