VALUES ('doc-09-mitre-attack-p0-2423', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Access to container image layers or mounted secrets (e.g., Docker secrets) by processes not tied to entrypoint or orchestration context.", "external_references": [{"external_id": "AN1158", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0412#AN1158"}], "id": "x-mitre-analytic--1a68a39c-c4e3-4ff1-88f5-db78575ce15e", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1158", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "read of /run/secrets or docker volumes by non-entrypoint process", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"channel": "unusual process spawned from container image context", "name": "containerd:Events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Container entrypoints that are permitted to read secrets", "field": "EntrypointAllowlist"}, {"description": "Paths to credentials/secrets inside container images", "field": "VolumeMountPath"}], "x_mitre_platforms": ["Containers"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2423', 0, 105, '09-mitre-attack', 'retrieved', '917BB64F9BBC8A4E50AD8DDB89F4209F07FC608C2ADA63641092BE0162633535', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
