VALUES ('doc-09-mitre-attack-p0-2424', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Abnormal use of `lsblk`, `fdisk -l`, `lshw -class disk`, or `parted` by non-admin users or within non-interactive shells suggests suspicious disk enumeration activity.", "external_references": [{"external_id": "AN0537", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0188#AN0537"}], "id": "x-mitre-analytic--1a7052d7-84f1-4116-bdb1-49bbe8709e3d", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0537", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "execve call with argv matching known disk enumeration commands (lsblk, parted, fdisk)", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "command line arguments containing lsblk, fdisk, parted", "name": "auditd:EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Detection can exclude interactive TTY sessions to reduce false positives from admin usage", "field": "TTY_type"}, {"description": "Differentiate between interactive user shells vs. script-based execution", "field": "shell_parent"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2424', 0, 118, '09-mitre-attack', 'retrieved', '40BEB8451D176D03B6FD7ED83BA8929D2873AF36718AB097DD4BCC70A8EBD3E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
