VALUES ('doc-09-mitre-attack-p0-2426', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-23T18:08:03.334Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detection identifies execution of scripts or files that appear visually benign (low printable character ratio) but result in runtime decoding, dynamic evaluation, and subsequent process or network activity. Correlation links script execution with abnormal Unicode density and follow-on behavior such as child process creation or outbound connections.", "external_references": [{"external_id": "AN2063", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0920#AN2063"}], "id": "x-mitre-analytic--1a9f097a-d5b9-424d-ae20-19ed73eb9dcf", "modified": "2026-04-24T20:31:04.803Z", "name": "Analytic 2063", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "revoked": false, "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "EventCode=3, 22", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"channel": "EventCode=1", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4688", "name": "WinEventLog:Security", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "EventCode=4103, 4104, 4105, 4106", "name": "WinEventLog:PowerShell", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"channel": "EventCode=11", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "EventCode=7", "name": "WinEventLog:Sysmon", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "To tune for atypical virtual memory allocations that might indicate non-rendering characters in dense files", "field": "AllocationSizeThreshold"}, {"description": "Allows tuning for atypical processes from script execution (e.g., powershell.exe, wscript.exe, mshta.exe)", "field": "ExecutionContext"}, {"description": "Tune for invisible characters, or atypical amounts of Unicode characters (U+...)", "field": "UnicodeDensityThreshold"}], "x_mitre_platforms": ["Windows"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2426', 0, 175, '09-mitre-attack', 'retrieved', '5F7723E35D38F371D7093EE443B8049D0DCD6E9D021A7B30DA99CAC614710994', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
