VALUES ('doc-09-mitre-attack-p0-2427', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adversary compromises a Linux-based web server and modifies hosted web files by exploiting upload vulnerabilities, remote code execution, or replacing index.html via SSH/webshell.", "external_references": [{"external_id": "AN1623", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0590#AN1623"}], "id": "x-mitre-analytic--1affb8e9-25b4-49c1-b290-687e9696fa83", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1623", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "open/write syscalls targeting web directory files", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"channel": "Successful sudo or ssh from unknown IPs", "name": "NSM:Connections", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "Suspicious POSTs to upload endpoints", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "May differ (e.g., /var/www/html, /srv/http, etc.)", "field": "web_root"}, {"description": "Adversary content hash may change across campaigns", "field": "payload_hash"}, {"description": "Can range from apache/nginx user to root if escalated", "field": "UserContext"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2427', 0, 126, '09-mitre-attack', 'retrieved', '38B1657B7010FC01CA957E457BFEE5FE842104B7A7C74798D710BF233D61C213', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
