VALUES ('doc-09-mitre-attack-p0-2429', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of leaked credential pairs against Outlook Web Access (OWA), Microsoft 365, or Exchange from a single client IP with multiple failures", "external_references": [{"external_id": "AN1269", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0460#AN1269"}], "id": "x-mitre-analytic--1b3bbeab-2000-47d6-88f9-8ed519f9bed6", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1269", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "Logon failure", "name": "m365:exchange", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Optional: cross-reference to haveibeenpwned or internal credential dumps", "field": "PasswordSourceMatch"}, {"description": "Tunable value for how many unique mailbox attempts trigger alert", "field": "MailboxLoginThreshold"}], "x_mitre_platforms": ["Office Suite"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2429', 0, 93, '09-mitre-attack', 'retrieved', '4EE448DEFE2C16A1CD1B62F5D9D0A883A53C034FFB5531C7682BD52453193CF6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
