VALUES ('doc-09-mitre-attack-p0-2430', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "ESXi shell (BusyBox) or VMware utilities (openssl, python if present) used to Base64/hex encode data from datastore or config files → followed by abnormal egress from the host (NSX/flow logs) with asymmetric bytes_out or HTTPS posts to non-management endpoints.", "external_references": [{"external_id": "AN0348", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0124#AN0348"}], "id": "x-mitre-analytic--1b53dd1b-c98e-4b25-a7fd-70dad586ebf1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0348", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "commands containing base64, openssl enc -base64, xxd -p", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "unexpected script/command invocations via hostd", "name": "esxi:hostd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"channel": "network_flow: bytes_out >> bytes_in to external", "name": "NSX:FlowLogs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"channel": "http: Base64/MIME looking payloads from ESXi host IP", "name": "NSM:Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "CIDRs for legitimate vCenter/NSX/backup endpoints.", "field": "MgmtCIDRs"}, {"description": "Out:In ratio deemed suspicious (e.g., ≥3 on ESXi).", "field": "BytesRatio"}, {"description": "Correlation window between shell command and egress.", "field": "TimeWindow"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2430', 0, 154, '09-mitre-attack', 'retrieved', 'D656463FF6F5C87B42DDD025B4DC52DE503720686F678393044D86CB631428FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
