VALUES ('doc-09-mitre-attack-p0-2431', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Creation of run-only AppleScripts or Mach-O binaries lacking symbol table and string references, especially when dropped by user space scripting engines or staging apps.", "external_references": [{"external_id": "AN0057", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0019#AN0057"}], "id": "x-mitre-analytic--1b5b9ee8-69e6-41d4-a529-aa18afcdf453", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 0057", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "file write", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "name": "macos:endpointsecurity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"channel": "code_signing, file_metadata", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "AppleScript flag to disable reverse engineering (run-only compiled scripts)", "field": "RunOnlyFlag"}, {"description": "Filter to isolate staging or suspicious scripting engines", "field": "ParentProcess"}, {"description": "Tuning based on unsigned vs. developer-signed payloads", "field": "SignedStatus"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2431', 0, 116, '09-mitre-attack', 'retrieved', 'EA94DCA5