VALUES ('doc-09-mitre-attack-p0-2432', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "SSH login via hostd or `/var/log/auth.log`, followed by CLI access to host shell or file manipulation in restricted areas.", "external_references": [{"external_id": "AN1640", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0596#AN1640"}], "id": "x-mitre-analytic--1b6eaec8-141f-44f8-ae1f-387c44635c38", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1640", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "None", "name": "esxi:auth", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"channel": "None", "name": "esxi:shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "port 22 access", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Legitimate SSH users to this host", "field": "AllowedUsers"}, {"description": "Correlate SSH login and unauthorized commands or shell access", "field": "TimeWindow"}, {"description": "Flag commands like esxcli, rm, chmod post-login", "field": "CommandList"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2432', 0, 109, '09-mitre-attack', 'retrieved', 'E2BB58F2AC1C7B6FA779EDA34C50C8C842C396FE7E0253F2EAF6D1538CE37613', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowled