VALUES ('doc-09-mitre-attack-p0-2433', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors for hardware or firmware tampering by correlating system boot logs, hardware inventory changes, and secure boot/firmware verification failures. Behavioral chain: (1) UEFI/BIOS version drift; (2) secure boot disabled or signature verification errors; (3) unexpected modules or hardware devices enumerated at boot; (4) new device firmware images loaded from non-approved sources.", "external_references": [{"external_id": "AN1036", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0368#AN1036"}], "id": "x-mitre-analytic--1c25310b-d8fa-472d-a10e-c327a8fba693", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1036", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "firmware_update, kexec_load", "name": "auditd:SYSCALL", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"channel": "Firmware updates applied or failed", "name": "fwupd:logs", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "List of SHA256/SHA512 firmware hashes allowed.", "field": "ApprovedFirmwareHashes"}, {"description": "Known hardware component IDs per host baseline.", "field": "AllowedDeviceIDs"}], "x_mitre_platforms": ["Linux"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2433', 0, 126, '09-mitre-attack', 'retrieved', 'CBC91D97E477D1FC4506D26354B99940A2915672BAC6B595864C1157E769D127', 