VALUES ('doc-09-mitre-attack-p0-2434', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Monitors use of archive or encryption tools (zip, openssl) tied to user-scripted activity or binaries writing encoded payloads under /Users or /Volumes.", "external_references": [{"external_id": "AN1066", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0378#AN1066"}], "id": "x-mitre-analytic--1c2e527f-b9ff-4e1d-896d-0c1257f0abc1", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1066", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "log stream --predicate ''processImagePath contains \"zip\" OR \"base64\"''", "name": "macos:unifiedlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"channel": "file_events", "name": "macos:osquery", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Tunable to identify uncommon or encrypted file formats (e.g., .enc, .b64, .xz)", "field": "FilenameExtensionList"}, {"description": "Tune to prioritize unexpected file access by service accounts", "field": "UserContext"}], "x_mitre_platforms": ["macOS"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2434', 0, 107, '09-mitre-attack', 'retrieved', 'E96482D2A5D0448BE402245CB6DAEBC2823177699906CFCAE3ADC08331CF37DE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
