VALUES ('doc-09-mitre-attack-p0-2435', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T15:10:28.402Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Detects abuse of busybox commands (e.g., `touch`) or log timestamp tampering during backdoor persistence or evasion.", "external_references": [{"external_id": "AN1629", "source_name": "mitre-attack", "url": "https://attack.mitre.org/detectionstrategies/DET0591#AN1629"}], "id": "x-mitre-analytic--1c3cb010-1c22-40c8-92d3-52e31353ad92", "modified": "2025-10-21T15:10:28.402Z", "name": "Analytic 1629", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "spec_version": "2.1", "type": "x-mitre-analytic", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_domains": ["enterprise-attack"], "x_mitre_log_source_references": [{"channel": "/var/log/vmkernel.log", "name": "esxi:vmkernel", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}], "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "x_mitre_mutable_elements": [{"description": "Unusual backdating to match legit files", "field": "TimestampAgeComparison"}, {"description": "Overlap with known persistence paths", "field": "PersistenceOverlap"}], "x_mitre_platforms": ["ESXi"], "x_mitre_version": "1.0"}', 'kb-doc-09-mitre-attack-p0-2435', 0, 78, '09-mitre-attack', 'retrieved', '31543C84BB05A28ADF80A67A1E23BC45679658B44C9D8B43799369934A39A5E4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
